window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch02"]={"id": "ch02", "title": "第二章 染色体与DNA", "sub": "朱玉贤《现代分子生物学》第5版 · 教师课件逐页详解", "sub2": "染色质 · DNA · 基因 · 基因组 · 染色体", "modules": [{"i": 0, "name": "模块一：染色质、染色体与基因的概念", "slides": [{"i": 0, "sec": "染色质、染色体与基因的概念", "title": "模块一内容导览 (p2)", "notes": "本页给出模块一的知识框架：DNA的结构与物理化学性质、基因的概念与分类/结构特征/功能、基因组（细菌与真核生物）、染色体与核小体。学习时应把握“DNA→基因→基因组→染色体”的层次递进关系：DNA是遗传信息的化学载体，基因是其中具有功能意义的序列单位，基因组是一个生物全部遗传信息的总和，而染色体（染色质）则是DNA在细胞内的组织与包装形式。", "page": 2, "level": "了解", "img": "assets/img/ch02/p002.jpg", "anim": null, "fig": null, "points": ["模块一知识框架：DNA结构/性质→基因概念/分类/结构/功能→基因组（细菌与真核）→染色体与核小体", "层次递进关系：DNA（化学载体）→基因（功能序列单位）→基因组（全部遗传信息）→染色体（组织包装形式）", "考点：基因是DNA上具有功能意义的序列单位，基因组是生物全部遗传信息的总和", "考点：染色体/染色质是DNA在细胞内的组织与包装形式"], "check": {"q": "关于模块一的知识框架，下列哪项最符合“DNA→基因→基因组→染色体”的层次递进关系？", "o": ["A. DNA是遗传信息的化学载体，基因是其中具有功能意义的序列单位，基因组是一个生物全部遗传信息的总和，染色体是DNA在细胞内的组织与包装形式", "B. 基因是遗传信息的化学载体，DNA是其中具有功能意义的序列单位，染色体是一个生物全部遗传信息的总和，基因组是DNA在细胞内的组织与包装形式", "C. 染色体是遗传信息的化学载体，基因组是其中具有功能意义的序列单位，DNA是一个生物全部遗传信息的总和，基因是DNA在细胞内的组织与包装形式", "D. 基因组是遗传信息的化学载体，染色体是其中具有功能意义的序列单位，DNA是一个生物全部遗传信息的总和，基因是DNA在细胞内的组织与包装形式"], "a": "A", "e": "讲义明确：DNA是遗传信息的化学载体，基因是其中具有功能意义的序列单位，基因组是一个生物全部遗传信息的总和，染色体（染色质）则是DNA在细胞内的组织与包装形式。"}, "cards": [{"front": "模块一的知识框架包含哪几部分？其层次递进关系是什么？", "back": "包含：DNA的结构与物理化学性质、基因的概念与分类/结构特征/功能、基因组（细菌与真核生物）、染色体与核小体。层次递进：DNA→基因→基因组→染色体。", "mnemonic": "DNA是载体，基因是单位，基因组是总和，染色体是包装", "useImg": false}, {"front": "染色质与染色体是什么关系？", "back": "二者是同一物质在不同细胞周期阶段的不同存在形式：间期多为伸展的染色质，分裂期凝缩为染色体，均以DNA为基本遗传物质。", "mnemonic": "间期染色质，分裂期染色体，同物不同态", "useImg": false}]}, {"i": 1, "sec": "染色质、染色体与基因的概念", "title": "基因的概念与功能产物 (p3)", "notes": "1909年Johannsen提出“基因”一词，用以指代决定遗传性状的“遗传因子”。现代分子生物学将基因定义为：合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。若最终产物是多肽，基因信息需经转录和翻译表达为蛋白质，再体现生理功能；若最终产物是RNA，则该RNA本身即具结构、催化、识别或调控等功能，无需翻译。此定义强调基因是“功能单位”，而非仅是一段可读框。", "page": 3, "level": "掌握", "img": "assets/img/ch02/p003.jpg", "anim": null, "fig": null, "points": ["1909年Johannsen提出“基因”一词，指决定遗传性状的遗传因子", "现代定义：基因是合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列", "基因通常为DNA序列，RNA病毒中为RNA", "最终产物为多肽时：经转录和翻译表达为蛋白质再体现生理功能", "最终产物为RNA时：RNA本身即具结构、催化、识别或调控等功能，无需翻译；强调基因是功能单位"], "check": {"q": "根据现代分子生物学对基因的定义，下列哪项最准确？", "o": ["A. 基因是决定遗传性状的“遗传因子”，由Johannsen于1909年提出", "B. 基因是合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）", "C. 基因是一段可读框，其最终产物必须是蛋白质", "D. 基因是DNA分子上任意一段能够转录的序列，其功能产物只能是RNA"], "a": "B", "e": "现代分子生物学将基因定义为：合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。A是历史名词，C、D均不准确。"}, "cards": [{"front": "谁在1909年提出了“基因”一词？其最初含义是什么？", "back": "Johannsen于1909年提出，用以指代决定遗传性状的“遗传因子”。", "mnemonic": "Johannsen—基因命名者", "useImg": false}]}, {"i": 2, "sec": "染色质、染色体与基因的概念", "title": "染色质、染色体与DNA、核酸的关系 (p4)", "notes": "DNA即脱氧核糖核酸，通常泛指某一生物体内全部脱氧核糖核酸；核酸则是DNA与RNA的总称。在真核细胞中，DNA并非裸露存在，而是与组蛋白等结合形成染色质；细胞分裂时染色质高度折叠压缩成染色体。因此，染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式：间期多为伸展的染色质，分裂期则凝缩为染色体，二者均以DNA为基本遗传物质。", "page": 4, "level": "掌握", "img": "assets/img/ch02/p004.jpg", "anim": null, "fig": null, "points": ["DNA即脱氧核糖核酸，通常泛指某一生物体内全部脱氧核糖核酸", "核酸是DNA与RNA的总称", "真核细胞中DNA并非裸露存在，而是与组蛋白等结合形成染色质", "细胞分裂时染色质高度折叠压缩成染色体", "染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式：间期多为伸展的染色质，分裂期凝缩为染色体，二者均以DNA为基本遗传物质"], "check": {"q": "关于真核细胞中DNA、染色质与染色体的关系，下列哪项正确？", "o": ["A. DNA与RNA的总称是核酸；真核细胞中DNA通常与组蛋白等结合形成染色质，细胞分裂时染色质高度折叠压缩成染色体", "B. 染色质与染色体是两种不同的遗传物质，染色质含DNA，染色体含RNA", "C. 真核细胞中DNA以裸露形式存在，染色质和染色体只是形态描述，与DNA包装无关", "D. 核酸仅指DNA；染色质存在于分裂期，染色体存在于间期"], "a": "A", "e": "讲义指出：核酸是DNA与RNA的总称；真核细胞中DNA并非裸露存在，而是与组蛋白等结合形成染色质；细胞分裂时染色质高度折叠压缩成染色体。染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式。"}, "cards": [{"front": "现代分子生物学对“基因”的定义是什么？", "back": "合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。", "mnemonic": "基因=一条多肽或RNA所需的全部序列", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_1", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "根据现代分子生物学定义，基因是指：", "o": ["A. 一段能编码蛋白质的DNA序列", "B. 合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列", "C. 染色体上能被染色的区域", "D. 生物体内全部DNA的总和"], "a": "B", "e": "基因的现代定义强调其最终功能产物可以是有功能的多肽或RNA分子，因此编码RNA的序列也属于基因；A只涵盖编码蛋白质的基因，D描述的是基因组。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_2", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "关于染色质与染色体的关系，正确的是：", "o": ["A. 染色质和染色体是两种不同的遗传物质", "B. 染色质只存在于原核细胞，染色体只存在于真核细胞", "C. 染色质和染色体是同一物质在细胞周期不同阶段的不同存在形式", "D. 染色体由RNA和蛋白质组成，染色质由DNA和蛋白质组成"], "a": "C", "e": "真核细胞中，DNA与组蛋白等结合形成染色质，分裂期高度折叠压缩形成染色体，二者化学本质相同，只是形态和包装程度不同。", "kp": "ch02_s0_2"}, {"id": "ch02_mcq_3", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "下列哪项不是基因最终功能产物的可能形式？", "o": ["A. 具有催化功能的RNA", "B. 具有调控功能的RNA", "C. 具有结构功能的多肽", "D. 直接作为遗传密码的脱氧核糖"], "a": "D", "e": "基因的功能产物可以是有功能的多肽或RNA分子；脱氧核糖是DNA的组成成分，不是基因表达的功能产物。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_4", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "“核酸”这一术语的正确含义是：", "o": ["A. 仅指DNA", "B. 仅指RNA", "C. DNA和RNA的总称", "D. 指所有含氮碱基"], "a": "C", "e": "核酸是脱氧核糖核酸（DNA）和核糖核酸（RNA）的总称，DNA和RNA都是核酸的具体类型。", "kp": "ch02_s0_2"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "基因是合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列。", "a": "对", "e": "这是现代分子生物学对基因的定义，强调基因是功能单位，最终产物可为多肽或RNA。", "kp": "ch02_s0_1"}, {"id": "ch02_judge_2", "modI": 0, "q": "染色质与染色体是两种完全不同的物质。", "a": "错", "e": "染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式：间期多为伸展的染色质，分裂期则凝缩为染色体，二者均以DNA为基本遗传物质。", "kp": "ch02_s0_2"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "1909年，Johannsen提出“________”一词，用以指代决定遗传性状的“遗传因子”。", "a": "基因", "kp": "ch02_s0_1"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述基因的现代分子生物学定义及其功能产物类型。", "a": "定义：合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。功能产物类型：①若最终产物是多肽，基因信息需经转录和翻译表达为蛋白质，再体现生理功能；②若最终产物是RNA，则该RNA本身即具结构、催化、识别或调控等功能，无需翻译。该定义强调基因是“功能单位”，而非仅是一段可读框。", "kp": "ch02_s0_1"}], "calc": [], "term": [{"id": "ch02_term_1", "modI": 0, "term": "Gene", "def": "基因：合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。要点：①1909年Johannsen提出“基因”一词；②强调功能单位，而非仅一段可读框；③最终产物可为多肽或RNA；④若产物为多肽，需经转录和翻译；⑤若产物为RNA，则该RNA本身即具结构、催化、识别或调控等功能。", "kp": "ch02_s0_1"}, {"id": "ch02_term_2", "modI": 0, "term": "Chromatin", "def": "染色质：真核细胞中DNA与组蛋白等结合形成的复合物。要点：①间期多为伸展的染色质；②细胞分裂时高度折叠压缩成染色体；③染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式；④均以DNA为基本遗传物质。", "kp": null}]}, {"i": 1, "name": "模块二：DNA的一级与二级结构", "slides": [{"i": 0, "sec": "DNA的结构", "title": "DNA概述 (p5)", "notes": "本页作为“DNA”部分的引入，提示接下来将系统讨论DNA的化学组成与空间结构。DNA是遗传信息的载体，其结构决定复制、转录与修复等基本生命过程。理解DNA结构需从一级结构（核苷酸序列）与二级结构（双螺旋）两个层次展开。", "page": 5, "level": "了解", "img": "assets/img/ch02/p005.jpg", "anim": null, "fig": null, "points": ["DNA是遗传信息的载体，其结构决定复制、转录与修复等基本生命过程", "DNA结构需从一级结构（核苷酸序列）与二级结构（双螺旋）两个层次理解", "本页为DNA部分的引入，提示后续系统讨论DNA的化学组成与空间结构"], "check": {"q": "关于DNA结构层次的理解，下列哪项最符合本页观点？", "o": ["A. DNA结构只需从双螺旋层次理解，一级序列不影响其功能", "B. DNA是遗传信息载体，其结构可从一级结构与二级结构两个层次展开", "C. DNA的化学组成与空间结构无关，复制和转录不依赖其结构", "D. DNA只决定转录过程，与复制和修复无直接关系"], "a": "B", "e": "本页指出DNA是遗传信息载体，理解其结构需从一级结构（核苷酸序列）与二级结构（双螺旋）两个层次展开，并联系复制、转录与修复等过程。"}, "cards": [{"front": "DNA结构应从哪两个层次理解？", "back": "一级结构（核苷酸序列）与二级结构（双螺旋）。", "mnemonic": "先看字母顺序，再看螺旋形状", "useImg": false}]}, {"i": 1, "sec": "DNA的结构", "title": "DNA结构总览 (p6)", "notes": "本页以《Molecular Biology of the Cell》Figure 4-3为引，概括DNA结构研究的经典框架：从核苷酸单体、磷酸二酯键连接形成多核苷酸链，再到两条链反向平行、碱基互补配对形成双螺旋。该图通常展示DNA从化学结构到双螺旋模型的层次关系，是后续各页知识点的总纲。", "page": 6, "level": "理解", "img": "assets/img/ch02/p006.jpg", "anim": null, "fig": "该图通常从核苷酸单体开始，展示磷酸二酯键连接形成多核苷酸链，再展示两条反向平行的链通过碱基互补配对形成双螺旋。看图时按“单体→链→双螺旋”的层次逐级理解。", "points": ["DNA结构研究的经典框架：核苷酸单体→磷酸二酯键连接→多核苷酸链→两条链反向平行、碱基互补配对形成双螺旋", "该图展示DNA从化学结构到双螺旋模型的层次关系，是后续知识点的总纲", "理解DNA结构需把握从单体到多聚体、从一级到二级的递进关系"], "check": {"q": "本页以经典框架概括DNA结构研究，通常不包括下列哪一层次？", "o": ["A. 核苷酸单体", "B. 磷酸二酯键连接形成多核苷酸链", "C. 两条链反向平行并碱基互补配对形成双螺旋", "D. 蛋白质四级结构的亚基排列"], "a": "D", "e": "本页概括的是从核苷酸单体、磷酸二酯键连接、多核苷酸链到反向平行双螺旋的DNA结构层次；蛋白质四级结构不属于DNA结构框架。"}, "cards": [{"front": "DNA四种碱基分别属于哪类？", "back": "嘌呤：A、G（双环）；嘧啶：C、T（单环）。", "mnemonic": "嘌双嘧单；A/G嘌呤，C/T嘧啶", "useImg": false}]}, {"i": 2, "sec": "DNA的结构", "title": "碱基类型：嘌呤与嘧啶 (p7)", "notes": "DNA含四种碱基：嘌呤类的腺嘌呤（A）和鸟嘌呤（G），嘧啶类的胞嘧啶（C）和胸腺嘧啶（T）。嘌呤为双环结构，嘧啶为单环结构。A与T、G与C通过氢键互补配对，使两条链在序列上互为模板，这是DNA复制与信息传递的化学基础。", "page": 7, "level": "掌握", "img": "assets/img/ch02/p007.jpg", "anim": null, "fig": null, "points": ["DNA含四种碱基：嘌呤类的腺嘌呤（A）和鸟嘌呤（G），嘧啶类的胞嘧啶（C）和胸腺嘧啶（T）", "嘌呤为双环结构，嘧啶为单环结构", "A与T、G与C通过氢键互补配对，使两条链在序列上互为模板", "碱基互补配对是DNA复制与信息传递的化学基础"], "check": {"q": "下列关于DNA碱基类型的叙述，正确的是：", "o": ["A. A和G是嘧啶，C和T是嘌呤", "B. A和G是嘌呤，C和T是嘧啶", "C. A、T、G、C均为嘌呤", "D. A、T、G、C均为嘧啶"], "a": "B", "e": "DNA中腺嘌呤A和鸟嘌呤G属于嘌呤类，胞嘧啶C和胸腺嘧啶T属于嘧啶类；嘌呤为双环结构，嘧啶为单环结构。"}, "cards": [{"front": "DNA中碱基如何互补配对？各形成几个氢键？", "back": "A与T配对，形成2个氢键；G与C配对，形成3个氢键。", "mnemonic": "A-T两键，G-C三键", "useImg": false}]}, {"i": 3, "sec": "DNA的结构", "title": "RNA与DNA核苷酸的差异 (p8)", "notes": "RNA与DNA的核苷酸主要有两点不同：一是RNA含核糖（2′-OH），DNA含脱氧核糖；二是RNA用尿嘧啶（U）替代DNA中的胸腺嘧啶（T）。U与A同样能配对，但T比U多一个甲基，有利于DNA的稳定性和修复识别。这些差异决定了RNA更易折叠、更易降解，而DNA更适合长期储存遗传信息。", "page": 8, "level": "掌握", "img": "assets/img/ch02/p008.jpg", "anim": null, "fig": null, "points": ["RNA含核糖（2′-OH），DNA含脱氧核糖", "RNA用尿嘧啶（U）替代DNA中的胸腺嘧啶（T）", "U与A同样能配对，但T比U多一个甲基，有利于DNA的稳定性和修复识别", "这些差异决定了RNA更易折叠、更易降解，而DNA更适合长期储存遗传信息"], "check": {"q": "RNA与DNA核苷酸的主要差异是：", "o": ["A. RNA含脱氧核糖，DNA含核糖", "B. RNA用胸腺嘧啶T，DNA用尿嘧啶U", "C. RNA含核糖并用U替代T，DNA含脱氧核糖并用T", "D. RNA和DNA的糖相同，只是碱基配对方式不同"], "a": "C", "e": "RNA含核糖（2′-OH），DNA含脱氧核糖；RNA用尿嘧啶U替代DNA中的胸腺嘧啶T。T比U多一个甲基，有利于DNA稳定性和修复识别。"}, "cards": [{"front": "RNA与DNA的核苷酸有哪两点主要差异？", "back": "①RNA含核糖（2′-OH），DNA含脱氧核糖；②RNA用U替代DNA中的T。", "mnemonic": "RNA有氧有U，DNA脱氧有T", "useImg": false}]}, {"i": 4, "sec": "DNA的结构", "title": "核苷酸的形成：糖苷键与磷酸酯键 (p9)", "notes": "核苷酸由碱基、戊糖和磷酸组成。碱基与戊糖通过糖苷键（N-糖苷键）连接形成核苷，核苷再与磷酸通过磷酸酯键连接形成核苷酸，过程中伴随脱水。糖苷键和磷酸酯键是核酸一级结构中两类关键共价键，决定了链的骨架组成与方向性。", "page": 9, "level": "掌握", "img": "assets/img/ch02/p009.jpg", "anim": null, "fig": null, "points": ["核苷酸由碱基、戊糖和磷酸组成", "碱基与戊糖通过糖苷键（N-糖苷键）连接形成核苷", "核苷再与磷酸通过磷酸酯键连接形成核苷酸，过程中伴随脱水", "糖苷键和磷酸酯键是核酸一级结构中两类关键共价键，决定链的骨架组成与方向性"], "check": {"q": "核苷酸形成过程中，碱基与戊糖之间以及核苷与磷酸之间的连接键分别是：", "o": ["A. 磷酸二酯键和糖苷键", "B. 糖苷键和磷酸酯键", "C. 氢键和磷酸二酯键", "D. 肽键和糖苷键"], "a": "B", "e": "碱基与戊糖通过糖苷键（N-糖苷键）连接形成核苷；核苷再与磷酸通过磷酸酯键连接形成核苷酸，过程中伴随脱水。"}, "cards": [{"front": "为什么T比U更利于DNA稳定性？", "back": "T比U多一个甲基，有利于DNA的稳定性和修复识别。", "mnemonic": "T多一个甲基，更稳更易修", "useImg": false}]}, {"i": 5, "sec": "DNA的结构", "title": "3′→5′磷酸二酯键与多核苷酸链 (p10)", "notes": "DNA多核苷酸链中，相邻核苷酸通过3′,5′-磷酸二酯键连接：一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键。由此链具有明确的方向性，一端为5′端，另一端为3′端。磷酸二酯键构成DNA的共价骨架，而碱基序列则携带遗传信息。", "page": 10, "level": "掌握", "img": "assets/img/ch02/p010.jpg", "anim": null, "fig": null, "points": ["相邻核苷酸通过3′,5′-磷酸二酯键连接：一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键", "链具有明确的方向性，一端为5′端，另一端为3′端", "磷酸二酯键构成DNA的共价骨架，碱基序列携带遗传信息"], "check": {"q": "关于DNA多核苷酸链中3′,5′-磷酸二酯键的叙述，正确的是：", "o": ["A. 一个核苷酸的5′-OH与下一个核苷酸的3′-磷酸形成酯键", "B. 一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键", "C. 相邻核苷酸通过氢键连接形成共价骨架", "D. 磷酸二酯键连接碱基，使DNA具有方向性"], "a": "B", "e": "DNA链中相邻核苷酸通过3′,5′-磷酸二酯键连接，即一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键，使链具有5′端和3′端方向性。"}, "cards": [{"front": "核苷酸由哪三部分组成？", "back": "碱基、戊糖和磷酸。", "mnemonic": "碱+糖+磷酸=核苷酸", "useImg": false}]}, {"i": 6, "sec": "DNA的结构", "title": "反向平行与碱基互补 (p11)", "notes": "DNA由两条反向平行的多核苷酸链组成，一条为5′→3′，另一条为3′→5′。两条链通过互补碱基之间的氢键连接：A与T形成两个氢键，G与C形成三个氢键。碱基互补使两条链序列互为镜像，是DNA复制、转录及分子杂交（如Southern、PCR）的基础。", "page": 11, "level": "掌握", "img": "assets/img/ch02/p011.jpg", "anim": null, "fig": null, "points": ["DNA由两条反向平行的多核苷酸链组成，一条为5′→3′，另一条为3′→5′", "两条链通过互补碱基之间的氢键连接：A与T形成两个氢键，G与C形成三个氢键", "碱基互补使两条链序列互为镜像", "碱基互补是DNA复制、转录及分子杂交（如Southern、PCR）的基础"], "check": {"q": "关于DNA反向平行与碱基互补的叙述，正确的是：", "o": ["A. 两条链同向平行，A与G配对，C与T配对", "B. 两条链反向平行，A与T形成两个氢键，G与C形成三个氢键", "C. 两条链反向平行，A与T形成三个氢键，G与C形成两个氢键", "D. 碱基互补只与转录有关，与PCR和Southern杂交无关"], "a": "B", "e": "DNA由两条反向平行的多核苷酸链组成，一条为5′→3′，另一条为3′→5′；A与T形成两个氢键，G与C形成三个氢键。碱基互补是复制、转录及分子杂交的基础。"}, "cards": [{"front": "碱基与戊糖、核苷与磷酸分别通过什么键连接？", "back": "碱基与戊糖通过糖苷键（N-糖苷键）连接；核苷与磷酸通过磷酸酯键连接。", "mnemonic": "碱糖糖苷，核磷磷酸酯", "useImg": false}]}, {"i": 7, "sec": "DNA的结构", "title": "DNA二级结构：双螺旋 (p12)", "notes": "DNA二级结构是两条反向平行的多核苷酸链围绕同一中心轴盘绕形成的双螺旋。示意图与空间填充模型显示：磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧，形成大沟和小沟。双螺旋直径约2 nm，B-DNA每圈约10个碱基对、螺距约3.4 nm，这种结构既稳定又便于碱基序列被读取。", "page": 12, "level": "掌握", "img": "assets/img/ch02/p012.jpg", "anim": null, "fig": "示意图与空间填充模型显示双螺旋的外侧为磷酸-脱氧核糖骨架，内侧为碱基对。注意观察大沟和小沟的位置，以及B-DNA的直径、每圈碱基对数和螺距等参数。", "points": ["DNA二级结构是两条反向平行的多核苷酸链围绕同一中心轴盘绕形成的双螺旋", "磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧，形成大沟和小沟", "双螺旋直径约2 nm，B-DNA每圈约10个碱基对、螺距约3.4 nm", "这种结构既稳定又便于碱基序列被读取"], "check": {"q": "关于DNA二级结构（B-DNA双螺旋）的描述，下列哪项正确？", "o": ["A. 两条多核苷酸链平行同向盘绕，碱基位于外侧", "B. 磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧，形成大沟和小沟", "C. 双螺旋直径约3.4 nm，每圈约10个碱基对", "D. 螺距约2 nm，每圈约3.4个碱基对"], "a": "B", "e": "B-DNA中磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧，并形成大沟和小沟；直径约2 nm，螺距约3.4 nm，每圈约10个碱基对，故B正确。"}, "cards": [{"front": "DNA多核苷酸链中相邻核苷酸通过什么键连接？方向性如何？", "back": "通过3′,5′-磷酸二酯键连接；链有方向性，一端为5′端，另一端为3′端。", "mnemonic": "3′羟基连5′磷酸，链有头尾", "useImg": false}]}, {"i": 8, "sec": "DNA的结构", "title": "DNA结构的多样性：右手与左手螺旋 (p13)", "notes": "DNA并非只有一种构象，可形成右手螺旋和左手螺旋等不同形式。右手螺旋包括A-DNA和B-DNA，左手螺旋主要为Z-DNA。不同构象在螺旋直径、螺距、碱基倾角、糖环构象等方面不同，其形成受序列、盐浓度、水合程度及拓扑压力等因素影响。结构多样性提示DNA在细胞内并非静态，而可随环境与功能需要发生构象变化。", "page": 13, "level": "理解", "img": "assets/img/ch02/p013.jpg", "anim": null, "fig": null, "points": ["DNA并非只有一种构象，可形成右手螺旋和左手螺旋等不同形式", "右手螺旋包括A-DNA和B-DNA，左手螺旋主要为Z-DNA", "不同构象在螺旋直径、螺距、碱基倾角、糖环构象等方面不同", "构象形成受序列、盐浓度、水合程度及拓扑压力等因素影响", "结构多样性提示DNA在细胞内并非静态，可随环境与功能需要发生构象变化"], "check": {"q": "下列关于DNA结构多样性的叙述，正确的是？", "o": ["A. A-DNA和B-DNA为左手螺旋，Z-DNA为右手螺旋", "B. DNA只有一种固定构象，不随环境改变", "C. 右手螺旋包括A-DNA和B-DNA，左手螺旋主要为Z-DNA", "D. 不同构象的差异仅体现在碱基序列上，与糖环构象无关"], "a": "C", "e": "DNA可形成右手螺旋（A-DNA、B-DNA）和左手螺旋（Z-DNA），不同构象在螺旋直径、螺距、碱基倾角、糖环构象等方面不同，并受序列、盐浓度、水合程度及拓扑压力影响，故C正确。"}, "cards": [{"front": "DNA两条链的空间关系是什么？", "back": "两条链反向平行：一条5′→3′，另一条3′→5′，通过互补碱基氢键连接。", "mnemonic": "反向平行，互补成双", "useImg": false}]}, {"i": 9, "sec": "DNA的结构", "title": "A-DNA、B-DNA与Z-DNA (p14)", "notes": "A-DNA、B-DNA和Z-DNA是三种典型DNA构象。影响双链构象的因素包括：核苷酸顺序、碱基组成、盐的种类、相对湿度（水合程度）等。B-DNA是生理条件下的主要形式；A-DNA在低水合条件下有利；Z-DNA为左手螺旋，常出现在特定序列并受拓扑压力影响。这些构象差异与蛋白质识别、基因调控及染色质结构密切相关。", "page": 14, "level": "掌握", "img": "assets/img/ch02/p014.jpg", "anim": null, "fig": null, "points": ["A-DNA、B-DNA和Z-DNA是三种典型DNA构象", "影响双链构象的因素包括：核苷酸顺序、碱基组成、盐的种类、相对湿度（水合程度）等", "B-DNA是生理条件下的主要形式；A-DNA在低水合条件下有利；Z-DNA为左手螺旋，常出现在特定序列并受拓扑压力影响", "这些构象差异与蛋白质识别、基因调控及染色质结构密切相关"], "check": {"q": "关于A-DNA、B-DNA和Z-DNA三种典型构象，下列叙述正确的是？", "o": ["A. B-DNA在低水合条件下有利，A-DNA是生理条件下的主要形式", "B. Z-DNA为右手螺旋，常出现在特定序列并受拓扑压力影响", "C. A-DNA在低水合条件下有利，B-DNA是生理条件下的主要形式，Z-DNA为左手螺旋", "D. 三种构象的形成只取决于核苷酸顺序，与盐的种类和相对湿度无关"], "a": "C", "e": "B-DNA是生理条件下的主要形式；A-DNA在低水合条件下有利；Z-DNA为左手螺旋，常出现在特定序列并受拓扑压力影响。影响构象的因素包括核苷酸顺序、碱基组成、盐的种类和相对湿度等，故C正确。"}, "cards": [{"front": "B-DNA双螺旋的主要结构参数有哪些？", "back": "直径约2 nm；每圈约10个碱基对；螺距约3.4 nm；骨架在外侧，碱基对在内侧，形成大沟和小沟。", "mnemonic": "2纳米粗，10碱基一圈，3.4纳米螺距", "useImg": false}]}, {"i": 10, "sec": "DNA的结构", "title": "不同DNA构象的特征与意义 (p15)", "notes": "A型DNA在低水合条件下有利，RNA-DNA杂交链和双链RNA常采用A型几何；B型DNA是生理水溶液条件下的主要形式；Z型DNA为左手螺旋，形成依赖特定序列和拓扑压力。不同构象的生物学意义在于：蛋白质可识别特定DNA构象，从而参与复制、转录、重组和基因表达调控。", "page": 15, "level": "理解", "img": "assets/img/ch02/p015.jpg", "anim": null, "fig": null, "points": ["A型DNA在低水合条件下有利，RNA-DNA杂交链和双链RNA常采用A型几何", "B型DNA是生理水溶液条件下的主要形式", "Z型DNA为左手螺旋，形成依赖特定序列和拓扑压力", "不同构象的生物学意义在于：蛋白质可识别特定DNA构象，从而参与复制、转录、重组和基因表达调控"], "check": {"q": "关于不同DNA构象的特征与生物学意义，下列叙述正确的是？", "o": ["A. RNA-DNA杂交链和双链RNA常采用B型几何", "B. A型DNA在低水合条件下有利，RNA-DNA杂交链和双链RNA常采用A型几何", "C. Z型DNA为右手螺旋，其形成不依赖特定序列", "D. 蛋白质只能识别DNA的碱基序列，不能识别特定DNA构象"], "a": "B", "e": "A型DNA在低水合条件下有利，RNA-DNA杂交链和双链RNA常采用A型几何；B型DNA是生理水溶液条件下的主要形式；Z型DNA为左手螺旋，形成依赖特定序列和拓扑压力；蛋白质可识别特定DNA构象参与复制、转录、重组和基因表达调控，故B正确。"}, "cards": [{"front": "A-DNA、B-DNA、Z-DNA分别是什么螺旋？", "back": "A-DNA和B-DNA为右手螺旋；Z-DNA为左手螺旋。B-DNA是生理条件下的主要形式。", "mnemonic": "A、B右手，Z左手", "useImg": false}]}, {"i": 11, "sec": "DNA的结构", "title": "维持双螺旋稳定的因素 (p16)", "notes": "双螺旋的稳定主要依靠四类作用：①碱基对之间的氢键；②碱基堆积力，包括碱基疏水相互作用和范德华力；③磷酸基团负电荷与介质中阳离子形成的离子键，可屏蔽静电排斥；④碱基的分子内能。其中碱基堆积力对双螺旋稳定性贡献最大，氢键保证配对特异性，离子键维持骨架电荷平衡。这些因素共同决定DNA的稳定性与解链行为。", "page": 16, "level": "掌握", "img": "assets/img/ch02/p016.jpg", "anim": null, "fig": null, "points": ["双螺旋的稳定主要依靠四类作用：①碱基对之间的氢键；②碱基堆积力，包括碱基疏水相互作用和范德华力；③磷酸基团负电荷与介质中阳离子形成的离子键，可屏蔽静电排斥；④碱基的分子内能", "碱基堆积力对双螺旋稳定性贡献最大", "氢键保证配对特异性", "离子键维持骨架电荷平衡", "这些因素共同决定DNA的稳定性与解链行为"], "check": {"q": "关于维持DNA双螺旋稳定的因素，下列叙述正确的是？", "o": ["A. 氢键对双螺旋稳定性的贡献最大，并保证配对特异性", "B. 碱基堆积力对双螺旋稳定性贡献最大，氢键保证配对特异性，离子键维持骨架电荷平衡", "C. 磷酸基团负电荷之间的静电排斥直接增强双螺旋稳定性", "D. 碱基的分子内能与双螺旋稳定性无关"], "a": "B", "e": "双螺旋稳定依靠氢键、碱基堆积力、离子键和碱基分子内能等；其中碱基堆积力贡献最大，氢键保证配对特异性，离子键（阳离子屏蔽磷酸基团负电荷）维持骨架电荷平衡，故B正确。"}, "cards": [{"front": "维持DNA双螺旋稳定的四类作用中，哪类贡献最大？", "back": "碱基堆积力贡献最大；此外还有氢键、离子键和碱基分子内能。", "mnemonic": "堆积力最大，氢键保特异，离子稳骨架", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_5", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "DNA双螺旋中，碱基对之间的主要作用力是：", "o": ["A. 磷酸二酯键", "B. 氢键", "C. 肽键", "D. 糖苷键"], "a": "B", "e": "碱基对之间通过氢键连接，A-T形成两个氢键，G-C形成三个氢键；磷酸二酯键连接同一链内相邻核苷酸，糖苷键连接碱基与戊糖。", "kp": "ch02_s1_7"}, {"id": "ch02_mcq_6", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "下列关于DNA与RNA核苷酸差异的叙述，正确的是：", "o": ["A. DNA含核糖，RNA含脱氧核糖", "B. DNA含尿嘧啶，RNA含胸腺嘧啶", "C. DNA含脱氧核糖和胸腺嘧啶，RNA含核糖和尿嘧啶", "D. DNA和RNA的碱基组成完全相同"], "a": "C", "e": "DNA含脱氧核糖和胸腺嘧啶（T），RNA含核糖和尿嘧啶（U），这是两者在化学组成上的主要区别。", "kp": "ch02_s1_3"}, {"id": "ch02_mcq_7", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "生理水溶液条件下DNA的主要构象形式是：", "o": ["A. A-DNA", "B. B-DNA", "C. Z-DNA", "D. 三链DNA"], "a": "B", "e": "B-DNA是生理水溶液条件下的主要形式；A-DNA在低水合条件下有利，Z-DNA为左手螺旋，需特定序列和拓扑压力。", "kp": "ch02_s1_10"}, {"id": "ch02_mcq_8", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "维持DNA双螺旋稳定性的因素中，贡献最大的是：", "o": ["A. 碱基对之间的氢键", "B. 碱基堆积力", "C. 磷酸基团与阳离子形成的离子键", "D. 碱基的分子内能"], "a": "B", "e": "碱基堆积力包括疏水相互作用和范德华力，对双螺旋稳定性贡献最大；氢键主要保证配对特异性，离子键主要屏蔽磷酸骨架的静电排斥。", "kp": "ch02_s1_11"}, {"id": "ch02_mcq_9", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "DNA两条链反向平行的含义是：", "o": ["A. 两条链的碱基序列完全相同", "B. 一条链为5′→3′方向，另一条链为3′→5′方向", "C. 两条链均为左手螺旋", "D. 两条链通过磷酸二酯键相互连接"], "a": "B", "e": "反向平行指两条多核苷酸链方向相反：一条为5′→3′，另一条为3′→5′；两条链之间通过碱基氢键连接，而非磷酸二酯键。", "kp": "ch02_s1_6"}], "judge": [{"id": "ch02_judge_3", "modI": 1, "q": "RNA用尿嘧啶（U）替代DNA中的胸腺嘧啶（T），U与A同样能配对。", "a": "对", "e": "RNA含核糖（2′-OH），DNA含脱氧核糖；RNA用U替代T，U与A同样能配对，但T比U多一个甲基，有利于DNA的稳定性和修复识别。", "kp": "ch02_s1_3"}, {"id": "ch02_judge_4", "modI": 1, "q": "DNA双螺旋中，磷酸-脱氧核糖骨架位于内侧，碱基对位于外侧。", "a": "错", "e": "DNA双螺旋中，磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧，形成大沟和小沟。", "kp": "ch02_s1_7"}], "fill": [{"id": "ch02_fill_2", "modI": 1, "q": "DNA含四种碱基：嘌呤类的腺嘌呤（A）和鸟嘌呤（G），嘧啶类的胞嘧啶（C）和________（T）。", "a": "胸腺嘧啶", "kp": "ch02_s1_2"}, {"id": "ch02_fill_3", "modI": 1, "q": "DNA多核苷酸链中，相邻核苷酸通过________相连（一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键）。", "a": "磷酸二酯键", "kp": "ch02_s1_5"}, {"id": "ch02_fill_4", "modI": 1, "q": "DNA双螺旋中，A与T形成________个氢键，G与C形成________个氢键。", "a": "2,3", "kp": "ch02_s1_7"}], "short": [{"id": "ch02_short_2", "modI": 1, "q": "简述DNA双螺旋结构的主要特征。", "a": "①两条反向平行的多核苷酸链围绕同一中心轴盘绕形成双螺旋；②磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧；③形成大沟和小沟；④双螺旋直径约2 nm；⑤B-DNA每圈约10个碱基对，螺距约3.4 nm；⑥碱基互补配对：A与T形成两个氢键，G与C形成三个氢键；⑦这种结构既稳定又便于碱基序列被读取。", "kp": "ch02_s1_7"}], "calc": [], "term": [{"id": "ch02_term_3", "modI": 1, "term": "Nucleotide", "def": "核苷酸：由碱基、戊糖和磷酸组成，是核酸的基本结构单位。要点：①碱基与戊糖通过N-糖苷键连接形成核苷；②核苷再与磷酸通过磷酸酯键连接形成核苷酸；③过程中伴随脱水；④糖苷键和磷酸酯键是核酸一级结构中两类关键共价键。", "kp": "ch02_s1_1"}, {"id": "ch02_term_4", "modI": 1, "term": "Phosphodiester bond", "def": "3′,5′-磷酸二酯键：DNA多核苷酸链中相邻核苷酸之间的连接键。要点：①一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键；②构成DNA的共价骨架；③使链具有明确方向性，一端为5′端，另一端为3′端；④碱基序列携带遗传信息。", "kp": "ch02_s1_6"}, {"id": "ch02_term_5", "modI": 1, "term": "B-DNA", "def": "B型DNA：生理水溶液条件下DNA的主要双螺旋构象。要点：①右手螺旋；②两条反向平行的多核苷酸链围绕同一中心轴盘绕；③磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧；④形成大沟和小沟；⑤直径约2 nm，每圈约10个碱基对，螺距约3.4 nm。", "kp": "ch02_s1_9"}]}, {"i": 2, "name": "模块三：DNA的三级结构（拓扑）与理化性质", "slides": [{"i": 0, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA拓扑结构的基本概念(p17)", "notes": "真核生物染色体中的线性DNA由于长度极长，并受到染色质结构及其他细胞组分相互作用的限制，会受到拓扑约束。共价闭合环状DNA（cccDNA）如质粒和环状细菌染色体被认为是受到拓扑约束的典型例子。理解DNA的拓扑结构，以及细胞如何在DNA复制、转录和其他染色体相关过程中适应并利用这些拓扑约束，是分子生物学中的一个重要基础问题。拓扑约束的存在意味着DNA的某些拓扑性质（如连环数）在共价闭合环状分子中是固定的，除非通过拓扑异构酶等机制改变。", "page": 17, "level": "掌握", "img": "assets/img/ch02/p017.jpg", "anim": null, "fig": null, "points": ["真核生物线性DNA因长度极长并受染色质结构限制，受到拓扑约束。", "共价闭合环状DNA（cccDNA）如质粒和环状细菌染色体是拓扑约束的典型例子。", "拓扑约束意味着某些拓扑性质（如连环数）在共价闭合环状分子中是固定的。", "理解DNA拓扑结构及细胞如何适应和利用拓扑约束是分子生物学的重要基础问题。"], "check": {"q": "根据DNA拓扑结构的基本概念，下列哪类DNA分子被认为是受到拓扑约束的典型例子？", "o": ["A. 真核生物线性染色体DNA", "B. 共价闭合环状DNA（cccDNA）", "C. 单链DNA", "D. 断裂的双链DNA片段"], "a": "B", "e": "讲义明确指出共价闭合环状DNA（cccDNA）如质粒和环状细菌染色体是受到拓扑约束的典型例子；线性DNA虽也受拓扑约束，但典型例子是cccDNA。"}, "cards": [{"front": "什么是DNA的拓扑约束？典型例子是什么？", "back": "线性DNA因长度极长并受染色质结构等限制而受拓扑约束；共价闭合环状DNA（cccDNA）如质粒和环状细菌染色体是典型例子。拓扑约束意味着某些拓扑性质（如连环数）在cccDNA中是固定的。", "mnemonic": "闭环锁死拓扑数，线性受限也难逃", "useImg": false}, {"front": "什么是杂交？可以发生在哪些分子之间？", "back": "杂交是指两条互补或接近互补的DNA/RNA序列通过碱基配对形成双链的过程。可发生在DNA-DNA、DNA-RNA或RNA-RNA之间。", "mnemonic": "互补配对即杂交，DNA/RNA都可搭", "useImg": false}]}, {"i": 1, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA的三种拓扑构型(p18)", "notes": "DNA在结构上主要有三种拓扑构型的变化：超螺旋（supercoiling）、连锁（catenation）与纽结（knotting）。这些构型能够使DNA在不进行复制与转录时，尽量维持紧密性，有利于DNA的包装。但在转录或复制过程中，这些拓扑构型将会阻碍反应的进行，因此需要拓扑异构酶等来解除这些拓扑障碍。超螺旋是同一DNA分子内的过度缠绕或缠绕不足；连锁是两个环状DNA分子相互套连；纽结是同一DNA链自身打结。", "page": 18, "level": "掌握", "img": "assets/img/ch02/p018.jpg", "anim": null, "fig": null, "points": ["DNA的三种拓扑构型：超螺旋、连锁与纽结。", "超螺旋是同一DNA分子内的过度缠绕或缠绕不足。", "连锁是两个环状DNA分子相互套连；纽结是同一DNA分子打结。", "这些构型有利于DNA紧密包装，但会阻碍复制和转录，需拓扑异构酶解除。"], "check": {"q": "下列哪一项不属于讲义中提到的DNA三种主要拓扑构型？", "o": ["A. 超螺旋", "B. 连锁", "C. 纽结", "D. 变性"], "a": "D", "e": "讲义列出DNA的三种拓扑构型为超螺旋、连锁与纽结；变性属于DNA的理化性质变化，不是拓扑构型。"}, "cards": [{"front": "DNA的三种拓扑构型是什么？", "back": "超螺旋（supercoiling）、连锁（catenation）与纽结（knotting）。", "mnemonic": "超连纽——超螺旋、连锁、纽结", "useImg": false}, {"front": "杂交的严格性取决于哪些条件？有哪些应用？", "back": "严格性取决于温度、盐浓度和甲酰胺浓度等。应用包括Southern blot、Northern blot、原位杂交、PCR、基因芯片、DNA纳米技术等。", "mnemonic": "温盐甲酰胺控严格", "useImg": false}]}, {"i": 2, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA超螺旋及其意义(p19)", "notes": "电镜下的超螺旋DNA与松弛DNA对比显示，超螺旋DNA更加紧密。DNA超螺旋是DNA链所承受扭转应力的一种表现，通常是指DNA相对于正常状态发生过度缠绕或缠绕不足。超螺旋对于DNA的紧密包装非常重要，使得长链DNA能够被压缩在细胞核或类核内。超螺旋分为正超螺旋和负超螺旋，负超螺旋有利于解链，从而促进复制和转录等过程。", "page": 19, "level": "掌握", "img": "assets/img/ch02/p019.jpg", "anim": null, "fig": null, "points": ["电镜下超螺旋DNA比松弛DNA更紧密。", "超螺旋是DNA链承受扭转应力的表现，即相对于正常状态过度缠绕或缠绕不足。", "超螺旋对DNA紧密包装非常重要，使长链DNA压缩在细胞核或类核内。", "超螺旋分为正超螺旋和负超螺旋，负超螺旋有利于解链，促进复制和转录。"], "check": {"q": "关于DNA超螺旋的生物学意义，下列叙述正确的是？", "o": ["A. 正超螺旋有利于解链，促进复制和转录", "B. 负超螺旋有利于解链，促进复制和转录", "C. 超螺旋使DNA变得松散，不利于包装", "D. 超螺旋仅存在于线性DNA中"], "a": "B", "e": "讲义指出负超螺旋有利于解链，从而促进复制和转录等过程；超螺旋使DNA更紧密，有利于包装。"}, "cards": [{"front": "超螺旋、连锁、纽结分别指什么？", "back": "超螺旋：同一DNA分子内的过度缠绕或缠绕不足；连锁：两个环状DNA分子相互套连；纽结：同一DNA分子内发生打结。", "mnemonic": "自缠为超，互套为连，自打成结", "useImg": false}, {"front": "DNA-PAINT技术的原理是什么？", "back": "利用DNA杂交的瞬时结合和解离实现单分子定位。短链DNA探针与目标分子上的对接链互补，探针结合时发出荧光，解离时荧光消失，从而实现超分辨率成像。", "mnemonic": "瞬时结合闪荧光，解离消失定单分子", "useImg": false}]}, {"i": 3, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "超螺旋的生物学功能与拓扑异构酶(p20)", "notes": "本页为示意图，结合前后页内容，该图可能展示了超螺旋DNA在电镜下的形态以及拓扑异构酶的作用。超螺旋使DNA紧密包装，但复制和转录时解旋会产生正超螺旋压力，阻碍解链。拓扑异构酶通过切断和重新连接DNA链来调节超螺旋水平，从而解决拓扑问题。真核生物中核小体的形成引入负超螺旋，而拓扑异构酶可以松弛超螺旋DNA，维持DNA的适当拓扑状态。", "page": 20, "level": "理解", "img": "assets/img/ch02/p020.jpg", "anim": null, "fig": "该图可能展示了超螺旋DNA在电镜下的形态以及拓扑异构酶的作用。观察时注意超螺旋DNA的紧密缠绕形态，以及拓扑异构酶如何通过切断和连接改变DNA拓扑状态。", "points": ["超螺旋使DNA紧密包装，但复制和转录解旋时产生正超螺旋压力，阻碍解链。", "拓扑异构酶通过切断和重新连接DNA链来调节超螺旋水平。", "真核生物中核小体的形成引入负超螺旋。", "拓扑异构酶可以松弛超螺旋DNA，维持适当的拓扑状态。"], "check": {"q": "根据超螺旋的生物学功能与拓扑异构酶的作用，下列叙述正确的是？", "o": ["A. 拓扑异构酶通过切断和重新连接DNA链来调节超螺旋水平", "B. 拓扑异构酶通过水解DNA碱基来松弛超螺旋", "C. 核小体的形成引入正超螺旋", "D. 复制和转录时解旋会产生负超螺旋压力"], "a": "A", "e": "讲义指出拓扑异构酶通过切断和重新连接DNA链来调节超螺旋水平；核小体形成引入负超螺旋；解旋产生正超螺旋压力。"}, "cards": [{"front": "DNA超螺旋的本质是什么？分为哪两类？", "back": "超螺旋是DNA链所承受扭转应力的一种表现，即相对于正常状态发生过度缠绕或缠绕不足。分为正超螺旋和负超螺旋。", "mnemonic": "正紧负松，扭转应力", "useImg": false}]}, {"i": 4, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "复制过程中的拓扑压力(p21)", "notes": "在DNA复制过程中，解旋酶解开双链，未解链部分的缠绕更加紧密，形成正超螺旋压力。这种压力使解链不能继续进行，因此需要拓扑异构酶来释放这种张力。拓扑异构酶I切割一条链并旋转，拓扑异构酶II切割两条链并传递另一条双链通过，从而改变连环数。这一机制保证了复制叉的顺利推进。", "page": 21, "level": "掌握", "img": "assets/img/ch02/p021.jpg", "anim": null, "fig": null, "points": ["DNA复制时，解旋酶解开双链，未解链部分缠绕更紧密，形成正超螺旋压力。", "正超螺旋压力使解链不能继续进行，需要拓扑异构酶释放张力。", "拓扑异构酶I切割一条链并旋转；拓扑异构酶II切割两条链并传递另一条双链通过。", "拓扑异构酶通过改变连环数保证复制叉顺利推进。"], "check": {"q": "在DNA复制过程中，解旋酶解开双链后，未解链部分会形成什么拓扑压力？需要哪种酶来释放？", "o": ["A. 负超螺旋压力；拓扑异构酶I", "B. 正超螺旋压力；拓扑异构酶", "C. 纽结；解旋酶", "D. 连锁；连接酶"], "a": "B", "e": "讲义指出复制时解旋酶解开双链，未解链部分缠绕更紧密，形成正超螺旋压力，需要拓扑异构酶来释放张力。"}, "cards": [{"front": "负超螺旋有什么生物学意义？", "back": "负超螺旋有利于解链，从而促进复制和转录等过程；同时有助于DNA的紧密包装，使长链DNA压缩在细胞核或类核内。", "mnemonic": "负超易解链，复制转录欢", "useImg": false}]}, {"i": 5, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "负超螺旋与拓扑异构酶的作用(p22)", "notes": "细胞内的DNA通常处于负超螺旋状态，这有利于解链过程。在真核生物中，核小体的形成引入负超螺旋，帮助DNA压缩。拓扑异构酶可以松弛超螺旋DNA，通过暂时切断DNA链来改变拓扑状态。电镜照片显示超螺旋DNA的形态。负超螺旋不仅有利于复制和转录，还与DNA的重组和修复等过程密切相关。", "page": 22, "level": "掌握", "img": "assets/img/ch02/p022.jpg", "anim": null, "fig": null, "points": ["细胞内DNA通常处于负超螺旋状态，有利于解链。", "真核生物中核小体的形成引入负超螺旋，帮助DNA压缩。", "拓扑异构酶通过暂时切断DNA链来松弛超螺旋，改变拓扑状态。", "负超螺旋有利于复制、转录，并与DNA重组和修复密切相关。"], "check": {"q": "关于细胞内DNA的负超螺旋状态，下列叙述错误的是？", "o": ["A. 负超螺旋有利于解链过程", "B. 真核生物中核小体的形成引入负超螺旋", "C. 拓扑异构酶可以松弛超螺旋DNA", "D. 负超螺旋不利于DNA的压缩包装"], "a": "D", "e": "讲义指出负超螺旋有利于解链，核小体形成引入负超螺旋帮助DNA压缩，拓扑异构酶可松弛超螺旋；因此D项“不利于压缩包装”错误。"}, "cards": [{"front": "拓扑异构酶如何解决DNA拓扑问题？", "back": "拓扑异构酶通过切断和重新连接DNA链来调节超螺旋水平。拓扑异构酶I切割一条链并旋转；拓扑异构酶II切割两条链并传递另一条双链通过，从而改变连环数。", "mnemonic": "I切一链转，II切两链传", "useImg": false}]}, {"i": 6, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "核酸的物理化学性质：变性(p23)", "notes": "DNA变性（DNA denaturation, DNA melting）是指DNA双螺旋的两条链分离的过程。促进DNA变性的条件包括加热、低离子强度、高pH和有机溶剂。变性过程中，氢键断裂，碱基堆积力被破坏，但共价键不受影响。变性后DNA的紫外吸收（260 nm）增加，称为增色效应。这一性质常用于检测DNA的变性和复性。", "page": 23, "level": "掌握", "img": "assets/img/ch02/p023.jpg", "anim": null, "fig": null, "points": ["DNA变性是指双螺旋两条链分离的过程。", "促进变性的条件：加热、低离子强度、高pH和有机溶剂。", "变性过程中氢键断裂，碱基堆积力被破坏，但共价键不受影响。", "变性后DNA在260 nm紫外吸收增加，称为增色效应。"], "check": {"q": "关于DNA变性，下列叙述正确的是？", "o": ["A. 变性时DNA的共价键断裂", "B. 变性后260 nm紫外吸收减少，称为减色效应", "C. 加热、低离子强度、高pH和有机溶剂均可促进变性", "D. 变性是指DNA两条链分离但碱基堆积力不受影响"], "a": "C", "e": "讲义指出促进DNA变性的条件包括加热、低离子强度、高pH和有机溶剂；变性时氢键断裂、碱基堆积力被破坏，但共价键不受影响；变性后260 nm吸收增加，称为增色效应。"}, "cards": [{"front": "复制过程中为什么会产生拓扑压力？如何解决？", "back": "解旋酶解开双链时，未解链部分缠绕更加紧密，形成正超螺旋压力，使解链不能继续。需要拓扑异构酶释放张力，保证复制叉顺利推进。", "mnemonic": "解旋生正超，拓扑来解压", "useImg": false}]}, {"i": 7, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA的熔解温度（Tm）(p24)", "notes": "DNA的熔解温度（Tm）是两条链半解离或变性的温度，即吸光值增加到最大值的一半时的温度。将DNA加热，并通过260 nm处吸光度的增加来测量其熔解。熔化完成一半的点是熔化温度（Tm）。图中DNA的Tm约为85℃。Tm值与GC含量正相关，GC含量越高，Tm越高，因为GC碱基对有三个氢键，比AT碱基对更稳定。", "page": 24, "level": "掌握", "img": "assets/img/ch02/p024.jpg", "anim": null, "fig": null, "points": ["Tm是DNA两条链半解离或变性的温度，即吸光值增加到最大值一半时的温度。", "通过加热DNA并测量260 nm吸光度增加来测定熔解曲线。", "图中DNA的Tm约为85℃。", "Tm值与GC含量正相关，GC含量越高，Tm越高，因为GC碱基对有三个氢键。"], "check": {"q": "关于DNA熔解温度（Tm）的叙述，正确的是？", "o": ["A. Tm是DNA完全变性时的温度", "B. Tm是吸光值增加到最大值一半时的温度", "C. Tm与GC含量呈负相关", "D. Tm测定通常在280 nm处进行"], "a": "B", "e": "Tm定义为两条链半解离或变性时的温度，即吸光值增加到最大值一半时的温度；Tm与GC含量正相关，测定通常在260 nm处进行。"}, "cards": [{"front": "真核生物中核小体的形成对DNA拓扑状态有何影响？", "back": "核小体的形成引入负超螺旋，帮助DNA压缩，有利于解链过程。细胞内DNA通常处于负超螺旋状态。", "mnemonic": "核小体缠出负超螺旋", "useImg": false}]}, {"i": 8, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA熔解曲线与GC含量的关系(p25)", "notes": "本页为示意图，结合前后页内容，该图可能展示了不同物种DNA的熔解曲线，说明GC含量对Tm的影响。熔解曲线显示吸光度随温度升高而增加，呈S形。GC含量高的DNA，其熔解曲线向右移动，Tm值更高。这一性质可用于估计DNA的GC含量，也可用于PCR引物设计等。", "page": 25, "level": "理解", "img": "assets/img/ch02/p025.jpg", "anim": null, "fig": "该图可能展示了不同物种DNA的熔解曲线，说明GC含量对Tm的影响。观察时注意曲线呈S形，GC含量高的DNA曲线右移，Tm值更高。", "points": ["熔解曲线显示吸光度随温度升高而增加，呈S形。", "GC含量高的DNA，熔解曲线向右移动，Tm值更高。", "该性质可用于估计DNA的GC含量，也可用于PCR引物设计。"], "check": {"q": "根据DNA熔解曲线与GC含量的关系，下列叙述正确的是？", "o": ["A. GC含量越高，熔解曲线越向左移动，Tm越低", "B. 熔解曲线呈S形，吸光度随温度升高而增加", "C. AT含量越高，Tm越高", "D. 熔解曲线可用于直接测定DNA序列"], "a": "B", "e": "熔解曲线显示吸光度随温度升高而增加，呈S形；GC含量高的DNA熔解曲线向右移动，Tm更高；该性质可用于估计GC含量，但不能直接测定序列。"}, "cards": [{"front": "什么是DNA变性？促进变性的条件有哪些？", "back": "DNA变性是指DNA双螺旋两条链分离的过程。促进条件：加热、低离子强度、高pH和有机溶剂。变性时氢键断裂、碱基堆积力被破坏，但共价键不受影响。", "mnemonic": "热低碱有机，氢断共价留", "useImg": false}]}, {"i": 9, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "各物种DNA的GC含量(p26)", "notes": "不同物种的DNA具有不同的GC含量。例如，酵母和大肠杆菌的GC含量不同，这影响了它们的Tm值。GC含量是物种基因组特征之一，与基因组的稳定性、密码子偏好性等有关。通过测定Tm可以估算GC含量，反之亦然。", "page": 26, "level": "了解", "img": "assets/img/ch02/p026.jpg", "anim": null, "fig": null, "points": ["不同物种的DNA具有不同的GC含量。", "GC含量影响Tm值，例如酵母和大肠杆菌的GC含量不同。", "GC含量是物种基因组特征之一，与基因组稳定性、密码子偏好性等有关。", "通过测定Tm可以估算GC含量，反之亦然。"], "check": {"q": "关于不同物种DNA的GC含量，下列叙述正确的是？", "o": ["A. 所有物种的GC含量相同", "B. GC含量不影响Tm值", "C. GC含量是物种基因组特征之一，可通过Tm估算", "D. GC含量与基因组稳定性无关"], "a": "C", "e": "不同物种DNA的GC含量不同，GC含量是物种基因组特征之一，与基因组稳定性等有关；通过测定Tm可以估算GC含量。"}, "cards": [{"front": "什么是增色效应？", "back": "DNA变性后紫外吸收（260 nm）增加的现象，称为增色效应。常用于检测DNA的变性和复性。", "mnemonic": "变性吸光增，260看分明", "useImg": false}]}, {"i": 10, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA复性（退火）(p27)", "notes": "复性（DNA renaturation/annealing，退火）是指分离的DNA链重新结合形成双链的过程。变性DNA在适当条件下可以复性，恢复原来的双螺旋结构。复性过程遵循二级反应动力学，其速度取决于DNA浓度、序列复杂度和温度等因素。复性是许多分子生物学技术的基础，如PCR、Southern杂交等。", "page": 27, "level": "掌握", "img": "assets/img/ch02/p027.jpg", "anim": null, "fig": null, "points": ["复性是指分离的DNA链重新结合形成双链的过程。", "变性DNA在适当条件下可以复性，恢复原来的双螺旋结构。", "复性过程遵循二级反应动力学，速度取决于DNA浓度、序列复杂度和温度等因素。", "复性是许多分子生物学技术的基础，如PCR、Southern杂交等。"], "check": {"q": "关于DNA复性（退火）的叙述，正确的是？", "o": ["A. 复性是指DNA双链解离成单链的过程", "B. 复性过程遵循一级反应动力学", "C. 复性速度取决于DNA浓度、序列复杂度和温度等因素", "D. 复性只能发生在DNA-DNA之间"], "a": "C", "e": "复性是指分离的DNA链重新结合形成双链的过程，遵循二级反应动力学，其速度取决于DNA浓度、序列复杂度和温度等因素。"}, "cards": [{"front": "什么是DNA的熔解温度（Tm）？", "back": "Tm是两条链半解离或变性的温度，即吸光值增加到最大值一半时的温度。", "mnemonic": "半解温度即Tm", "useImg": false}]}, {"i": 11, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "复性的步骤：成核与拉拉链(p28)", "notes": "变性的单链DNA分子在复性过程中重新彼此靠近，随机碰撞。若是非对应片段，即使有短暂结合也会分离。互补的两条链首先是中心部分互补碱基对之间形成氢键，称为成核作用（nucleation），接着像拉拉链一样，其余部分随之形成互补双链，称为拉拉链作用（Zippering）。复性过程受温度、DNA浓度、复性时间和DNA复杂度等因素影响。", "page": 28, "level": "理解", "img": "assets/img/ch02/p028.jpg", "anim": null, "fig": null, "points": ["复性时变性单链DNA随机碰撞，非对应片段短暂结合也会分离。", "互补链首先在中心部分形成氢键，称为成核作用。", "随后像拉拉链一样，其余部分形成互补双链，称为拉拉链作用。", "复性过程受温度、DNA浓度、复性时间和DNA复杂度等因素影响。"], "check": {"q": "关于DNA复性的步骤，下列叙述正确的是？", "o": ["A. 复性时两条链首先从末端开始配对", "B. 成核作用是指互补链中心部分形成氢键", "C. 拉拉链作用是指非对应片段短暂结合", "D. 复性过程不受温度影响"], "a": "B", "e": "复性时互补的两条链首先是中心部分互补碱基对之间形成氢键，称为成核作用；接着像拉拉链一样其余部分形成互补双链，称为拉拉链作用。复性过程受温度等因素影响。"}, "cards": [{"front": "Tm值与GC含量有什么关系？为什么？", "back": "Tm值与GC含量正相关，GC含量越高，Tm越高。因为GC碱基对有三个氢键，比AT碱基对（两个氢键）更稳定。", "mnemonic": "GC三氢键，Tm往上窜", "useImg": false}]}, {"i": 12, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "影响复性的因素(p29)", "notes": "影响复性的因素包括：温度，最佳复性温度比Tm低约25℃；DNA浓度，浓度越高复性越快；复性时间，降温要慢；DNA的复杂程度，片段越小、碱基组成越单一，复性越快。淬火（Quenching）是将热DNA溶液迅速插入冰中，以确保变性DNA保持单链状态。这些因素在核酸杂交实验中需要严格控制。", "page": 29, "level": "掌握", "img": "assets/img/ch02/p029.jpg", "anim": null, "fig": null, "points": ["温度：最佳复性温度比Tm低约25℃。", "DNA浓度：浓度越高复性越快。", "复性时间：降温要慢。", "DNA复杂程度：片段越小、碱基组成越单一，复性越快。", "淬火是将热DNA溶液迅速插入冰中，确保变性DNA保持单链状态。"], "check": {"q": "关于影响DNA复性的因素，下列叙述正确的是？", "o": ["A. 最佳复性温度比Tm高约25℃", "B. DNA浓度越低复性越快", "C. 淬火是将热DNA溶液迅速插入冰中，使变性DNA保持单链状态", "D. DNA复杂度越高复性越快"], "a": "C", "e": "最佳复性温度比Tm低约25℃；DNA浓度越高复性越快；淬火是将热DNA溶液迅速插入冰中，以确保变性DNA保持单链状态；DNA复杂度越高复性越慢。"}, "cards": [{"front": "DNA熔解曲线的形状及与GC含量的关系？", "back": "熔解曲线呈S形，吸光度随温度升高而增加。GC含量高的DNA，熔解曲线向右移动，Tm值更高。可用于估计GC含量和PCR引物设计。", "mnemonic": "S形右移GC高", "useImg": false}]}, {"i": 13, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "杂交（Hybridization）(p30)", "notes": "杂交是指两条互补或接近互补的DNA/RNA序列通过碱基配对形成双链的过程。杂交可以发生在DNA-DNA、DNA-RNA或RNA-RNA之间。杂交是分子生物学中重要的检测手段，如Southern blot、Northern blot、原位杂交等。杂交的严格性取决于温度、盐浓度和甲酰胺浓度等条件。", "page": 30, "level": "掌握", "img": "assets/img/ch02/p030.jpg", "anim": null, "fig": null, "points": ["杂交是指两条互补或接近互补的DNA/RNA序列通过碱基配对形成双链的过程。", "杂交可以发生在DNA-DNA、DNA-RNA或RNA-RNA之间。", "杂交是分子生物学中重要的检测手段，如Southern blot、Northern blot、原位杂交等。", "杂交的严格性取决于温度、盐浓度和甲酰胺浓度等条件。"], "check": {"q": "关于杂交（Hybridization）的叙述，正确的是？", "o": ["A. 杂交只能发生在DNA-DNA之间", "B. 杂交的严格性取决于温度、盐浓度和甲酰胺浓度等条件", "C. 杂交是指两条完全相同的DNA链形成双链的过程", "D. Southern blot是检测RNA的技术"], "a": "B", "e": "杂交是指两条互补或接近互补的DNA/RNA序列通过碱基配对形成双链的过程，可发生在DNA-DNA、DNA-RNA或RNA-RNA之间；杂交的严格性取决于温度、盐浓度和甲酰胺浓度等条件；Southern blot是检测DNA的技术。"}, "cards": [{"front": "什么是DNA复性（退火）？其动力学特征是什么？", "back": "复性是指分离的DNA链重新结合形成双链的过程。遵循二级反应动力学，速度取决于DNA浓度、序列复杂度和温度等因素。", "mnemonic": "二级动力学，浓度复杂度定速度", "useImg": false}]}, {"i": 14, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "复性与杂交的应用(p31)", "notes": "本页为示意图，结合前后页内容，该图可能展示了DNA复性和杂交的过程，以及DNA纳米机器人的应用。复性和杂交是许多分子生物学技术的基础，如PCR、基因芯片、DNA纳米技术等。DNA纳米机器人利用DNA的互补配对和杂交特性，可以设计出动态的纳米结构，用于药物递送和分子计算。", "page": 31, "level": "了解", "img": "assets/img/ch02/p031.jpg", "anim": null, "fig": "该图可能展示了DNA复性和杂交的过程，以及DNA纳米机器人的应用。观察时注意DNA链如何通过互补配对形成双链，以及纳米机器人如何利用杂交特性实现动态功能。", "points": ["复性和杂交是许多分子生物学技术的基础，如PCR、基因芯片、DNA纳米技术等。", "DNA纳米机器人利用DNA的互补配对和杂交特性，设计动态纳米结构。", "DNA纳米机器人可用于药物递送和分子计算。"], "check": {"q": "关于DNA复性与杂交的应用，下列哪项描述最符合该页示意图所体现的核心思想？", "o": ["A. DNA复性与杂交只能用于PCR，不能用于纳米技术", "B. DNA复性与杂交是PCR、基因芯片和DNA纳米机器人等技术的基础", "C. DNA复性与杂交仅发生在DNA与RNA之间，不涉及DNA与DNA之间", "D. DNA纳米机器人依靠DNA的断裂和连接，而不是互补配对与杂交"], "a": "B", "e": "该页示意图结合前后内容说明，DNA复性和杂交是PCR、基因芯片、DNA纳米技术等许多分子生物学技术的基础；DNA纳米机器人利用DNA互补配对和杂交特性设计动态纳米结构。"}, "cards": [{"front": "复性的两个步骤是什么？", "back": "①成核作用（nucleation）：互补链中心部分互补碱基对之间先形成氢键；②拉拉链作用（Zippering）：其余部分随之像拉拉链一样形成互补双链。", "mnemonic": "先成核，后拉链", "useImg": false}]}, {"i": 15, "sec": "DNA的三级结构（拓扑）与理化性质", "title": "DNA-PAINT技术(p32)", "notes": "DNA-PAINT是一种超分辨率显微成像技术，利用DNA杂交的瞬时结合和解离来实现单分子定位。通过设计短链DNA探针与目标分子上的对接链互补，探针结合时发出荧光，解离时荧光消失，从而实现对目标分子的高分辨率成像。该技术利用了DNA复性和杂交的原理，是分子生物学与纳米技术结合的典范。", "page": 32, "level": "了解", "img": "assets/img/ch02/p032.jpg", "anim": null, "fig": null, "points": ["DNA-PAINT是一种超分辨率显微成像技术，利用DNA杂交的瞬时结合和解离实现单分子定位。", "设计短链DNA探针与目标分子上的对接链互补，探针结合时发出荧光，解离时荧光消失。", "该技术利用DNA复性和杂交原理，实现高分辨率成像。", "DNA-PAINT是分子生物学与纳米技术结合的典范。"], "check": {"q": "DNA-PAINT超分辨率成像技术实现单分子定位的基本原理是：", "o": ["A. 通过DNA探针与目标对接链的瞬时结合和解离，使荧光信号闪烁，从而进行单分子定位", "B. 通过永久结合并持续发光的DNA探针，直接读取目标分子的位置", "C. 通过DNA聚合酶延伸探针，产生稳定荧光信号进行定位", "D. 通过限制性内切酶切割目标DNA，产生荧光片段进行定位"], "a": "A", "e": "DNA-PAINT利用DNA杂交的瞬时结合和解离：短链DNA探针与目标分子上的对接链互补，结合时发出荧光，解离时荧光消失，通过荧光闪烁实现高分辨率单分子定位。"}, "cards": [{"front": "影响复性的因素有哪些？什么是淬火？", "back": "影响因素：温度（最佳比Tm低约25℃）、DNA浓度（越高越快）、复性时间（降温要慢）、DNA复杂度（越小越单一越快）。淬火是将热DNA溶液迅速插入冰中，使变性DNA保持单链状态。", "mnemonic": "温浓时杂四因素，淬火冰镇保单链", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_10", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "关于DNA超螺旋的描述，下列哪项是正确的？", "o": ["A. 正超螺旋有利于DNA解链", "B. 负超螺旋使DNA更加紧密，不利于解链", "C. 负超螺旋有利于DNA解链，促进复制和转录", "D. 超螺旋只存在于环状DNA中"], "a": "C", "e": "负超螺旋使DNA双链更容易解开，从而促进复制和转录。正超螺旋则使解链更困难。超螺旋也存在于线性DNA的拓扑约束区域。", "kp": "ch02_s2_2"}, {"id": "ch02_mcq_11", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "DNA的熔解温度（Tm）是指：", "o": ["A. DNA完全变性时的温度", "B. DNA两条链半解离时的温度", "C. DNA开始变性时的温度", "D. DNA复性一半时的温度"], "a": "B", "e": "Tm是DNA两条链半解离或变性的温度，即吸光值增加到最大值一半时的温度。", "kp": "ch02_s2_7"}, {"id": "ch02_mcq_12", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "下列哪种条件不利于DNA复性？", "o": ["A. 温度比Tm低约25℃", "B. 高DNA浓度", "C. 缓慢降温", "D. 高温（接近Tm）"], "a": "D", "e": "复性的最佳温度比Tm低约25℃，高温接近Tm会使DNA保持变性状态，不利于复性。", "kp": "ch02_s2_10"}, {"id": "ch02_mcq_13", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "关于DNA杂交，下列哪项描述是错误的？", "o": ["A. 杂交可以发生在DNA和RNA之间", "B. 杂交需要两条链完全互补", "C. 杂交是许多分子生物学技术的基础", "D. 杂交的严格性受温度和盐浓度影响"], "a": "B", "e": "杂交可以发生在互补或接近互补的序列之间，不需要完全互补。", "kp": "ch02_s2_10"}, {"id": "ch02_mcq_14", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "在DNA复制过程中，解旋酶解开双链会导致什么后果？", "o": ["A. 形成负超螺旋，促进解链", "B. 形成正超螺旋，阻碍解链", "C. 形成连锁，阻碍解链", "D. 形成纽结，促进解链"], "a": "B", "e": "解旋酶解开双链时，未解链部分缠绕更紧密，形成正超螺旋压力，阻碍解链继续进行，需要拓扑异构酶来释放张力。", "kp": "ch02_s2_4"}], "judge": [{"id": "ch02_judge_5", "modI": 2, "q": "碱基堆积力对双螺旋稳定性贡献最大，氢键保证配对特异性。", "a": "对", "e": "维持双螺旋稳定的因素中，碱基堆积力对双螺旋稳定性贡献最大，氢键保证配对特异性，离子键维持骨架电荷平衡。", "kp": "ch02_s2_6"}, {"id": "ch02_judge_6", "modI": 2, "q": "DNA变性过程中，氢键断裂，碱基堆积力被破坏，共价键也断裂。", "a": "错", "e": "DNA变性过程中，氢键断裂，碱基堆积力被破坏，但共价键不受影响。", "kp": "ch02_s2_6"}], "fill": [{"id": "ch02_fill_5", "modI": 2, "q": "DNA变性后，紫外吸收（260 nm）增加，称为________效应。", "a": "增色", "kp": "ch02_s2_6"}, {"id": "ch02_fill_6", "modI": 2, "q": "DNA的熔解温度（Tm）是两条链半解离或变性的温度，即吸光值增加到最大值的一半时的温度。Tm值与________含量正相关。", "a": "GC", "kp": "ch02_s2_7"}], "short": [{"id": "ch02_short_3", "modI": 2, "q": "简述维持DNA双螺旋稳定的因素。", "a": "①碱基对之间的氢键：保证配对特异性；②碱基堆积力：包括碱基疏水相互作用和范德华力，对双螺旋稳定性贡献最大；③磷酸基团负电荷与介质中阳离子形成的离子键：可屏蔽静电排斥，维持骨架电荷平衡；④碱基的分子内能。这些因素共同决定DNA的稳定性与解链行为。", "kp": "ch02_s2_2"}], "calc": [{"id": "ch02_calc_1", "modI": 2, "q": "论述DNA复制过程中拓扑压力的产生及拓扑异构酶的作用机制。", "a": "在DNA复制过程中，解旋酶解开双链，未解链部分的缠绕更加紧密，形成正超螺旋压力。这种压力使解链不能继续进行，因此需要拓扑异构酶来释放这种张力。拓扑异构酶I切割一条链并旋转，拓扑异构酶II切割两条链并传递另一条双链通过，从而改变连环数。这一机制保证了复制叉的顺利推进。此外，细胞内的DNA通常处于负超螺旋状态，这有利于解链过程；在真核生物中，核小体的形成引入负超螺旋，帮助DNA压缩；拓扑异构酶可以松弛超螺旋DNA，通过暂时切断DNA链来改变拓扑状态，维持DNA的适当拓扑状态。", "steps": "①解旋酶解开双链产生正超螺旋压力；②正超螺旋压力阻碍解链；③拓扑异构酶I切割一条链并旋转；④拓扑异构酶II切割两条链并传递另一条双链通过；⑤改变连环数，释放张力；⑥保证复制叉顺利推进；⑦负超螺旋有利于解链，核小体引入负超螺旋；⑧拓扑异构酶维持适当拓扑状态。", "kp": "ch02_s2_4"}], "term": [{"id": "ch02_term_6", "modI": 2, "term": "Supercoiling", "def": "超螺旋：DNA链所承受扭转应力的一种表现，通常指DNA相对于正常状态发生过度缠绕或缠绕不足。要点：①是同一DNA分子内的过度缠绕或缠绕不足；②使DNA更紧密，有利于包装；③分为正超螺旋和负超螺旋；④负超螺旋有利于解链，促进复制和转录；⑤复制和转录时解旋会产生正超螺旋压力。", "kp": "ch02_s2_1"}, {"id": "ch02_term_7", "modI": 2, "term": "Topoisomerase", "def": "拓扑异构酶：通过切断和重新连接DNA链来调节超螺旋水平的酶。要点：①拓扑异构酶I切割一条链并旋转；②拓扑异构酶II切割两条链并传递另一条双链通过；③改变连环数；④解决复制和转录中的拓扑压力；⑤维持DNA适当拓扑状态。", "kp": "ch02_s2_1"}, {"id": "ch02_term_8", "modI": 2, "term": "DNA denaturation", "def": "DNA变性（DNA熔解）：DNA双螺旋的两条链分离的过程。要点：①促进条件包括加热、低离子强度、高pH和有机溶剂；②氢键断裂，碱基堆积力被破坏，但共价键不受影响；③变性后260 nm紫外吸收增加，称为增色效应；④常用于检测DNA变性和复性。", "kp": "ch02_s2_10"}, {"id": "ch02_term_9", "modI": 2, "term": "Tm", "def": "熔解温度（Tm）：两条链半解离或变性的温度，即吸光值增加到最大值的一半时的温度。要点：①通过260 nm处吸光度增加来测量；②Tm值与GC含量正相关；③GC含量越高，Tm越高；④因为GC碱基对有三个氢键，比AT碱基对更稳定；⑤可用于估计DNA的GC含量和PCR引物设计。", "kp": "ch02_s2_7"}]}, {"i": 3, "name": "模块四：基因的分类与结构", "slides": [{"i": 0, "sec": "基因的分类与结构", "title": "基因概述 (p33)", "notes": "本页是“基因”主题的引入页，标题为“2. Gene”。基因是遗传信息的基本功能单位，通常指合成一条有功能多肽或RNA分子所必需的全部核苷酸序列。在分子生物学中，基因不仅包括编码序列，还包括调控其表达的各类元件。理解基因的概念是学习染色体结构、DNA复制、转录和翻译的基础。后续内容将从基因的细胞定位、产物类型以及原核与真核基因结构差异等方面展开分类与解析。", "page": 33, "level": "掌握", "img": "assets/img/ch02/p033.jpg", "anim": null, "fig": null, "points": ["基因是遗传信息的基本功能单位，通常指合成一条有功能多肽或RNA分子所必需的全部核苷酸序列。", "基因不仅包括编码序列，还包括调控其表达的各类元件。", "理解基因概念是学习染色体结构、DNA复制、转录和翻译的基础。", "后续从细胞定位、产物类型及原核与真核基因结构差异等方面展开分类与解析。"], "check": {"q": "关于基因的经典定义，下列哪项最准确？", "o": ["A. 基因是DNA分子上任意一段可被转录的序列", "B. 基因是合成一条有功能多肽或RNA分子所必需的全部核苷酸序列", "C. 基因是染色体上能被核糖体结合的特定序列", "D. 基因是编码蛋白质的连续密码子序列，不含任何调控元件"], "a": "B", "e": "基因是遗传信息的基本功能单位，经典定义指合成一条有功能多肽或RNA分子所必需的全部核苷酸序列，既包括编码序列也包括调控其表达的元件。"}, "cards": [{"front": "基因的经典定义是什么？", "back": "合成一条有功能多肽或RNA分子所必需的全部核苷酸序列，包括编码序列和调控元件。", "mnemonic": "基因=编码+调控，产物为蛋白或RNA", "useImg": false}]}, {"i": 1, "sec": "基因的分类与结构", "title": "按细胞定位分类：核基因与细胞质基因 (p34)", "notes": "按细胞定位，基因可分为核基因和细胞质基因。核基因位于细胞核内的染色体上，在真核细胞中占绝大多数，遵循孟德尔遗传规律。细胞质基因位于核外细胞质中，如细菌质粒、动植物线粒体基因和植物叶绿体基因。细胞质基因常表现为母系遗传或非孟德尔遗传，且线粒体和叶绿体基因组的复制与表达部分依赖核基因编码的蛋白，因此称为半自主性。该分类有助于理解核质互作与细胞器遗传。", "page": 34, "level": "掌握", "img": "assets/img/ch02/p034.jpg", "anim": null, "fig": null, "points": ["按细胞定位，基因分为核基因和细胞质基因。", "核基因位于细胞核内染色体上，在真核细胞中占绝大多数，遵循孟德尔遗传规律。", "细胞质基因位于核外细胞质中，如细菌质粒、动植物线粒体基因和植物叶绿体基因。", "细胞质基因常表现为母系遗传或非孟德尔遗传，线粒体和叶绿体基因组为半自主性。", "该分类有助于理解核质互作与细胞器遗传。"], "check": {"q": "下列关于核基因与细胞质基因的叙述，正确的是？", "o": ["A. 核基因位于染色体上，遵循孟德尔遗传规律；细胞质基因常表现为母系遗传或非孟德尔遗传", "B. 细胞质基因全部位于线粒体中，与叶绿体无关", "C. 核基因在真核细胞中只占少数，细胞质基因占绝大多数", "D. 细胞质基因完全自主复制与表达，不依赖核基因编码的蛋白"], "a": "A", "e": "核基因位于细胞核染色体上，遵循孟德尔规律；细胞质基因位于质粒、线粒体、叶绿体等，常呈母系或非孟德尔遗传，且为半自主性，部分依赖核基因产物。"}, "cards": [{"front": "按细胞定位，基因分为哪两类？", "back": "核基因（染色体上，占绝大多数，遵循孟德尔遗传）和细胞质基因（质粒、线粒体、叶绿体基因）。", "mnemonic": "核内孟德尔，核外母系传", "useImg": false}]}, {"i": 2, "sec": "基因的分类与结构", "title": "细胞质基因的特点：质粒与细胞器基因 (p35)", "notes": "本页进一步说明细胞质基因的典型代表。质粒是染色体或拟核以外的DNA分子，具有自主复制能力，可赋予宿主菌某些生物学性状，如抗药性、产毒素等，有利于细菌在特定环境条件下生存，也是基因工程的重要载体。线粒体基因存在于动植物细胞，叶绿体基因存在于植物细胞，它们均能进行半自主复制，自主程度有限，许多功能蛋白由核基因编码。这些细胞器基因的突变与多种人类疾病和植物性状相关。", "page": 35, "level": "理解", "img": "assets/img/ch02/p035.jpg", "anim": null, "fig": null, "points": ["质粒是染色体或拟核以外的DNA分子，具有自主复制能力，可赋予宿主菌某些生物学性状。", "质粒有利于细菌在特定环境条件下生存，也是基因工程的重要载体。", "线粒体基因存在于动植物细胞，叶绿体基因存在于植物细胞，均能进行半自主复制。", "细胞器基因自主程度有限，许多功能蛋白由核基因编码。", "细胞器基因突变与多种人类疾病和植物性状相关。"], "check": {"q": "关于质粒的叙述，下列哪项正确？", "o": ["A. 质粒是染色体或拟核以外的DNA分子，具有自主复制能力，可作为基因工程载体", "B. 质粒是细菌染色体的一部分，不能独立复制", "C. 质粒只能赋予细菌产毒素能力，与抗药性无关", "D. 质粒存在于所有动植物细胞中，属于细胞器基因组"], "a": "A", "e": "质粒是染色体或拟核以外的DNA分子，能自主复制，可赋予宿主抗药性、产毒素等性状，也是基因工程的重要载体。"}, "cards": [{"front": "细胞质基因的遗传特点是什么？", "back": "常表现为母系遗传或非孟德尔遗传；线粒体和叶绿体基因组为半自主性，复制与表达部分依赖核基因编码的蛋白。", "mnemonic": "半自主、母系传、靠核帮", "useImg": false}]}, {"i": 3, "sec": "基因的分类与结构", "title": "按基因产物分类：蛋白编码基因与功能RNA基因 (p36)", "notes": "按产物类型，基因主要分为蛋白编码基因和功能RNA基因。蛋白编码基因最终翻译成多肽或蛋白质；功能RNA基因转录后不翻译，直接以RNA形式发挥功能，如rRNA基因（rDNA）和tRNA基因（tDNA）。此外还有snRNA、miRNA等。基因的经典定义是合成一条有功能多肽或RNA分子所必需的全部核苷酸序列，这一定义涵盖了这两大类基因。该分类反映了基因表达终产物的多样性，是理解基因功能与基因组复杂度的重要基础。", "page": 36, "level": "掌握", "img": "assets/img/ch02/p036.jpg", "anim": null, "fig": null, "points": ["按产物类型，基因主要分为蛋白编码基因和功能RNA基因。", "蛋白编码基因最终翻译成多肽或蛋白质。", "功能RNA基因转录后不翻译，直接以RNA形式发挥功能，如rRNA基因（rDNA）和tRNA基因（tDNA）。", "此外还有snRNA、miRNA等。", "基因的经典定义涵盖这两大类基因，该分类反映了基因表达终产物的多样性。"], "check": {"q": "按基因产物分类，下列哪项属于功能RNA基因？", "o": ["A. 编码阻遏蛋白的调节基因", "B. 编码酶的结构基因", "C. rRNA基因（rDNA）和tRNA基因（tDNA）", "D. 编码转录激活因子的基因"], "a": "C", "e": "功能RNA基因转录后不翻译，直接以RNA形式发挥功能，如rRNA基因和tRNA基因；其余选项均属蛋白编码基因。"}, "cards": [{"front": "质粒是什么？有何特点与用途？", "back": "染色体或拟核以外的DNA分子，能自主复制，可赋予宿主抗药性、产毒素等性状，是基因工程的重要载体。", "mnemonic": "质粒=染色体外+自主复制+工程载体", "useImg": false}]}, {"i": 4, "sec": "基因的分类与结构", "title": "蛋白编码基因：结构基因与调节基因 (p37)", "notes": "蛋白编码基因可分为结构基因和调节基因。结构基因可转录成mRNA并翻译成多肽链，构成结构蛋白、酶和激素等，直接参与细胞组成与代谢。调节基因编码阻遏蛋白或转录激活因子等调控蛋白，它们通常具有特殊结构域，能进入细胞核并结合DNA序列，调节结构基因的表达。调节基因本质仍是通过转录和翻译形成蛋白质，但其功能是调控而非直接执行代谢，常通过信号放大影响众多下游基因，是基因表达调控网络的关键节点。", "page": 37, "level": "掌握", "img": "assets/img/ch02/p037.jpg", "anim": null, "fig": null, "points": ["蛋白编码基因可分为结构基因和调节基因。", "结构基因可转录成mRNA并翻译成多肽链，构成结构蛋白、酶和激素等，直接参与细胞组成与代谢。", "调节基因编码阻遏蛋白或转录激活因子等调控蛋白，能进入细胞核并结合DNA序列，调节结构基因的表达。", "调节基因本质仍是通过转录和翻译形成蛋白质，但其功能是调控而非直接执行代谢。", "调节基因常通过信号放大影响众多下游基因，是基因表达调控网络的关键节点。"], "check": {"q": "关于结构基因与调节基因的叙述，正确的是？", "o": ["A. 结构基因编码调控蛋白，调节基因编码酶和结构蛋白", "B. 结构基因转录成mRNA并翻译成多肽，直接参与细胞组成与代谢；调节基因编码阻遏蛋白或转录激活因子等调控蛋白", "C. 调节基因不经过转录和翻译，直接以DNA形式发挥调控作用", "D. 结构基因与调节基因的区别在于前者不翻译，后者翻译"], "a": "B", "e": "结构基因产物直接参与细胞组成与代谢；调节基因编码阻遏蛋白或转录激活因子等，通过结合DNA调控结构基因表达，其本质仍经转录翻译形成蛋白质。"}, "cards": [{"front": "按基因产物分类，基因分为哪两大类？", "back": "蛋白编码基因（翻译成多肽/蛋白质）和功能RNA基因（如rRNA基因、tRNA基因，不翻译直接以RNA发挥功能）。", "mnemonic": "产物两类：蛋白+功能RNA", "useImg": false}]}, {"i": 5, "sec": "基因的分类与结构", "title": "基因结构示意图：ORF、UTR与转录单位 (p38)", "notes": "本页为基因结构示意图，引出结构特征部分。图中通常标示开放阅读框（ORF，编码区）、非翻译区（UTR）和转录单位。ORF指从起始密码子到终止密码子的一段连续编码序列；UTR位于mRNA两端，不编码蛋白但参与稳定性、定位和翻译调控。转录单位是可转录为mRNA的一段DNA区域。表示基因结构时通常只用DNA编码链的碱基顺序，左侧为5′端，右侧为3′端。理解这些元件是分析原核与真核基因结构差异的基础。", "page": 38, "level": "掌握", "img": "assets/img/ch02/p038.jpg", "anim": null, "fig": "图中通常标示开放阅读框（ORF，编码区）、非翻译区（UTR）和转录单位。看这张图时，注意ORF位于中间，UTR分布在mRNA两端，转录单位覆盖整个可转录区域；同时注意DNA编码链的5′→3′方向。", "points": ["开放阅读框（ORF）指从起始密码子到终止密码子的一段连续编码序列。", "UTR位于mRNA两端，不编码蛋白但参与稳定性、定位和翻译调控。", "转录单位是可转录为mRNA的一段DNA区域。", "表示基因结构时通常只用DNA编码链的碱基顺序，左侧为5′端，右侧为3′端。", "理解这些元件是分析原核与真核基因结构差异的基础。"], "check": {"q": "关于ORF、UTR与转录单位的叙述，正确的是？", "o": ["A. ORF指从起始密码子到终止密码子的一段连续编码序列，UTR位于mRNA两端但不编码蛋白", "B. UTR位于ORF内部，直接参与蛋白质翻译", "C. 转录单位仅指ORF，不包括UTR", "D. 表示基因结构时通常用RNA的碱基顺序，左侧为3′端"], "a": "A", "e": "ORF是从起始密码子到终止密码子的连续编码序列；UTR位于mRNA两端，不编码蛋白但参与稳定性、定位和翻译调控；表示基因结构通常用DNA编码链，左5′右3′。"}, "cards": [{"front": "蛋白编码基因可分为哪两类？各自功能是什么？", "back": "结构基因：转录成mRNA并翻译成多肽，直接参与细胞组成与代谢；调节基因：编码阻遏蛋白或转录激活因子，调控结构基因表达。", "mnemonic": "结构干活，调节指挥", "useImg": false}]}, {"i": 6, "sec": "基因的分类与结构", "title": "原核基因结构特征：操纵子模型 (p39)", "notes": "原核基因结构的核心特征是操纵子模型。一个转录单位可能包括多个开放阅读框，即多个结构基因共用一个启动子和终止子，转录成一条多顺反子mRNA。操纵子中的基因通常功能相关，如代谢途径中的多个酶基因，便于协同调控。所谓“连续”是相对的，不同转录单位之间存在间隔区。操纵子模型由Jacob和Monod提出，是原核基因表达调控的经典范式，也说明原核基因常以功能单元成簇排列。", "page": 39, "level": "掌握", "img": "assets/img/ch02/p039.jpg", "anim": null, "fig": null, "points": ["原核基因结构的核心特征是操纵子模型。", "一个转录单位可能包括多个开放阅读框，即多个结构基因共用一个启动子和终止子，转录成一条多顺反子mRNA。", "操纵子中的基因通常功能相关，如代谢途径中的多个酶基因，便于协同调控。", "所谓“连续”是相对的，不同转录单位之间存在间隔区。", "操纵子模型由Jacob和Monod提出，是原核基因表达调控的经典范式。"], "check": {"q": "关于原核基因操纵子模型的叙述，正确的是？", "o": ["A. 一个转录单位只含一个开放阅读框，转录为单顺反子mRNA", "B. 多个结构基因共用一个启动子和终止子，转录成一条多顺反子mRNA，基因常功能相关", "C. 操纵子中基因功能无关，仅因位置相邻而共转录", "D. 操纵子模型由Watson和Crick提出，用于解释真核基因表达调控"], "a": "B", "e": "操纵子中多个结构基因共用一个启动子和终止子，转录成多顺反子mRNA，基因通常功能相关，便于协同调控；该模型由Jacob和Monod提出。"}, "cards": [{"front": "ORF和UTR分别是什么？", "back": "ORF（开放阅读框）：从起始密码子到终止密码子的连续编码序列；UTR（非翻译区）：mRNA两端不编码蛋白但参与稳定性、定位和翻译调控的序列。", "mnemonic": "ORF编码，UTR调控", "useImg": false}]}, {"i": 7, "sec": "基因的分类与结构", "title": "原核mRNA：多顺反子mRNA (p40)", "notes": "原核生物mRNA多为多顺反子mRNA，即一个mRNA分子上携有几种多肽分子的氨基酸序列信息，能翻译成两条或多条多肽链。这是因为一个转录单位包含多个ORF，核糖体可分别在各ORF的起始密码子处起始翻译。多顺反子mRNA使功能相关基因的表达同步协调，提高调控效率。与之相对，真核mRNA通常为单顺反子。多顺反子mRNA是原核基因表达的重要特征，也是理解操纵子调控和抗生素作用机制的基础。", "page": 40, "level": "掌握", "img": "assets/img/ch02/p040.jpg", "anim": null, "fig": null, "points": ["原核生物mRNA多为多顺反子mRNA，即一个mRNA分子上携有几种多肽分子的氨基酸序列信息。", "多顺反子mRNA能翻译成两条或多条多肽链，因为一个转录单位包含多个ORF。", "核糖体可分别在各ORF的起始密码子处起始翻译。", "多顺反子mRNA使功能相关基因的表达同步协调，提高调控效率。", "真核mRNA通常为单顺反子，多顺反子mRNA是原核基因表达的重要特征。"], "check": {"q": "关于原核生物多顺反子mRNA的叙述，正确的是：", "o": ["A. 一个mRNA分子只携带一种多肽的氨基酸序列信息", "B. 一个mRNA分子上携有几种多肽的氨基酸序列信息，可翻译成多条多肽链", "C. 多顺反子mRNA仅存在于真核生物中", "D. 多顺反子mRNA不能使功能相关基因的表达同步协调"], "a": "B", "e": "原核mRNA多为多顺反子，一个mRNA携有几种多肽信息，能翻译成两条或多条多肽链，使功能相关基因表达同步协调。"}, "cards": [{"front": "原核基因结构的核心特征是什么？", "back": "操纵子模型：多个结构基因共用一个启动子和终止子，转录成一条多顺反子mRNA，功能相关基因成簇排列便于协同调控。", "mnemonic": "操纵子=多基因+一启动子+多顺反子", "useImg": false}]}, {"i": 8, "sec": "基因的分类与结构", "title": "重叠基因 (p41)", "notes": "重叠基因指两个或两个以上的基因共用一段DNA顺序的现象，在原核生物和病毒中较为常见。重叠方式多样，如大基因内包含小基因、前后两个基因首尾重叠、几个基因部分重叠等。重叠基因可使有限的基因组携带更多遗传信息，提高编码效率，但也限制了序列的进化自由度。典型例子如噬菌体ΦX174的基因组。重叠基因的发现打破了基因彼此独立、互不重叠的传统观念，对理解基因组经济性和基因进化具有重要意义。", "page": 41, "level": "理解", "img": "assets/img/ch02/p041.jpg", "anim": null, "fig": null, "points": ["重叠基因指两个或两个以上的基因共用一段DNA顺序的现象，在原核生物和病毒中较为常见。", "重叠方式多样，如大基因内包含小基因、前后两个基因首尾重叠、几个基因部分重叠等。", "重叠基因可使有限的基因组携带更多遗传信息，提高编码效率，但也限制了序列的进化自由度。", "典型例子如噬菌体ΦX174的基因组。", "重叠基因的发现打破了基因彼此独立、互不重叠的传统观念，对理解基因组经济性和基因进化具有重要意义。"], "check": {"q": "关于重叠基因的叙述，错误的是：", "o": ["A. 指两个或两个以上基因共用一段DNA顺序的现象", "B. 在原核生物和病毒中较为常见", "C. 可使有限的基因组携带更多遗传信息，提高编码效率", "D. 重叠基因的发现支持了基因彼此独立、互不重叠的传统观念"], "a": "D", "e": "重叠基因的发现打破了基因彼此独立、互不重叠的传统观念，而非支持该观念。"}, "cards": [{"front": "什么是多顺反子mRNA？其意义是什么？", "back": "一个mRNA分子上携有几种多肽的氨基酸序列信息，能翻译成多条多肽链。使功能相关基因表达同步协调，提高调控效率。", "mnemonic": "一mRNA，多肽链，同步调", "useImg": false}]}, {"i": 9, "sec": "基因的分类与结构", "title": "真核基因的断裂结构：外显子与内含子 (p42)", "notes": "真核生物基因多为断裂结构，由外显子和内含子交替组成。外显子是编码序列，最终出现在成熟RNA产物中；内含子是非编码序列，通常不编码蛋白质，在转录后经剪接被去除。内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG。大多数高等真核基因被非编码DNA中断。断裂结构使真核基因可通过可变剪接产生多种mRNA和蛋白质，极大扩展了遗传信息容量，是真核基因表达调控和蛋白质多样性的重要基础。", "page": 42, "level": "掌握", "img": "assets/img/ch02/p042.jpg", "anim": null, "fig": null, "points": ["真核生物基因多为断裂结构，由外显子和内含子交替组成。", "外显子是编码序列，最终出现在成熟RNA产物中；内含子是非编码序列，在转录后经剪接被去除。", "内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG。", "大多数高等真核基因被非编码DNA中断。", "断裂结构使真核基因可通过可变剪接产生多种mRNA和蛋白质，极大扩展了遗传信息容量。"], "check": {"q": "关于真核基因断裂结构的叙述，正确的是：", "o": ["A. 外显子是非编码序列，在剪接中被去除", "B. 内含子是编码序列，最终出现在成熟RNA中", "C. 内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG", "D. 断裂结构使真核基因无法通过可变剪接产生多种mRNA"], "a": "C", "e": "内含子边界常遵循GT-AG规则；外显子为编码序列，内含子为非编码序列并被剪接去除，断裂结构可通过可变剪接产生多种mRNA。"}, "cards": [{"front": "什么是重叠基因？其意义是什么？", "back": "两个或以上基因共用一段DNA序列，常见于原核生物和病毒。可使有限基因组携带更多遗传信息，提高编码效率，但限制进化自由度。", "mnemonic": "共用序列，经济编码，进化受限", "useImg": false}]}, {"i": 10, "sec": "基因的分类与结构", "title": "断裂基因的分布与进化 (p43)", "notes": "断裂基因在细菌和噬菌体中也有发现，但极为罕见；酵母中绝大多数基因（>96%）不是断裂基因，平均长约1.4 kb，很少超过5 kb。哺乳动物中仅约6%的基因编码序列不被中断，约50%的基因含10个以上内含子，许多基因长度在5 kb至100 kb之间。不同物种相关基因比较表明，外显子序列通常保守，而内含子进化快得多，原因可能是内含子缺乏产生有用蛋白质序列的选择压力。这揭示了断裂基因在真核基因组中的普遍性及其进化意义。", "page": 43, "level": "理解", "img": "assets/img/ch02/p043.jpg", "anim": null, "fig": null, "points": ["断裂基因在细菌和噬菌体中也有发现，但极为罕见。", "酵母中绝大多数基因（>96%）不是断裂基因，平均长约1.4 kb，很少超过5 kb。", "哺乳动物中仅约6%的基因编码序列不被中断，约50%的基因含10个以上内含子，许多基因长度在5 kb至100 kb之间。", "不同物种相关基因比较表明，外显子序列通常保守，而内含子进化快得多。", "内含子进化快的原因可能是缺乏产生有用蛋白质序列的选择压力。"], "check": {"q": "关于断裂基因的分布与进化，叙述正确的是：", "o": ["A. 断裂基因在细菌和噬菌体中极为常见", "B. 酵母中绝大多数基因（>96%）不是断裂基因", "C. 哺乳动物中约50%的基因编码序列不被中断", "D. 不同物种相关基因比较表明，内含子序列通常比外显子更保守"], "a": "B", "e": "酵母中绝大多数基因（>96%）不是断裂基因；断裂基因在细菌和噬菌体中极为罕见；哺乳动物仅约6%的基因编码序列不被中断；外显子通常保守，内含子进化快得多。"}, "cards": [{"front": "真核基因的断裂结构由什么组成？内含子边界有何规则？", "back": "由外显子（编码序列，出现在成熟RNA中）和内含子（非编码序列，转录后剪接去除）交替组成；内含子边界常遵循GT-AG规则（5′端GT，3′端AG）。", "mnemonic": "外显编码，内含剪去，GT-AG", "useImg": false}]}, {"i": 11, "sec": "基因的分类与结构", "title": "真核mRNA：单顺反子mRNA (p44)", "notes": "真核生物mRNA通常为单顺反子mRNA，即一个mRNA分子上只携有一种多肽分子的氨基酸序列信息，只能翻译成一条多肽链。这与原核多顺反子mRNA形成鲜明对比。真核基因一般一个基因对应一个转录单位，转录后经过加帽、加尾和剪接等加工，成熟mRNA只含一个ORF。单顺反子结构使每个基因可独立调控，有利于真核生物复杂发育和细胞分化。该特征是理解真核基因表达调控和原核真核差异的关键。", "page": 44, "level": "掌握", "img": "assets/img/ch02/p044.jpg", "anim": null, "fig": null, "points": ["真核生物mRNA通常为单顺反子mRNA，即一个mRNA分子上只携有一种多肽分子的氨基酸序列信息。", "单顺反子mRNA只能翻译成一条多肽链，与原核多顺反子mRNA形成鲜明对比。", "真核基因一般一个基因对应一个转录单位，转录后经过加帽、加尾和剪接等加工，成熟mRNA只含一个ORF。", "单顺反子结构使每个基因可独立调控，有利于真核生物复杂发育和细胞分化。", "该特征是理解真核基因表达调控和原核真核差异的关键。"], "check": {"q": "关于真核生物单顺反子mRNA的叙述，正确的是：", "o": ["A. 一个mRNA分子上只携有一种多肽分子的氨基酸序列信息", "B. 一个mRNA分子可翻译成多条不同的多肽链", "C. 真核基因一般一个转录单位对应多个基因", "D. 单顺反子结构不利于每个基因的独立调控"], "a": "A", "e": "真核mRNA通常为单顺反子，一个mRNA只携有一种多肽信息，只翻译成一条多肽链，使每个基因可独立调控。"}, "cards": [{"front": "真核mRNA与原核mRNA在顺反子结构上有何区别？", "back": "真核mRNA通常为单顺反子（一个mRNA只含一个ORF，翻译一条多肽链），可独立调控；原核mRNA多为多顺反子（一个mRNA含多个ORF，翻译多条多肽链）。", "mnemonic": "真核单，原核多", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_15", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "下列哪项属于细胞质基因？", "o": ["A. 染色体上的核基因", "B. 细菌质粒基因", "C. 核糖体RNA基因", "D. 组蛋白基因"], "a": "B", "e": "细胞质基因位于细胞核以外的细胞质中，如细菌质粒、线粒体基因和叶绿体基因。核基因位于染色体上，rRNA基因和组蛋白基因均属核基因。", "kp": "ch02_s3_1"}, {"id": "ch02_mcq_16", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "关于原核生物mRNA，下列说法正确的是：", "o": ["A. 通常为单顺反子mRNA", "B. 一个mRNA只能翻译成一条多肽链", "C. 通常为多顺反子mRNA，可翻译成多条多肽链", "D. 不经过转录直接翻译"], "a": "C", "e": "原核生物mRNA多为多顺反子mRNA，一个mRNA分子上携有几种多肽的氨基酸序列信息，能翻译成两条或多条多肽链。真核mRNA通常为单顺反子。", "kp": "ch02_s3_7"}, {"id": "ch02_mcq_17", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "真核生物断裂基因中，内含子的典型边界特征是：", "o": ["A. 5′端AG，3′端GT", "B. 5′端GT，3′端AG", "C. 5′端AT，3′端GC", "D. 5′端GC，3′端AT"], "a": "B", "e": "真核基因内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG，这是剪接体识别内含子的重要信号。", "kp": "ch02_s3_9"}, {"id": "ch02_mcq_18", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "关于重叠基因，下列描述错误的是：", "o": ["A. 两个或两个以上基因共用一段DNA顺序", "B. 可使有限的基因组携带更多遗传信息", "C. 在真核生物中极为普遍", "D. 有多种重叠方式，如大基因内包含小基因"], "a": "C", "e": "重叠基因指两个或两个以上基因共用一段DNA顺序，在原核生物和病毒中较常见，并非在真核生物中极为普遍。它可提高编码效率，有多种重叠方式。", "kp": "ch02_s3_8"}, {"id": "ch02_mcq_19", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "按基因产物分类，tRNA基因属于：", "o": ["A. 蛋白编码基因", "B. 功能RNA基因", "C. 调节基因", "D. 结构基因"], "a": "B", "e": "tRNA基因转录后不翻译，直接以RNA形式发挥功能，属于功能RNA基因。蛋白编码基因包括结构基因和调节基因，最终产物为蛋白质。", "kp": "ch02_s3_3"}], "judge": [{"id": "ch02_judge_7", "modI": 3, "q": "原核生物mRNA多为单顺反子mRNA，真核生物mRNA通常为多顺反子mRNA。", "a": "错", "e": "原核生物mRNA多为多顺反子mRNA，即一个mRNA分子上携有几种多肽分子的氨基酸序列信息；真核生物mRNA通常为单顺反子mRNA，一个mRNA分子上只携有一种多肽分子的氨基酸序列信息。", "kp": "ch02_s3_7"}, {"id": "ch02_judge_8", "modI": 3, "q": "重叠基因指两个或两个以上的基因共用一段DNA顺序的现象，在原核生物和病毒中较为常见。", "a": "对", "e": "重叠基因可使有限的基因组携带更多遗传信息，提高编码效率，典型例子如噬菌体ΦX174的基因组。", "kp": "ch02_s3_8"}], "fill": [{"id": "ch02_fill_7", "modI": 3, "q": "原核生物mRNA多为________mRNA，即一个mRNA分子上携有几种多肽分子的氨基酸序列信息。", "a": "多顺反子", "kp": "ch02_s3_7"}, {"id": "ch02_fill_8", "modI": 3, "q": "真核生物基因多为断裂结构，由________和________交替组成。", "a": "外显子,内含子", "kp": "ch02_s3_9"}], "short": [{"id": "ch02_short_4", "modI": 3, "q": "简述原核基因结构的主要特征。", "a": "①操纵子模型：一个转录单位可能包括多个开放阅读框，多个结构基因共用一个启动子和终止子；②转录成一条多顺反子mRNA；③操纵子中的基因通常功能相关，便于协同调控；④结构基因序列通常是连续的，没有内含子，转录后一般不需要剪接；⑤基因组中重复序列很少，编码蛋白质的结构基因多为单拷贝，但rRNA基因往往是多拷贝；⑥存在重叠基因现象；⑦具有转座现象。", "kp": "ch02_s3_6"}], "calc": [{"id": "ch02_calc_2", "modI": 3, "q": "论述真核生物基因断裂结构的特征、分布及其进化意义。", "a": "真核生物基因多为断裂结构，由外显子和内含子交替组成。外显子是编码序列，最终出现在成熟RNA产物中；内含子是非编码序列，通常不编码蛋白质，在转录后经剪接被去除。内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG。大多数高等真核基因被非编码DNA中断。断裂结构使真核基因可通过可变剪接产生多种mRNA和蛋白质，极大扩展了遗传信息容量，是真核基因表达调控和蛋白质多样性的重要基础。分布：断裂基因在细菌和噬菌体中也有发现，但极为罕见；酵母中绝大多数基因（>96%）不是断裂基因，平均长约1.4 kb，很少超过5 kb；哺乳动物中仅约6%的基因编码序列不被中断，约50%的基因含10个以上内含子，许多基因长度在5 kb至100 kb之间。进化意义：不同物种相关基因比较表明，外显子序列通常保守，而内含子进化快得多，原因可能是内含子缺乏产生有用蛋白质序列的选择压力。这揭示了断裂基因在真核基因组中的普遍性及其进化意义。", "steps": "①真核基因由外显子和内含子交替组成；②外显子编码，内含子非编码；③内含子边界常遵循GT-AG规则；④可变剪接产生多种mRNA和蛋白质；⑤扩展遗传信息容量；⑥断裂基因在细菌和噬菌体中罕见；⑦酵母中>96%基因不是断裂基因；⑧哺乳动物中仅约6%基因编码序列不被中断；⑨外显子保守，内含子进化快；⑩内含子缺乏选择压力。", "kp": "ch02_s3_9"}], "term": [{"id": "ch02_term_10", "modI": 3, "term": "Operon", "def": "操纵子：原核生物基因表达调控的典型单位。要点：①由Jacob和Monod提出；②通常由启动子、操纵基因和一组功能相关的结构基因组成；③受同一调控序列控制；④转录成多顺反子mRNA；⑤一个开关同时控制多个相关蛋白合成，提高效率并节约调控资源。", "kp": "ch02_s3_6"}]}, {"i": 4, "name": "模块五：基因组——细菌基因组与质粒", "slides": [{"i": 0, "sec": "基因组概述", "title": "基因组章节导引 (p45)", "notes": "本页是“基因组”部分的章节导引，先总览细菌基因组与真核基因组两大板块。细菌基因组通常指其核区的一条环状双链DNA，结构紧凑、基因密度高；真核基因组则包括核基因组与线粒体、叶绿体等细胞器基因组。学习时应抓住原核与真核在基因组大小、结构、重复序列、基因组织方式上的差异，为后续操纵子、质粒、转座等概念打基础。", "page": 45, "level": "了解", "img": "assets/img/ch02/p045.jpg", "anim": null, "fig": null, "points": ["细菌基因组通常指核区的一条环状双链DNA，结构紧凑、基因密度高", "真核基因组包括核基因组与线粒体、叶绿体等细胞器基因组", "学习重点是原核与真核在基因组大小、结构、重复序列、基因组织方式上的差异", "为后续操纵子、质粒、转座等概念打基础"], "check": {"q": "关于细菌基因组与真核基因组比较的叙述，正确的是：", "o": ["A. 细菌基因组通常指核区的一条环状双链DNA，结构紧凑、基因密度高", "B. 细菌基因组与真核基因组一样都含有大量内含子", "C. 真核基因组仅指细胞核内的DNA，不包括细胞器基因组", "D. 细菌基因组比真核基因组大且含有大量重复序列"], "a": "A", "e": "细菌基因组通常为核区一条环状双链DNA，结构紧凑、基因密度高；真核基因组还包括线粒体、叶绿体等细胞器基因组，且与原核在大小、重复序列等方面差异明显。"}, "cards": [{"front": "细菌基因组通常由什么构成？", "back": "通常是一条环状双链DNA，位于核区，结构紧凑、基因密度高。", "mnemonic": "一条环状双链DNA，紧凑高效", "useImg": false}]}, {"i": 1, "sec": "细菌核基因组", "title": "细菌核基因组的基本特征 (p46)", "notes": "细菌核基因组一般由一条双链环状DNA分子组成，只有一个复制起点，保证整个基因组从一个位点起始复制。DNA在细胞内高度折叠形成致密区域，称为类核（nucleoid），没有核膜与细胞质分隔。这种组织形式使细菌能快速复制、转录和分裂，也解释了细菌基因组小而高效的特点。", "page": 46, "level": "掌握", "img": "assets/img/ch02/p046.jpg", "anim": null, "fig": null, "points": ["细菌核基因组一般由一条双链环状DNA分子组成", "只有一个复制起点，整个基因组从单一原点起始复制", "DNA高度折叠形成致密区域，称为类核（nucleoid）", "无核膜与细胞质分隔，基因组小而高效，利于快速复制、转录和分裂"], "check": {"q": "细菌核基因组的基本特征是：", "o": ["A. 由多条线状DNA组成，有多个复制起点", "B. 由一条双链环状DNA组成，只有一个复制起点", "C. 由一条单链环状DNA组成，无复制起点", "D. 由多条环状DNA组成，被核膜包裹"], "a": "B", "e": "细菌核基因组一般由一条双链环状DNA分子组成，只有一个复制起点，DNA高度折叠形成类核，无核膜包裹。"}, "cards": [{"front": "细菌核基因组的基本特征是什么？", "back": "一条双链环状DNA，只有一个复制起点，高度折叠形成类核，无核膜分隔。", "mnemonic": "一环一起点，折叠成类核", "useImg": false}]}, {"i": 2, "sec": "操纵子模型", "title": "操纵子模型示意 (p47)", "notes": "本页为操纵子模型示意图。操纵子是原核生物基因表达调控的典型单位，通常由启动子、操纵基因和一组功能相关的结构基因组成，受同一调控序列控制，转录成多顺反子mRNA。这样细菌可以用一个开关同时控制多个相关蛋白的合成，例如代谢途径中的多个酶，从而提高基因表达效率并节约调控资源。", "page": 47, "level": "掌握", "img": "assets/img/ch02/p047.jpg", "anim": null, "fig": "该图为操纵子模型示意图，横向展示启动子、操纵基因与多个结构基因的排列顺序。看图时注意调控序列位于结构基因上游，转录产物为一条包含多个基因的多顺反子mRNA。", "points": ["操纵子是原核生物基因表达调控的典型单位", "通常由启动子、操纵基因和一组功能相关的结构基因组成", "受同一调控序列控制，转录成多顺反子mRNA", "一个开关同时控制多个相关蛋白合成，提高效率、节约调控资源"], "check": {"q": "关于操纵子的叙述，正确的是：", "o": ["A. 操纵子由启动子、操纵基因和一组功能相关的结构基因组成，转录出多顺反子mRNA", "B. 操纵子是真核生物基因表达调控的典型单位", "C. 操纵子中的每个结构基因都有独立的启动子，分别转录", "D. 操纵子转录产物是单顺反子mRNA，只能编码一种蛋白"], "a": "A", "e": "操纵子是原核生物基因表达调控的典型单位，通常由启动子、操纵基因和一组功能相关的结构基因组成，受同一调控序列控制，转录成多顺反子mRNA。"}, "cards": [{"front": "什么是操纵子？", "back": "原核基因表达调控单位，由启动子、操纵基因和一组功能相关结构基因组成，转录成多顺反子mRNA。", "mnemonic": "一开关控多基因", "useImg": false}]}, {"i": 3, "sec": "细菌基因组结构特点", "title": "结构基因连续、重复序列少、rRNA多拷贝 (p48)", "notes": "细菌结构基因序列通常是连续的，没有内含子，因此转录后一般不需要剪接。基因组中重复序列很少，编码蛋白质的结构基因多为单拷贝，但编码rRNA的基因往往是多拷贝的。这是因为细菌生长繁殖快，对核糖体需求量大，多拷贝rRNA基因可保证rRNA高效转录，满足蛋白质合成需要。", "page": 48, "level": "掌握", "img": "assets/img/ch02/p048.jpg", "anim": null, "fig": null, "points": ["细菌结构基因序列通常连续，没有内含子，转录后一般不需剪接", "基因组中重复序列很少", "编码蛋白质的结构基因多为单拷贝", "编码rRNA的基因往往是多拷贝，以满足快速生长时对核糖体的大量需求"], "check": {"q": "关于细菌基因组结构基因与rRNA基因的叙述，正确的是：", "o": ["A. 结构基因多含内含子，转录后需剪接", "B. 结构基因多为单拷贝，rRNA基因常为多拷贝", "C. 结构基因和rRNA基因均为多拷贝", "D. 基因组中重复序列很多，rRNA基因仅为单拷贝"], "a": "B", "e": "细菌结构基因序列通常连续、无内含子，多为单拷贝；重复序列很少，但编码rRNA的基因往往是多拷贝，以满足快速生长时对核糖体的需求。"}, "cards": [{"front": "细菌结构基因有什么特点？", "back": "序列连续、无内含子、一般不需剪接；重复序列少；结构基因多为单拷贝，但rRNA基因常为多拷贝。", "mnemonic": "无内含子、少重复、rRNA多拷贝", "useImg": false}]}, {"i": 4, "sec": "转座现象", "title": "转座因子与转座现象 (p49)", "notes": "细菌基因组具有转座现象。转座又称移位，指转座因子在基因组不同位置间移动的现象。转座元件是能够在基因组中改变位置的DNA序列，可在同一DNA分子内或不同DNA分子之间转移。转座可导致基因插入失活、基因重排或耐药基因传播，是细菌遗传变异和适应环境的重要机制之一。", "page": 49, "level": "掌握", "img": "assets/img/ch02/p049.jpg", "anim": null, "fig": null, "points": ["转座又称移位，指转座因子在基因组不同位置间移动的现象", "转座元件是能在基因组中改变位置的DNA序列", "可在同一DNA分子内或不同DNA分子之间转移", "转座可导致基因插入失活、基因重排或耐药基因传播", "是细菌遗传变异和适应环境的重要机制之一"], "check": {"q": "关于细菌转座因子与转座现象的叙述，正确的是：", "o": ["A. 转座因子不能在基因组中改变位置", "B. 转座是指转座因子在基因组不同位置间移动的现象，可导致基因插入失活或耐药基因传播", "C. 转座只能在同一DNA分子内发生，不能在不同DNA分子间转移", "D. 转座现象只存在于真核生物中，细菌基因组无转座"], "a": "B", "e": "转座又称移位，指转座因子在基因组不同位置间移动，可在同一DNA分子内或不同DNA分子间转移，可导致基因插入失活、基因重排或耐药基因传播。"}, "cards": [{"front": "什么是转座现象？", "back": "转座因子在基因组不同位置间移动的现象，可导致插入失活、基因重排或耐药基因传播。", "mnemonic": "会跳的DNA，变异传播", "useImg": false}]}, {"i": 5, "sec": "质粒定义", "title": "质粒的广义与狭义定义 (p50)", "notes": "质粒广义上是一类独立于染色体外、能自主复制的核酸分子，可为DNA或RNA，存在于细菌、放线菌、真菌及一些动植物细胞中，其中细菌中最常见。细菌质粒大多是环状双链DNA。狭义上，质粒指存在于细菌染色体外的小型环状双链DNA分子，是基因工程中最重要的载体来源之一。", "page": 50, "level": "掌握", "img": "assets/img/ch02/p050.jpg", "anim": null, "fig": null, "points": ["广义质粒：独立于染色体外、能自主复制的核酸分子，可为DNA或RNA", "存在于细菌、放线菌、真菌及一些动植物细胞中，细菌中最常见", "细菌质粒大多是环状双链DNA", "狭义质粒：细菌染色体外的小型环状双链DNA分子", "是基因工程中最重要的载体来源之一"], "check": {"q": "关于质粒定义的叙述，正确的是：", "o": ["A. 广义质粒是一类独立于染色体外、能自主复制的核酸分子，可为DNA或RNA", "B. 狭义质粒指存在于细菌染色体外的大型线状双链DNA分子", "C. 质粒只存在于细菌中，不存在于放线菌、真菌及动植物细胞中", "D. 细菌质粒大多是单链RNA分子"], "a": "A", "e": "广义质粒是独立于染色体外、能自主复制的核酸分子，可为DNA或RNA；狭义质粒指细菌染色体外的小型环状双链DNA分子，是基因工程重要载体来源。"}, "cards": [{"front": "质粒的广义与狭义定义分别是什么？", "back": "广义：独立于染色体外、能自主复制的核酸分子，可为DNA或RNA。狭义：细菌染色体外的小型环状双链DNA。", "mnemonic": "广义核酸，狭义细菌环状DNA", "useImg": false}]}, {"i": 6, "sec": "质粒特性", "title": "质粒的寄生性、依赖性与选择优势 (p51)", "notes": "质粒对宿主生存并非必需，它像“借居者”一样存在于宿主细胞中，通常不杀伤细胞，也不明显影响宿主代谢，宿主失去质粒仍可生存。但质粒离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录。质粒可赋予宿主有利表型，如抗生素抗性：Ampr可水解β-内酰胺环解除氨苄毒性，Tetr可阻止四环素进入细胞。", "page": 51, "level": "掌握", "img": "assets/img/ch02/p051.jpg", "anim": null, "fig": null, "points": ["质粒对宿主生存并非必需，宿主失去质粒仍可生存", "质粒通常不杀伤细胞，也不明显影响宿主代谢", "质粒离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录", "质粒可赋予宿主有利表型，如抗生素抗性", "Ampr可水解β-内酰胺环解除氨苄毒性，Tetr可阻止四环素进入细胞"], "check": {"q": "关于质粒与宿主关系的叙述，正确的是：", "o": ["A. 质粒是宿主生存所必需的，失去质粒宿主即死亡", "B. 质粒离开宿主可独立生存并完成复制转录", "C. 质粒对宿主生存并非必需，但离开宿主不能独立生存，必须依赖宿主的酶和蛋白质", "D. 质粒总是杀伤宿主细胞并明显影响宿主代谢"], "a": "C", "e": "质粒对宿主生存并非必需，通常不杀伤细胞，也不明显影响宿主代谢；但质粒离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录，并可赋予宿主有利表型如抗生素抗性。"}, "cards": [{"front": "质粒对宿主有什么特点？", "back": "非必需，不杀伤细胞，不明显影响代谢；离开宿主不能独立生存，依赖宿主酶和蛋白质；可赋予有利表型如抗生素抗性。", "mnemonic": "借居者，靠宿主，给好处", "useImg": false}]}, {"i": 7, "sec": "质粒结构状态", "title": "质粒的三种结构状态 (p52)", "notes": "细菌质粒在结构上主要有三种状态：超螺旋环状双链DNA、带缺口的环状DNA以及线性DNA。超螺旋状态使DNA更紧凑，有利于在细胞内包装和复制；带缺口环状DNA常见于复制或损伤修复过程中；线性DNA质粒则存在于部分细菌或特殊类型中。不同构象会影响质粒电泳迁移率和提取纯化结果。", "page": 52, "level": "理解", "img": "assets/img/ch02/p052.jpg", "anim": null, "fig": null, "points": ["细菌质粒结构上主要有三种状态：超螺旋环状双链DNA、带缺口的环状DNA、线性DNA", "超螺旋使DNA更紧凑，有利于细胞内包装和复制", "带缺口环状DNA常见于复制或损伤修复过程中", "线性DNA质粒存在于部分细菌或特殊类型中", "不同构象会影响质粒电泳迁移率和提取纯化结果"], "check": {"q": "关于细菌质粒的结构状态，下列哪项描述符合讲义内容？", "o": ["A. 质粒在结构上主要有超螺旋环状双链DNA、带缺口的环状DNA以及线性DNA三种状态", "B. 质粒只能以线性DNA形式存在", "C. 质粒只能以带缺口的环状DNA形式存在", "D. 质粒只能以超螺旋环状双链DNA形式存在"], "a": "A", "e": "讲义指出细菌质粒在结构上主要有三种状态：超螺旋环状双链DNA、带缺口的环状DNA以及线性DNA。"}, "cards": [{"front": "质粒的三种结构状态是什么？", "back": "超螺旋环状双链DNA、带缺口的环状DNA、线性DNA。", "mnemonic": "超螺旋、缺口环、线性", "useImg": false}]}, {"i": 8, "sec": "质粒应用", "title": "质粒作为基因工程载体 (p53)", "notes": "质粒是基因工程的重要载体，可把外源基因送入宿主细胞进行克隆扩增或表达。质粒可以改造，并具备作为载体的三个特点：能独立自主复制；便于检测，如抗生素抗性筛选；容易导入宿主细胞，也易从宿主细胞中分离纯化。基因工程中主要使用人工构建的质粒，如加入多克隆位点、筛选标记和调控元件。", "page": 53, "level": "掌握", "img": "assets/img/ch02/p053.jpg", "anim": null, "fig": null, "points": ["质粒是基因工程的重要载体，可把外源基因送入宿主细胞进行克隆扩增或表达", "质粒可以改造，具备作为载体的三个特点", "能独立自主复制", "便于检测，如抗生素抗性筛选", "容易导入宿主细胞，也易从宿主细胞中分离纯化", "基因工程中主要使用人工构建的质粒，如加入多克隆位点、筛选标记和调控元件"], "check": {"q": "根据讲义，质粒作为基因工程载体应具备的特点不包括下列哪项？", "o": ["A. 能独立自主复制", "B. 便于检测，如抗生素抗性筛选", "C. 容易导入宿主细胞，也易从宿主细胞中分离纯化", "D. 必须含有内含子以保证表达"], "a": "D", "e": "讲义列出的载体三特点是能独立自主复制、便于检测、容易导入和分离纯化，并未要求含有内含子。"}, "cards": [{"front": "质粒作为基因工程载体的三个特点是什么？", "back": "能独立自主复制；便于检测如抗生素抗性筛选；容易导入宿主细胞，也易分离纯化。", "mnemonic": "能复制、好检测、易进出", "useImg": false}]}, {"i": 9, "sec": "细菌基因组小结", "title": "细菌基因组特征总结 (p54)", "notes": "细菌基因组较小，通常由一条环状双链DNA组成，也可有质粒；只有一个复制起始点；重复序列少；结构基因一般单拷贝；大多数结构基因组成操纵子；结构基因无内含子；编码区占基因组比例远大于真核基因组而小于病毒基因组；存在可移动DNA序列即转座因子；还常有质粒DNA。这些特征共同体现细菌基因组经济、高效、可塑的特点。", "page": 54, "level": "掌握", "img": "assets/img/ch02/p054.jpg", "anim": null, "fig": null, "points": ["细菌基因组较小，通常由一条环状双链DNA组成，也可有质粒", "只有一个复制起始点，重复序列少", "结构基因一般单拷贝，大多数结构基因组成操纵子，无内含子", "编码区占基因组比例远大于真核基因组而小于病毒基因组", "存在可移动DNA序列即转座因子，还常有质粒DNA", "体现细菌基因组经济、高效、可塑的特点"], "check": {"q": "关于细菌基因组特征，下列哪项符合讲义描述？", "o": ["A. 细菌基因组通常由多条线状双链DNA组成，有多个复制起始点", "B. 细菌结构基因一般多拷贝且含有内含子", "C. 细菌基因组较小，通常由一条环状双链DNA组成，只有一个复制起始点，结构基因一般单拷贝且无内含子", "D. 细菌基因组中重复序列丰富，编码区比例小于真核基因组"], "a": "C", "e": "讲义总结细菌基因组较小、通常一条环状双链DNA、只有一个复制起始点、重复序列少、结构基因一般单拷贝且无内含子。"}, "cards": [{"front": "细菌基因组的主要特征有哪些？", "back": "较小，一条环状双链DNA，可有质粒；一个复制起点；重复序列少；结构基因单拷贝、组成操纵子、无内含子；编码区比例高；有转座因子和质粒DNA。", "mnemonic": "小、环、一、少、操、无、高、转、质", "useImg": false}]}, {"i": 10, "sec": "真核基因组定义", "title": "真核基因组：广义与狭义定义 (p55)", "notes": "真核基因组广义上指生物有机体单倍体细胞中的所有DNA，包括核内染色体DNA以及线粒体、叶绿体等亚细胞器中的DNA；狭义上主要指核基因组，细胞器基因组通常单独讨论。真核基因组一般远大于细菌基因组，含有大量重复序列、内含子和非编码区，基因表达调控也更复杂，与细菌基因组形成鲜明对比。", "page": 55, "level": "理解", "img": "assets/img/ch02/p055.jpg", "anim": null, "fig": null, "points": ["真核基因组广义上指单倍体细胞中的所有DNA，包括核内染色体DNA及线粒体、叶绿体等亚细胞器DNA", "狭义上主要指核基因组，细胞器基因组通常单独讨论", "真核基因组一般远大于细菌基因组", "含有大量重复序列、内含子和非编码区", "基因表达调控更复杂，与细菌基因组形成鲜明对比"], "check": {"q": "关于真核基因组的定义，下列哪项符合讲义内容？", "o": ["A. 广义上仅指核内染色体DNA，不包括线粒体和叶绿体DNA", "B. 广义上指单倍体细胞中的所有DNA，包括核DNA和线粒体、叶绿体等亚细胞器DNA；狭义上主要指核基因组", "C. 狭义上指细胞器基因组，核基因组通常单独讨论", "D. 真核基因组一般小于细菌基因组，且不含重复序列"], "a": "B", "e": "讲义指出真核基因组广义上包括单倍体细胞中所有DNA（核DNA及线粒体、叶绿体等DNA），狭义上主要指核基因组，细胞器基因组通常单独讨论。"}, "cards": [{"front": "真核基因组的广义与狭义定义是什么？", "back": "广义：单倍体细胞中所有DNA，包括核DNA和线粒体、叶绿体等细胞器DNA。狭义：主要指核基因组。", "mnemonic": "广义含细胞器，狭义指核", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_20", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "关于细菌核基因组的结构特点，下列哪项正确？", "o": ["A. 由多条线性染色体组成，有多个复制起点", "B. 由一条双链环状DNA组成，只有一个复制起点", "C. 由一条单链RNA组成，无复制起点", "D. 由质粒和组蛋白共同构成，有核膜包被"], "a": "B", "e": "细菌核基因组通常由一条双链环状DNA分子组成，只有一个复制起点，DNA在胞内形成类核，无核膜包被。", "kp": "ch02_s4_1"}, {"id": "ch02_mcq_21", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "细菌结构基因的典型特征是：", "o": ["A. 含有大量内含子，需要剪接", "B. 序列连续，无内含子", "C. 全部为多拷贝基因", "D. 不能组成操纵子"], "a": "B", "e": "细菌结构基因序列连续、无内含子；大多数结构基因组成操纵子，且编码蛋白质的基因多为单拷贝，但rRNA基因常为多拷贝。", "kp": "ch02_s4_3"}, {"id": "ch02_mcq_22", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "关于质粒的特性，下列描述错误的是：", "o": ["A. 质粒对宿主生存通常不是必需的", "B. 质粒可赋予宿主抗生素抗性等有利表型", "C. 质粒离开宿主后仍能独立完成复制和转录", "D. 质粒必须依赖宿主细胞的酶和蛋白质进行复制"], "a": "C", "e": "质粒离开宿主无法独立生存，必须依赖宿主细胞的酶和蛋白质才能完成自身复制和转录。", "kp": "ch02_s4_5"}, {"id": "ch02_mcq_23", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "质粒作为基因工程载体通常不需要具备下列哪一特点？", "o": ["A. 能独立自主复制", "B. 便于检测，如具有抗生素抗性", "C. 容易导入宿主细胞并易于分离纯化", "D. 必须含有完整的内含子剪接系统"], "a": "D", "e": "基因工程载体质粒通常要求能独立复制、便于检测、容易导入和分离纯化；内含子剪接系统不是细菌质粒载体的必备特点。", "kp": "ch02_s4_8"}, {"id": "ch02_mcq_24", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "细菌基因组中编码rRNA的基因常为多拷贝，其主要原因是：", "o": ["A. 细菌需要大量核糖体以满足快速蛋白质合成", "B. rRNA基因必须通过转座才能表达", "C. rRNA基因含有内含子，需要多拷贝补偿", "D. 细菌基因组重复序列极少，所以rRNA不能多拷贝"], "a": "A", "e": "细菌生长繁殖快，对核糖体需求量大，多拷贝rRNA基因可保证rRNA高效转录，从而满足蛋白质合成需要。", "kp": "ch02_s4_3"}], "judge": [{"id": "ch02_judge_9", "modI": 4, "q": "细菌核基因组一般由一条双链环状DNA分子组成，有多个复制起点。", "a": "错", "e": "细菌核基因组一般由一条双链环状DNA分子组成，只有一个复制起点，保证整个基因组从一个位点起始复制。", "kp": "ch02_s4_1"}, {"id": "ch02_judge_10", "modI": 4, "q": "质粒对宿主生存并非必需，但离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录。", "a": "对", "e": "质粒像“借居者”一样存在于宿主细胞中，通常不杀伤细胞，也不明显影响宿主代谢，宿主失去质粒仍可生存，但质粒离开宿主不能独立生存。", "kp": "ch02_s4_6"}], "fill": [{"id": "ch02_fill_9", "modI": 4, "q": "细菌核基因组一般由一条双链环状DNA分子组成，只有________个复制起点。", "a": "一", "kp": "ch02_s4_1"}, {"id": "ch02_fill_10", "modI": 4, "q": "质粒作为基因工程载体应具备三个特点：能独立自主复制、便于________（如抗生素抗性）、容易________并分离纯化。", "a": "检测,导入宿主细胞", "kp": "ch02_s4_8"}], "short": [{"id": "ch02_short_5", "modI": 4, "q": "简述质粒的定义、特点及其作为基因工程载体的条件。", "a": "定义：质粒是独立于染色体外、能自主复制的核酸分子，细菌质粒大多是环状双链DNA。特点：①对宿主生存并非必需；②离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录；③可赋予宿主有利表型，如抗生素抗性；④在结构上主要有超螺旋环状双链DNA、带缺口的环状DNA以及线性DNA三种状态。作为基因工程载体的条件：①能独立自主复制；②便于导入宿主细胞；③具有选择标记。", "kp": "ch02_s4_8"}], "calc": [], "term": [{"id": "ch02_term_11", "modI": 4, "term": "Plasmid", "def": "质粒：独立于染色体外、能自主复制的核酸分子。要点：①广义上可为DNA或RNA，存在于细菌、放线菌、真菌及一些动植物细胞中；②细菌中最常见，大多是环状双链DNA；③狭义上指细菌染色体外的小型环状双链DNA分子；④对宿主生存并非必需，但可赋予有利表型；⑤是基因工程中最重要的载体来源之一。", "kp": "ch02_s4_1"}, {"id": "ch02_term_12", "modI": 4, "term": "Nucleoid", "def": "类核：细菌细胞内DNA高度折叠形成的致密区域。要点：①没有核膜与细胞质分隔；②细菌核基因组一般由一条双链环状DNA分子组成；③只有一个复制起点；④保证整个基因组从一个位点起始复制；⑤使细菌能快速复制、转录和分裂。", "kp": "ch02_s4_1"}]}, {"i": 5, "name": "模块六：真核生物基因组", "slides": [{"i": 0, "sec": "模块六：真核生物基因组", "title": "真核基因组大小与物种复杂性相关 (p56)", "notes": "真核生物基因组十分庞大，且其大小总体上与生物体的复杂程度呈正相关。例如，低等真核生物如酵母基因组约12 Mb，而哺乳动物可达3 Gb量级。不过这种相关性并非绝对，存在“C值悖论”：某些两栖类或植物的基因组甚至比人类还大，说明基因组大小并不完全等同于基因数目或生物学复杂性。真核基因组庞大也为基因调控、发育复杂性提供了更多序列基础。", "page": 56, "level": "掌握", "img": "assets/img/ch02/p056.jpg", "anim": null, "fig": null, "points": ["真核生物基因组十分庞大，大小总体上与生物体复杂程度呈正相关。", "低等真核生物如酵母基因组约12 Mb，哺乳动物可达3 Gb量级。", "存在“C值悖论”：某些两栖类或植物的基因组甚至比人类还大。", "基因组大小并不完全等同于基因数目或生物学复杂性。", "真核基因组庞大为基因调控、发育复杂性提供了更多序列基础。"], "check": {"q": "关于真核生物基因组大小与物种复杂性的关系，下列叙述正确的是？", "o": ["A. 真核基因组大小与生物复杂程度完全无关", "B. 真核基因组大小总体上与生物复杂程度呈正相关，但存在C值悖论", "C. 所有哺乳动物基因组均小于酵母基因组", "D. C值悖论说明基因组越大基因数目一定越多"], "a": "B", "e": "真核基因组大小总体与复杂性正相关，但并非绝对，存在C值悖论，即某些两栖类或植物基因组比人类还大，说明基因组大小不完全等同于基因数目或复杂性。"}, "cards": [{"front": "真核基因组大小与物种复杂性之间是什么关系？", "back": "总体上呈正相关，但并非绝对，存在C值悖论：某些两栖类或植物的基因组甚至比人类还大。", "mnemonic": "大而复杂，但C值悖论是例外", "useImg": false}]}, {"i": 1, "sec": "模块六：真核生物基因组", "title": "真核基因组非编码区多、基因密度低 (p57)", "notes": "真核基因组中编码蛋白质的区域（coding region）所占比例很低，通常不足10%，90%以上为非编码序列。因此真核基因密度远低于原核生物：原核基因组中基因排列紧凑，甚至存在重叠基因；而真核基因之间往往间隔大量非编码DNA。这些非编码区并非“垃圾”，其中包含调控元件、重复序列、内含子等，参与基因表达调控、染色体结构维持和进化。", "page": 57, "level": "掌握", "img": "assets/img/ch02/p057.jpg", "anim": null, "fig": null, "points": ["真核基因组中编码蛋白质的区域所占比例很低，通常不足10%。", "90%以上为非编码序列，真核基因密度远低于原核生物。", "原核基因组中基因排列紧凑，甚至存在重叠基因。", "真核基因之间往往间隔大量非编码DNA。", "非编码区包含调控元件、重复序列、内含子等，参与基因表达调控、染色体结构维持和进化。"], "check": {"q": "关于真核基因组非编码区与基因密度的叙述，正确的是？", "o": ["A. 真核基因组编码区通常占90%以上", "B. 真核基因排列比原核生物更紧凑，且普遍存在重叠基因", "C. 真核基因组非编码序列常超过90%，基因密度远低于原核生物", "D. 非编码区都是无功能的“垃圾DNA”"], "a": "C", "e": "真核基因组中编码蛋白质区域通常不足10%，90%以上为非编码序列，基因密度远低于原核生物；非编码区包含调控元件、重复序列、内含子等，并非全是垃圾DNA。"}, "cards": [{"front": "什么是C值悖论？", "back": "基因组大小并不完全等同于基因数目或生物学复杂性，某些低等生物的基因组反而比高等生物更大。", "mnemonic": "C值大≠更高级", "useImg": false}]}, {"i": 2, "sec": "模块六：真核生物基因组", "title": "真核基因组含有大量重复序列 (p58)", "notes": "重复序列是真核细胞基因组的重要特点之一，指基因组中存在一个以上相同或相似顺序拷贝的DNA序列。它们大多不直接编码蛋白质，但会影响基因组大小、结构稳定性以及基因表达调控。重复序列的拷贝数可从几个到数百万个不等，是造成真核基因组庞大的重要原因，也是真核生物基因组进化与调控复杂性的重要来源。", "page": 58, "level": "掌握", "img": "assets/img/ch02/p058.jpg", "anim": null, "fig": null, "points": ["重复序列是真核细胞基因组的重要特点之一。", "重复序列指基因组中存在一个以上相同或相似顺序拷贝的DNA序列。", "重复序列大多不直接编码蛋白质，但影响基因组大小、结构稳定性及基因表达调控。", "重复序列拷贝数可从几个到数百万个不等。", "重复序列是造成真核基因组庞大的重要原因，也是真核生物基因组进化与调控复杂性的重要来源。"], "check": {"q": "关于真核基因组重复序列的叙述，错误的是？", "o": ["A. 重复序列指基因组中存在一个以上相同或相似顺序拷贝的DNA序列", "B. 重复序列大多不直接编码蛋白质", "C. 重复序列拷贝数可从几个到数百万个不等", "D. 重复序列只增加基因组大小，对结构和表达调控没有影响"], "a": "D", "e": "重复序列是真核基因组重要特点，大多不直接编码蛋白质，但会影响基因组大小、结构稳定性以及基因表达调控，也是基因组进化与调控复杂性的重要来源。"}, "cards": [{"front": "真核基因组中编码蛋白质的区域占比大约是多少？", "back": "通常不足10%，90%以上为非编码序列，因此真核基因密度远低于原核生物。", "mnemonic": "编码不到一成，非编码九成以上", "useImg": false}]}, {"i": 3, "sec": "模块六：真核生物基因组", "title": "重复序列的主要类型：串联重复与散在重复 (p59)", "notes": "真核重复序列按排列方式主要分为两类：串联重复序列，如卫星DNA、小卫星DNA和微卫星DNA，它们首尾相连成簇分布，常位于着丝粒、端粒等异染色质区，与染色体结构和稳定性有关；散在重复序列，如转座元件，分散分布于基因组中，可移动或曾具有移动能力。两类重复序列在基因组中的分布、拷贝数和功能各不相同，共同塑造真核基因组的复杂结构。", "page": 59, "level": "掌握", "img": "assets/img/ch02/p059.jpg", "anim": null, "fig": null, "points": ["真核重复序列按排列方式主要分为串联重复序列和散在重复序列两类。", "串联重复序列包括卫星DNA、小卫星DNA和微卫星DNA，首尾相连成簇分布。", "串联重复序列常位于着丝粒、端粒等异染色质区，与染色体结构和稳定性有关。", "散在重复序列如转座元件，分散分布于基因组中，可移动或曾具有移动能力。", "两类重复序列在基因组中的分布、拷贝数和功能各不相同，共同塑造真核基因组的复杂结构。"], "check": {"q": "按排列方式划分，真核重复序列主要包括哪两类？", "o": ["A. 编码序列与非编码序列", "B. 串联重复序列与散在重复序列", "C. 外显子与内含子", "D. 单一序列与多拷贝序列"], "a": "B", "e": "真核重复序列按排列方式主要分为串联重复序列（如卫星DNA、小卫星DNA、微卫星DNA）和散在重复序列（如转座元件）。"}, "cards": [{"front": "真核基因组的非编码区是否都是垃圾DNA？", "back": "不是。非编码区包含调控元件、重复序列、内含子等，参与基因表达调控、染色体结构维持和进化。", "mnemonic": "非编码≠无功能", "useImg": false}]}, {"i": 4, "sec": "模块六：真核生物基因组", "title": "转座元件：真核重复序列的重要组成 (p60)", "notes": "转座元件是真核生物重复序列的重要组成部分，能在基因组中移动或扩增，从而影响基因组大小、结构和进化。不同物种中转座元件所占比例差异很大，例如人类基因组中约45%为转座元件。但比例高并不意味着它们都在活跃“跳跃”：大多数转座子因突变积累或表观遗传机制（如DNA甲基化、组蛋白修饰）而被沉默，只有少数仍具转座活性。", "page": 60, "level": "理解", "img": "assets/img/ch02/p060.jpg", "anim": null, "fig": null, "points": ["转座元件是真核生物重复序列的重要组成部分。", "转座元件能在基因组中移动或扩增，从而影响基因组大小、结构和进化。", "不同物种中转座元件所占比例差异很大，例如人类基因组中约45%为转座元件。", "大多数转座子因突变积累或表观遗传机制（如DNA甲基化、组蛋白修饰）而被沉默。", "只有少数转座子仍具转座活性。"], "check": {"q": "关于转座元件的叙述，正确的是？", "o": ["A. 人类基因组中约45%为转座元件，且大多数仍活跃跳跃", "B. 转座元件不能影响基因组大小、结构和进化", "C. 人类基因组中约45%为转座元件，但大多数因突变或表观遗传机制被沉默", "D. 转座元件只存在于原核生物中"], "a": "C", "e": "转座元件是真核重复序列的重要组成部分，人类基因组中约45%为转座元件，但大多数因突变积累或DNA甲基化、组蛋白修饰等表观遗传机制被沉默，只有少数仍具转座活性。"}, "cards": [{"front": "真核基因组重复序列按排列方式主要分为哪两类？", "back": "串联重复序列（卫星DNA、小卫星DNA、微卫星DNA）和散在重复序列（如转座元件）。", "mnemonic": "串联成簇，散在分布", "useImg": false}]}, {"i": 5, "sec": "模块六：真核生物基因组", "title": "转座元件的两种转座机制：复制型与剪切型 (p61)", "notes": "该图展示转座元件的两种主要转座方式。“复制-粘贴”（copy and paste）即复制型转座：转座子先转录为RNA，再逆转录为DNA，插入新位点，原拷贝保留，因此拷贝数增加，常见于逆转录转座子。“剪切-粘贴”（cut and paste）即DNA型转座：转座酶将转座子从原位置切下并插入新位点，原位置丢失，拷贝数通常不增加。两种机制均能引起基因组结构变异和进化。", "page": 61, "level": "理解", "img": "assets/img/ch02/p061.jpg", "anim": null, "fig": "该图展示转座元件的两种主要转座方式。左侧或上方通常为复制型转座：转座子转录为RNA，逆转录为DNA后插入新位点，原拷贝保留；右侧或下方为剪切型转座：转座酶将转座子从原位置切下并插入新位点，原位置丢失。通过对比箭头和拷贝数变化，可直观理解两种机制对基因组结构的影响。", "points": ["转座元件有两种主要转座机制：复制型转座和剪切型转座。", "复制型转座即“复制-粘贴”：转座子先转录为RNA，再逆转录为DNA，插入新位点，原拷贝保留，拷贝数增加。", "复制型转座常见于逆转录转座子。", "剪切型转座即“剪切-粘贴”：转座酶将转座子从原位置切下并插入新位点，原位置丢失，拷贝数通常不增加。", "两种机制均能引起基因组结构变异和进化。"], "check": {"q": "关于复制型转座与剪切型转座的比较，正确的是？", "o": ["A. 复制型转座通常使拷贝数增加，剪切型转座通常不增加拷贝数", "B. 复制型转座会切下原拷贝，原位置丢失", "C. 剪切型转座通过RNA逆转录为DNA后插入新位点", "D. 两种转座方式都不会引起基因组结构变异"], "a": "A", "e": "复制型转座即“复制-粘贴”，原拷贝保留，拷贝数增加，常见于逆转录转座子；剪切型转座即“剪切-粘贴”，转座子从原位置切下并插入新位点，原位置丢失，拷贝数通常不增加。"}, "cards": [{"front": "串联重复序列常位于染色体的哪些区域？有什么功能？", "back": "常位于着丝粒、端粒等异染色质区，与染色体结构和稳定性有关。", "mnemonic": "着丝粒端粒，结构稳定", "useImg": false}]}, {"i": 6, "sec": "模块六：真核生物基因组", "title": "断裂基因：外显子与内含子 (p62)", "notes": "断裂基因（split gene）是真核生物基因组结构的重要特征，指编码蛋白质的基因序列被非编码的插入序列隔开。其中外显子（exon）是最终保留在成熟mRNA中的编码或非编码区段，内含子（intron）则在转录后剪接过程中被切除。断裂基因是真核生物与原核生物基因组的主要区别之一，它使同一前体mRNA可通过可变剪接产生多种mRNA和蛋白质，极大扩展了遗传信息容量。", "page": 62, "level": "掌握", "img": "assets/img/ch02/p062.jpg", "anim": null, "fig": null, "points": ["断裂基因是真核生物基因组结构的重要特征，指编码蛋白质的基因序列被非编码的插入序列隔开。", "外显子是最终保留在成熟mRNA中的编码或非编码区段。", "内含子在转录后剪接过程中被切除。", "断裂基因是真核生物与原核生物基因组的主要区别之一。", "断裂基因使同一前体mRNA可通过可变剪接产生多种mRNA和蛋白质，极大扩展了遗传信息容量。"], "check": {"q": "关于断裂基因中外显子与内含子的叙述，正确的是？", "o": ["A. 内含子是最终保留在成熟mRNA中的编码区段", "B. 外显子一定编码蛋白质，内含子一定不参与剪接", "C. 断裂基因指编码蛋白质的基因序列被非编码插入序列隔开，内含子在剪接中被切除", "D. 断裂基因只存在于原核生物中，且不能发生可变剪接"], "a": "C", "e": "断裂基因是真核生物基因组的重要特征，指编码蛋白质的基因序列被非编码插入序列隔开；外显子最终保留在成熟mRNA中，内含子在转录后剪接中被切除，并可通过可变剪接产生多种mRNA和蛋白质。"}, "cards": [{"front": "转座元件的两种转座机制是什么？", "back": "复制型转座（复制-粘贴，拷贝数增加，常见于逆转录转座子）和剪切型转座（剪切-粘贴，原位置丢失，拷贝数通常不增加）。", "mnemonic": "复制粘贴增拷贝，剪切粘贴挪位置", "useImg": false}]}, {"i": 7, "sec": "模块六：真核生物基因组", "title": "真核生物基因组特点小结 (p63)", "notes": "本页总结真核生物基因组的主要特征：基因组庞大，与物种复杂性总体相关；mRNA为单顺反子，即一条mRNA通常只编码一种蛋白质；非编码区占90%以上，基因密度低；基因常为断裂基因，含内含子和外显子；含有大量重复序列和转座元件。这些特征共同决定了真核基因表达调控的复杂性和多样性，也是真核生物进化与发育复杂性的重要基础。", "page": 63, "level": "掌握", "img": "assets/img/ch02/p063.jpg", "anim": null, "fig": null, "points": ["真核生物基因组庞大，与物种复杂性总体相关。", "mRNA为单顺反子，即一条mRNA通常只编码一种蛋白质。", "非编码区占90%以上，基因密度低。", "基因常为断裂基因，含内含子和外显子。", "含有大量重复序列和转座元件，这些特征共同决定了真核基因表达调控的复杂性和多样性。"], "check": {"q": "根据真核生物基因组特点，下列关于其mRNA的描述正确的是？", "o": ["A. 一条mRNA通常编码多种蛋白质", "B. mRNA为单顺反子，通常只编码一种蛋白质", "C. 真核生物mRNA不含非编码区", "D. 真核生物基因不含内含子"], "a": "B", "e": "真核生物mRNA为单顺反子，即一条mRNA通常只编码一种蛋白质；其基因常为断裂基因，含内含子和外显子，非编码区占90%以上。"}, "cards": [{"front": "什么是断裂基因？外显子和内含子有何区别？", "back": "断裂基因指编码蛋白质的基因序列被非编码插入序列隔开。外显子最终保留在成熟mRNA中，内含子在转录后剪接中被切除。", "mnemonic": "外显保留，内含被切", "useImg": false}]}, {"i": 8, "sec": "模块六：真核生物基因组", "title": "染色体：真核基因组的包装形式 (p64)", "notes": "本页标题为“Chromosome”，引出真核基因组以染色体形式存在。真核生物基因组DNA与组蛋白结合形成核小体，进一步折叠压缩为染色质，在细胞分裂期高度凝缩成染色体。这种包装不仅将长达数米的DNA装入微米级细胞核，还通过染色质结构变化参与基因表达调控。染色体结构、端粒和着丝粒等对基因组稳定性、复制和分离至关重要。", "page": 64, "level": "掌握", "img": "assets/img/ch02/p064.jpg", "anim": null, "fig": null, "points": ["真核基因组以染色体形式存在。", "真核生物基因组DNA与组蛋白结合形成核小体，进一步折叠压缩为染色质。", "在细胞分裂期染色质高度凝缩成染色体。", "这种包装将长达数米的DNA装入微米级细胞核，并通过染色质结构变化参与基因表达调控。", "染色体结构、端粒和着丝粒等对基因组稳定性、复制和分离至关重要。"], "check": {"q": "关于真核基因组以染色体形式包装的描述，下列哪项正确？", "o": ["A. 真核DNA不与蛋白质结合，直接以裸露DNA形式存在", "B. DNA与组蛋白结合形成核小体，进一步折叠压缩为染色质，分裂期高度凝缩成染色体", "C. 染色体包装仅用于储存DNA，不参与基因表达调控", "D. 端粒和着丝粒与基因组稳定性、复制和分离无关"], "a": "B", "e": "真核基因组DNA与组蛋白结合形成核小体，进一步折叠压缩为染色质，在细胞分裂期高度凝缩成染色体；这种包装还通过染色质结构变化参与基因表达调控，端粒和着丝粒对基因组稳定性、复制和分离至关重要。"}, "cards": [{"front": "真核生物基因组的主要特点有哪些？", "back": "基因组庞大；mRNA为单顺反子；非编码区占90%以上，基因密度低；基因为断裂基因，含内含子和外显子；含大量重复序列和转座元件。", "mnemonic": "大、单、低、断、重", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_25", "mod": "模块六：真核生物基因组", "modI": 5, "q": "下列关于真核生物基因组特点的叙述，错误的是：", "o": ["A. 基因组庞大，与物种复杂性总体呈正相关", "B. 非编码区占90%以上，基因密度低", "C. 基因多为断裂基因，含有内含子和外显子", "D. 基因组中重复序列很少，且不编码蛋白质"], "a": "D", "e": "真核基因组含有大量重复序列，如卫星DNA和转座元件，它们大多不编码蛋白质，但会影响基因组大小、结构和表达调控，因此D错误。", "kp": "ch02_s5_7"}, {"id": "ch02_mcq_26", "mod": "模块六：真核生物基因组", "modI": 5, "q": "真核生物断裂基因中，在mRNA剪接过程中被切除的序列是：", "o": ["A. 外显子", "B. 内含子", "C. 启动子", "D. 增强子"], "a": "B", "e": "断裂基因由外显子和内含子组成，内含子在转录后剪接过程中被切除，外显子则连接形成成熟mRNA。", "kp": "ch02_s5_6"}, {"id": "ch02_mcq_27", "mod": "模块六：真核生物基因组", "modI": 5, "q": "关于转座元件的转座机制，下列叙述正确的是：", "o": ["A. “复制-粘贴”转座后原拷贝丢失，拷贝数不变", "B. “剪切-粘贴”转座后原拷贝保留，拷贝数增加", "C. “复制-粘贴”转座后原拷贝保留，拷贝数增加", "D. 两种机制均不改变基因组大小"], "a": "C", "e": "复制型转座即“复制-粘贴”，原拷贝保留并在新位点插入新拷贝，拷贝数增加；剪切型转座即“剪切-粘贴”，原位置丢失，拷贝数通常不增加。", "kp": "ch02_s5_5"}, {"id": "ch02_mcq_28", "mod": "模块六：真核生物基因组", "modI": 5, "q": "下列哪项不是真核生物基因组的主要特征？", "o": ["A. 含有大量重复序列", "B. 基因密度高，编码区占90%以上", "C. 存在断裂基因", "D. mRNA通常为单顺反子"], "a": "B", "e": "真核基因组非编码区占90%以上，基因密度低，编码区比例小，因此B不是真核基因组特征。", "kp": "ch02_s5_7"}, {"id": "ch02_mcq_29", "mod": "模块六：真核生物基因组", "modI": 5, "q": "大多数转座元件在真核基因组中不活跃“跳跃”的主要原因是：", "o": ["A. 它们全部被完全切除", "B. 突变积累或表观遗传机制使其沉默", "C. 它们只能存在于原核生物中", "D. 它们不参与基因组进化"], "a": "B", "e": "大多数转座子因突变积累或表观遗传机制（如DNA甲基化、组蛋白修饰）被沉默，只有少数仍具转座活性。", "kp": "ch02_s5_4"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}, {"i": 6, "name": "模块七：染色体与DNA包装（核小体）", "slides": [{"i": 0, "sec": "染色体与DNA包装（核小体）", "title": "人体DNA的总长度 (p65)", "notes": "本页通过计算展示人体DNA的惊人长度：每个碱基对长度约0.332 nm，人类基因组约3.4×10⁹ bp，二倍体细胞含2套基因组，人体约1×10¹⁴个细胞，总DNA长度约2.26×10¹¹ km，相当于地球到太阳距离（1.50×10⁸ km）的约1500个来回。这一计算直观说明DNA必须被高度压缩才能容纳于细胞核内，引出染色体包装问题。", "page": 65, "level": "了解", "img": "assets/img/ch02/p065.jpg", "anim": null, "fig": null, "points": ["每个碱基对长度约0.332 nm，人类基因组约3.4×10⁹ bp", "二倍体细胞含2套基因组，人体约1×10¹⁴个细胞", "总DNA长度约2.26×10¹¹ km，约为地球到太阳距离的1500个来回", "说明DNA必须高度压缩才能容纳于细胞核内，引出染色体包装问题"], "check": {"q": "根据本页计算，人体DNA总长度约为多少，并与地球到太阳距离相比如何？", "o": ["A. 约2.26×10¹¹ km，约为地球到太阳距离的1500个来回", "B. 约2.26×10⁸ km，约为地球到太阳距离的1.5倍", "C. 约3.4×10⁹ km，约为地球到太阳距离的20个来回", "D. 约1×10¹⁴ km，约为地球到太阳距离的1000倍"], "a": "A", "e": "本页计算得出人体DNA总长度约2.26×10¹¹ km，相当于地球到太阳距离（1.50×10⁸ km）的约1500个来回。"}, "cards": [{"front": "人体DNA总长度约为多少？相当于什么？", "back": "约2.26×10¹¹ km，相当于地球到太阳距离的约1500个来回。", "mnemonic": "人体DNA可绕地球到太阳1500趟", "useImg": false}, {"front": "谁于1997年发表了核小体核心颗粒的晶体结构？分辨率多少？", "back": "Luger和Richmond于1997年在Nature发表，分辨率2.8 Å。", "mnemonic": "", "useImg": false}]}, {"i": 1, "sec": "染色体与DNA包装（核小体）", "title": "染色质与染色体的基本概念 (p66)", "notes": "DNA在细胞中并非裸露存在，而是与蛋白质结合，原核生物、真核生物甚至病毒均如此。DNA与其结合蛋白的复合物称为染色质（chromatin），在细胞分裂期高度压缩形成染色体（chromosome）。染色质/染色体的首要功能是压缩DNA，使其适应细胞空间，同时参与基因表达调控、DNA复制、修复和重组等过程。", "page": 66, "level": "掌握", "img": "assets/img/ch02/p066.jpg", "anim": null, "fig": null, "points": ["DNA在细胞中并非裸露存在，而是与蛋白质结合", "DNA与结合蛋白的复合物称为染色质（chromatin）", "细胞分裂期高度压缩形成染色体（chromosome）", "染色质/染色体的首要功能是压缩DNA，使其适应细胞空间", "同时参与基因表达调控、DNA复制、修复和重组等过程"], "check": {"q": "关于染色质与染色体的基本概念，下列哪项正确？", "o": ["A. DNA在细胞中均以裸露形式存在，只有真核生物例外", "B. 染色质是DNA与结合蛋白的复合物，细胞分裂期高度压缩形成染色体", "C. 染色体仅存在于原核生物中，真核生物只有染色质", "D. 染色质/染色体的功能仅限于压缩DNA，不参与基因表达调控"], "a": "B", "e": "DNA与结合蛋白形成染色质，细胞分裂期高度压缩为染色体；其功能包括压缩DNA、基因表达调控、复制、修复和重组等。"}, "cards": [{"front": "为什么DNA必须被高度压缩？", "back": "因为人体DNA总长度远超细胞尺度，必须高度压缩才能容纳于细胞核内。", "mnemonic": "", "useImg": false}, {"front": "核小体的形状是什么？DNA缠绕导致压缩约多少倍？", "back": "呈圆柱形，DNA缠绕导致长度压缩约6倍。", "mnemonic": "", "useImg": false}]}, {"i": 2, "sec": "染色体与DNA包装（核小体）", "title": "DNA包装成染色体的重要性 (p67)", "notes": "染色体是DNA的压缩形式，便于装入细胞；可保护DNA免受损伤；在细胞分裂时能高效传递给两个子细胞；染色体赋予每个DNA分子整体组织形式，有利于基因表达、DNA复制、修复及重组。因此，DNA包装不仅是空间问题，更与遗传信息稳定传递和功能调控密切相关。", "page": 67, "level": "掌握", "img": "assets/img/ch02/p067.jpg", "anim": null, "fig": null, "points": ["染色体是DNA的压缩形式，便于装入细胞", "可保护DNA免受损伤", "细胞分裂时能高效传递给两个子细胞", "染色体赋予每个DNA分子整体组织形式，有利于基因表达、DNA复制、修复及重组", "DNA包装不仅是空间问题，更与遗传信息稳定传递和功能调控密切相关"], "check": {"q": "DNA包装成染色体的重要性不包括下列哪一项？", "o": ["A. 便于将DNA装入细胞空间", "B. 保护DNA免受损伤", "C. 使细胞分裂时DNA能高效传递给子细胞", "D. 改变DNA的碱基序列以产生遗传变异"], "a": "D", "e": "DNA包装不改变碱基序列；其重要性包括压缩空间、保护DNA、高效传递及有利于基因表达、复制、修复和重组。"}, "cards": [{"front": "什么是染色质？", "back": "DNA与其结合蛋白形成的复合物。", "mnemonic": "DNA+蛋白=染色质", "useImg": false}, {"front": "组蛋白H1的功能是什么？", "back": "结合在核小体之间的连接DNA上，锁住核小体DNA的进出端，稳定核小体结构，促进30 nm纤维形成。", "mnemonic": "H1锁门促纤维", "useImg": false}]}, {"i": 3, "sec": "染色体与DNA包装（核小体）", "title": "染色体多样性 (p68)", "notes": "染色体具有多样性：形状上可为环状或线状；每种生物染色体数目恒定；拷贝数可为单倍体、二倍体或多倍体。这些特征反映了不同生物在基因组组织和遗传方式上的差异，是理解染色体结构与功能的基础。", "page": 68, "level": "理解", "img": "assets/img/ch02/p068.jpg", "anim": null, "fig": null, "points": ["染色体形状可为环状或线状", "每种生物染色体数目恒定", "拷贝数可为单倍体、二倍体或多倍体", "这些特征反映了不同生物在基因组组织和遗传方式上的差异"], "check": {"q": "关于染色体多样性，下列描述正确的是？", "o": ["A. 染色体形状只有线状一种", "B. 每种生物染色体数目可变，不恒定", "C. 染色体拷贝数可为单倍体、二倍体或多倍体", "D. 原核生物染色体均为线状"], "a": "C", "e": "染色体形状可为环状或线状；每种生物染色体数目恒定；拷贝数可为单倍体、二倍体或多倍体。"}, "cards": [{"front": "什么是染色体？", "back": "染色质在细胞分裂期高度压缩形成的结构。", "mnemonic": "染色质压缩成染色体", "useImg": false}, {"front": "每个核小体单位包括哪些成分？", "back": "约200 bp DNA、一个组蛋白八聚体和一个H1分子。", "mnemonic": "", "useImg": false}]}, {"i": 4, "sec": "染色体与DNA包装（核小体）", "title": "不同生物染色体组成的变异 (p69)", "notes": "本页展示不同生物染色体组成的变化，包括染色体数目、形状、大小和拷贝数的差异。例如，原核生物通常为环状染色体，真核生物为线状染色体；不同物种染色体数目从几条到数百条不等。这些变异与生物进化、基因组复杂性和生活方式相关。", "page": 69, "level": "了解", "img": "assets/img/ch02/p069.jpg", "anim": null, "fig": null, "points": ["不同生物染色体数目、形状、大小和拷贝数存在差异", "原核生物通常为环状染色体，真核生物为线状染色体", "不同物种染色体数目从几条到数百条不等", "这些变异与生物进化、基因组复杂性和生活方式相关"], "check": {"q": "不同生物染色体组成的变异主要体现在哪些方面？", "o": ["A. 仅染色体数目不同", "B. 仅染色体形状不同", "C. 染色体数目、形状、大小和拷贝数均可不同", "D. 所有生物染色体组成完全相同"], "a": "C", "e": "不同生物染色体组成在数目、形状、大小和拷贝数上均有差异，如原核生物常为环状，真核生物为线状。"}, "cards": [{"front": "染色质/染色质的首要功能是什么？", "back": "压缩DNA，使其适应细胞空间。", "mnemonic": "", "useImg": false}, {"front": "什么是染色质小体？", "back": "包括H1和166 bp DNA的结构。", "mnemonic": "", "useImg": false}]}, {"i": 5, "sec": "染色体与DNA包装（核小体）", "title": "基因组大小与生物复杂性的关系 (p70)", "notes": "基因组大小与生物复杂性大致相关，但并非严格线性。复杂生物通常具有更大的基因组，但存在C值悖论：某些简单生物基因组反而更大。这说明基因组大小不能完全决定复杂性，基因调控和非编码序列等因素同样重要。", "page": 70, "level": "理解", "img": "assets/img/ch02/p070.jpg", "anim": null, "fig": null, "points": ["基因组大小与生物复杂性大致相关，但并非严格线性", "复杂生物通常具有更大的基因组", "存在C值悖论：某些简单生物基因组反而更大", "基因组大小不能完全决定复杂性，基因调控和非编码序列等因素同样重要"], "check": {"q": "关于基因组大小与生物复杂性的关系，下列哪项正确？", "o": ["A. 基因组越大，生物一定越复杂", "B. 基因组大小与生物复杂性完全无关", "C. 基因组大小与复杂性大致相关，但存在C值悖论", "D. 简单生物基因组一定比复杂生物小"], "a": "C", "e": "基因组大小与复杂性大致相关但非严格线性，存在C值悖论，即某些简单生物基因组反而更大。"}, "cards": [{"front": "染色质/染色体还参与哪些过程？", "back": "基因表达调控、DNA复制、修复和重组。", "mnemonic": "", "useImg": false}, {"front": "组蛋白变体有哪些例子？其功能是什么？", "back": "如H2A.Z、H3.3、CENP-A等，参与基因表达调控、染色质重塑、着丝粒功能等。", "mnemonic": "", "useImg": false}]}, {"i": 6, "sec": "染色体与DNA包装（核小体）", "title": "不同生物染色体基因密度比较 (p71)", "notes": "大肠杆菌基因组几乎全部由基因组成，基因密度极高；而复杂生物基因密度降低，存在大量非编码序列。这反映了真核生物基因组中调控序列、重复序列和内含子等非编码成分增加，基因表达调控更复杂。", "page": 71, "level": "理解", "img": "assets/img/ch02/p071.jpg", "anim": null, "fig": null, "points": ["大肠杆菌基因组几乎全部由基因组成，基因密度极高", "复杂生物基因密度降低，存在大量非编码序列", "真核生物基因组中调控序列、重复序列和内含子等非编码成分增加", "基因表达调控更复杂"], "check": {"q": "比较不同生物染色体基因密度，下列哪项正确？", "o": ["A. 大肠杆菌基因组几乎全部由基因组成，基因密度极高", "B. 复杂生物基因密度高于大肠杆菌", "C. 真核生物基因组中非编码序列很少", "D. 基因密度与生物复杂性成正比"], "a": "A", "e": "大肠杆菌基因组几乎全为基因，密度极高；复杂生物基因密度降低，含大量非编码序列、调控序列、重复序列和内含子。"}, "cards": [{"front": "DNA包装成染色体的重要性有哪些？", "back": "便于装入细胞、保护DNA、细胞分裂时高效传递给子细胞、赋予DNA整体组织形式，有利于基因表达、复制、修复及重组。", "mnemonic": "装、护、传、组", "useImg": false}]}, {"i": 7, "sec": "染色体与DNA包装（核小体）", "title": "原核生物染色体结构 (p72)", "notes": "大肠杆菌染色体中央部分（约20%）由RNA和核心蛋白组成，帮助DNA盘曲包装；外围部分（约80%）为双链DNA超螺旋结构，扭结成约100个DNA环，每个环是一个相对独立的拓扑结构域。电镜照片显示环状质粒DNA。这种组织形式有利于DNA的压缩和复制。", "page": 72, "level": "掌握", "img": "assets/img/ch02/p072.jpg", "anim": null, "fig": null, "points": ["大肠杆菌染色体中央部分（约20%）由RNA和核心蛋白组成，帮助DNA盘曲包装", "外围部分（约80%）为双链DNA超螺旋结构", "扭结成约100个DNA环，每个环是一个相对独立的拓扑结构域", "电镜照片显示环状质粒DNA", "这种组织形式有利于DNA的压缩和复制"], "check": {"q": "关于大肠杆菌染色体结构的描述，下列哪项正确？", "o": ["A. 中央约80%由RNA和核心蛋白组成，外围约20%为双链DNA超螺旋", "B. 中央约20%由RNA和核心蛋白组成，外围约80%为双链DNA超螺旋，扭结成约100个相对独立的拓扑结构域", "C. 整个染色体完全由双链DNA超螺旋组成，没有RNA和蛋白参与", "D. 外围部分由RNA和核心蛋白组成，中央部分为双链DNA超螺旋"], "a": "B", "e": "大肠杆菌染色体中央约20%由RNA和核心蛋白组成，帮助DNA盘曲包装；外围约80%为双链DNA超螺旋，扭结成约100个DNA环，每个环是一个相对独立的拓扑结构域。"}, "cards": [{"front": "染色体多样性表现在哪些方面？", "back": "形状（环状或线状）、数目恒定、拷贝数（单倍体、二倍体或多倍体）。", "mnemonic": "形、数、拷", "useImg": false}]}, {"i": 8, "sec": "染色体与DNA包装（核小体）", "title": "真核细胞分裂周期中染色体结构变化 (p73)", "notes": "真核细胞周期中染色体结构动态变化：M期高度凝缩，彼此完全解缠；G1、S、G2期扩散，压缩程度显著降低。DNA复制需要几乎完全解组装和重新组装染色体相关蛋白。这种动态变化保证遗传物质正确复制和分离。", "page": 73, "level": "掌握", "img": "assets/img/ch02/p073.jpg", "anim": null, "fig": null, "points": ["M期染色体高度凝缩，彼此完全解缠", "G1、S、G2期染色体扩散，压缩程度显著降低", "DNA复制需要几乎完全解组装和重新组装染色体相关蛋白", "这种动态变化保证遗传物质正确复制和分离"], "check": {"q": "真核细胞分裂周期中，染色体结构变化的正确描述是？", "o": ["A. M期染色体扩散，G1、S、G2期高度凝缩", "B. M期高度凝缩，彼此完全解缠；G1、S、G2期扩散，压缩程度显著降低", "C. 整个细胞周期染色体始终保持高度凝缩状态", "D. DNA复制发生在M期，此时染色体高度凝缩"], "a": "B", "e": "真核细胞周期中，M期染色体高度凝缩且彼此完全解缠；G1、S、G2期扩散，压缩程度显著降低。DNA复制需要几乎完全解组装和重新组装染色体相关蛋白。"}, "cards": [{"front": "原核生物和真核生物的染色体形状分别是什么？", "back": "原核生物通常为环状染色体，真核生物为线状染色体。", "mnemonic": "原环真线", "useImg": false}]}, {"i": 9, "sec": "染色体与DNA包装（核小体）", "title": "染色质术语的起源 (p74)", "notes": "Walther Flemming于1882年首次使用“染色质”一词，描述细胞核中可被碱性染料染色的物质。这一术语的提出标志着对染色体结构研究的开端，为后续核小体假说和染色质结构研究奠定基础。", "page": 74, "level": "了解", "img": "assets/img/ch02/p074.jpg", "anim": null, "fig": null, "points": ["Walther Flemming于1882年首次使用“染色质”一词", "描述细胞核中可被碱性染料染色的物质", "这一术语的提出标志着对染色体结构研究的开端", "为后续核小体假说和染色质结构研究奠定基础"], "check": {"q": "“染色质”一词最早由谁于哪一年提出？", "o": ["A. Kornberg，1974年", "B. Walther Flemming，1882年", "C. Olins和Olins，1973年", "D. Oudet等，1975年"], "a": "B", "e": "Walther Flemming于1882年首次使用“染色质”一词，描述细胞核中可被碱性染料染色的物质，标志着对染色体结构研究的开端。"}, "cards": [{"front": "什么是C值悖论？", "back": "基因组大小与生物复杂性大致相关但并非严格线性，某些简单生物基因组反而更大。", "mnemonic": "", "useImg": false}]}, {"i": 10, "sec": "染色体与DNA包装（核小体）", "title": "电镜下观察到的染色质结构形式 (p75)", "notes": "通过电子显微镜可观察到不同层次的染色体结构，包括核小体、30 nm纤维、核骨架和中期染色体等。这些结构层次反映了DNA从松散到高度压缩的包装过程，是理解染色质高级结构的重要依据。", "page": 75, "level": "理解", "img": "assets/img/ch02/p075.jpg", "anim": null, "fig": null, "points": ["电子显微镜可观察到不同层次的染色体结构", "包括核小体、30 nm纤维、核骨架和中期染色体等", "这些结构层次反映了DNA从松散到高度压缩的包装过程", "是理解染色质高级结构的重要依据"], "check": {"q": "通过电子显微镜可观察到的染色质结构形式不包括下列哪项？", "o": ["A. 核小体", "B. 30 nm纤维", "C. 核骨架和中期染色体", "D. 核糖体"], "a": "D", "e": "电镜下可观察到核小体、30 nm纤维、核骨架和中期染色体等不同层次的染色体结构，核糖体不属于本页所列的染色质结构形式。"}, "cards": [{"front": "大肠杆菌与复杂生物的基因密度有何差异？", "back": "大肠杆菌基因组几乎全部由基因组成，基因密度极高；复杂生物基因密度降低，存在大量非编码序列。", "mnemonic": "", "useImg": false}]}, {"i": 11, "sec": "染色体与DNA包装（核小体）", "title": "DNA包装的多级水平 (p76)", "notes": "DNA包装分为四个主要层次：一级为核小体形成；二级为30 nm纤维（螺线管模型）；三级为核骨架；四级为有丝分裂（中期）染色体。每一级都进一步压缩DNA，最终使DNA长度压缩约10000倍，适应细胞核空间。", "page": 76, "level": "掌握", "img": "assets/img/ch02/p076.jpg", "anim": null, "fig": null, "points": ["一级为核小体形成", "二级为30 nm纤维（螺线管模型）", "三级为核骨架", "四级为有丝分裂（中期）染色体", "每一级都进一步压缩DNA，最终使DNA长度压缩约10000倍"], "check": {"q": "DNA包装的多级水平中，二级结构是指？", "o": ["A. 核小体形成", "B. 30 nm纤维（螺线管模型）", "C. 核骨架", "D. 有丝分裂（中期）染色体"], "a": "B", "e": "DNA包装分为四个主要层次：一级为核小体形成；二级为30 nm纤维（螺线管模型）；三级为核骨架；四级为有丝分裂（中期）染色体。"}, "cards": [{"front": "原核生物染色体结构如何组成？", "back": "中央约20%由RNA和核心蛋白组成帮助DNA盘曲；外围约80%为双链DNA超螺旋，扭结成约100个DNA环，每个环是一个相对独立的拓扑结构域。", "mnemonic": "20%RNA蛋白+80%超螺旋环", "useImg": false}]}, {"i": 12, "sec": "染色体与DNA包装（核小体）", "title": "核小体结构示意图 (p77)", "notes": "本页为图片/示意图，展示核小体的结构：组蛋白八聚体（由H3-H4四聚体和两个H2A-H2B二聚体组成）构成核心，DNA缠绕约1.67圈，H1结合连接DNA。该图直观说明核小体是染色质的基本结构单位，为理解DNA包装提供结构基础。", "page": 77, "level": "掌握", "img": "assets/img/ch02/p077.jpg", "anim": null, "fig": "图中中央为组蛋白八聚体，DNA双螺旋缠绕在其表面约1.67圈；注意H1结合在DNA进出端的连接DNA上，可据此理解核小体的基本组成。", "points": ["组蛋白八聚体由H3-H4四聚体和两个H2A-H2B二聚体组成，构成核心", "DNA缠绕约1.67圈", "H1结合连接DNA", "核小体是染色质的基本结构单位", "为理解DNA包装提供结构基础"], "check": {"q": "关于核小体结构，下列描述正确的是？", "o": ["A. 组蛋白八聚体由H1-H4四聚体和两个H2A-H2B二聚体组成", "B. 组蛋白八聚体由H3-H4四聚体和两个H2A-H2B二聚体组成，DNA缠绕约1.67圈，H1结合连接DNA", "C. DNA缠绕组蛋白八聚体约3圈，H1位于核心中央", "D. 核小体核心由H2A-H2B四聚体和两个H3-H4二聚体组成"], "a": "B", "e": "核小体中组蛋白八聚体由H3-H4四聚体和两个H2A-H2B二聚体组成，DNA缠绕约1.67圈，H1结合连接DNA。"}, "cards": [{"front": "真核细胞周期中染色体结构如何变化？", "back": "M期高度凝缩、彼此完全解缠；G1、S、G2期扩散，压缩程度显著降低。", "mnemonic": "M期紧，间期松", "useImg": false}]}, {"i": 13, "sec": "染色体与DNA包装（核小体）", "title": "核小体假说的提出 (p78)", "notes": "1974年Kornberg提出核小体假说，认为染色质由重复的组蛋白-DNA复合物组成。Olins和Olins（1973）、Woodcock（1973）等通过电镜观察支持该假说。Oudet等（1975）进一步证实核小体结构。这些研究奠定了染色质结构研究的基础。", "page": 78, "level": "理解", "img": "assets/img/ch02/p078.jpg", "anim": null, "fig": null, "points": ["1974年Kornberg提出核小体假说", "认为染色质由重复的组蛋白-DNA复合物组成", "Olins和Olins（1973）、Woodcock（1973）等通过电镜观察支持该假说", "Oudet等（1975）进一步证实核小体结构", "这些研究奠定了染色质结构研究的基础"], "check": {"q": "关于核小体假说的提出与证实，下列哪项正确？", "o": ["A. Kornberg于1974年提出核小体假说，Olins和Olins、Woodcock等通过电镜观察支持该假说，Oudet等进一步证实", "B. Walther Flemming于1882年提出核小体假说", "C. Oudet等于1974年提出核小体假说，Kornberg于1975年证实", "D. 核小体假说由Olins和Olins于1975年提出，Woodcock于1973年证实"], "a": "A", "e": "1974年Kornberg提出核小体假说，认为染色质由重复的组蛋白-DNA复合物组成；Olins和Olins（1973）、Woodcock（1973）等通过电镜观察支持该假说；Oudet等（1975）进一步证实核小体结构。"}, "cards": [{"front": "谁首次使用“染色质”一词？何时？", "back": "Walther Flemming于1882年首次使用。", "mnemonic": "", "useImg": false}]}, {"i": 14, "sec": "染色体与DNA包装（核小体）", "title": "DNase I消化揭示核小体包装 (p79)", "notes": "分离细胞核，用DNase I（非特异性内切酶）部分消化，琼脂糖凝胶电泳显示150-200 bp倍数的梯状条带。说明DNA被蛋白质保护，形成重复的核小体结构。这些蛋白质为组蛋白H1、H2A、H2B、H3和H4。该实验是核小体存在的经典证据。", "page": 79, "level": "掌握", "img": "assets/img/ch02/p079.jpg", "anim": null, "fig": null, "points": ["分离细胞核，用DNase I（非特异性内切酶）部分消化", "琼脂糖凝胶电泳显示150-200 bp倍数的梯状条带", "说明DNA被蛋白质保护，形成重复的核小体结构", "这些蛋白质为组蛋白H1、H2A、H2B、H3和H4", "该实验是核小体存在的经典证据"], "check": {"q": "用DNase I部分消化分离的细胞核后，琼脂糖凝胶电泳呈现约150-200 bp倍数的梯状条带，这一结果最能说明：", "o": ["A. DNA被蛋白质保护，形成重复的核小体结构", "B. DNA被完全降解为单核苷酸", "C. 组蛋白H1是唯一的DNA结合蛋白", "D. DNA复制呈半保留方式"], "a": "A", "e": "DNase I部分消化产生150-200 bp倍数的梯状条带，说明DNA被蛋白质周期性保护，是核小体存在的经典证据。"}, "cards": [{"front": "电镜下可观察到哪些染色质结构层次？", "back": "核小体、30 nm纤维、核骨架和中期染色体等。", "mnemonic": "", "useImg": false}]}, {"i": 15, "sec": "染色体与DNA包装（核小体）", "title": "核小体 (p80)", "notes": "核小体是染色质的基本结构单位，由组蛋白八聚体和约146 bp DNA组成。DNA缠绕在组蛋白八聚体表面约1.67圈，形成盘状核心颗粒。相邻核小体由连接DNA相连，H1结合在连接DNA上。核小体的形成是DNA压缩的第一级。", "page": 80, "level": "掌握", "img": "assets/img/ch02/p080.jpg", "anim": null, "fig": null, "points": ["核小体是染色质的基本结构单位", "由组蛋白八聚体和约146 bp DNA组成", "DNA缠绕在组蛋白八聚体表面约1.67圈，形成盘状核心颗粒", "相邻核小体由连接DNA相连，H1结合在连接DNA上", "核小体的形成是DNA压缩的第一级"], "check": {"q": "关于核小体结构，下列叙述正确的是：", "o": ["A. 由组蛋白八聚体和约146 bp DNA组成，DNA缠绕约1.67圈", "B. 由组蛋白四聚体和约200 bp DNA组成，DNA缠绕约1圈", "C. 不含连接DNA，H1位于核心颗粒内部", "D. 是DNA压缩的第二级结构"], "a": "A", "e": "核小体由组蛋白八聚体和约146 bp DNA组成，DNA缠绕约1.67圈，是DNA压缩的第一级；相邻核小体由连接DNA相连，H1结合在连接DNA上。"}, "cards": [{"front": "DNA包装的四个主要层次是什么？", "back": "一级：核小体；二级：30 nm纤维（螺线管）；三级：核骨架；四级：有丝分裂（中期）染色体。", "mnemonic": "核、纤、架、染", "useImg": false}]}, {"i": 16, "sec": "染色体与DNA包装（核小体）", "title": "组蛋白的种类 (p81)", "notes": "真核细胞含有5种组蛋白：H1、H2A、H2B、H3和H4。其中H2A、H2B、H3、H4为核心组蛋白，各两个组成八聚体；H1为连接组蛋白，结合在核小体之间的连接DNA上。组蛋白富含碱性氨基酸，带正电荷，与带负电的DNA结合。", "page": 81, "level": "掌握", "img": "assets/img/ch02/p081.jpg", "anim": null, "fig": null, "points": ["真核细胞含有5种组蛋白：H1、H2A、H2B、H3和H4", "H2A、H2B、H3、H4为核心组蛋白，各两个组成八聚体", "H1为连接组蛋白，结合在核小体之间的连接DNA上", "组蛋白富含碱性氨基酸，带正电荷，与带负电的DNA结合"], "check": {"q": "真核细胞中属于核心组蛋白、各两个组成组蛋白八聚体的是：", "o": ["A. H1、H2A、H2B、H3", "B. H2A、H2B、H3、H4", "C. H1、H2A、H3、H4", "D. H1、H2B、H3、H4"], "a": "B", "e": "H2A、H2B、H3、H4为核心组蛋白，各两个组成八聚体；H1为连接组蛋白，结合在连接DNA上。"}, "cards": [{"front": "DNA包装最终使DNA长度压缩约多少倍？", "back": "约10000倍。", "mnemonic": "", "useImg": false}]}, {"i": 17, "sec": "染色体与DNA包装（核小体）", "title": "组蛋白的特性 (p82)", "notes": "组蛋白是细胞核中含量丰富的蛋白质，总质量几乎与DNA相当；在中性pH下带明显正电荷；大多数组蛋白在不同物种间高度保守，无组织特异性。这些特性使其能与DNA紧密结合并参与染色质结构形成。", "page": 82, "level": "掌握", "img": "assets/img/ch02/p082.jpg", "anim": null, "fig": null, "points": ["组蛋白是细胞核中含量丰富的蛋白质，总质量几乎与DNA相当", "在中性pH下带明显正电荷", "大多数组蛋白在不同物种间高度保守", "无组织特异性", "这些特性使其能与DNA紧密结合并参与染色质结构形成"], "check": {"q": "下列哪项不是组蛋白的典型特性？", "o": ["A. 在中性pH下带明显正电荷", "B. 总质量几乎与DNA相当", "C. 大多数组蛋白在不同物种间高度保守", "D. 具有明显的组织特异性"], "a": "D", "e": "组蛋白大多数在不同物种间高度保守，无组织特异性；其带正电荷、含量丰富，总质量几乎与DNA相当。"}, "cards": [{"front": "核小体的核心由什么组成？", "back": "组蛋白八聚体（1个H3-H4四聚体和2个H2A-H2B二聚体）。", "mnemonic": "四聚体+2个二聚体", "useImg": false}]}, {"i": 18, "sec": "染色体与DNA包装（核小体）", "title": "组蛋白的氨基酸分布与修饰 (p83)", "notes": "组蛋白肽链氨基酸分布不对称：N端富含碱性氨基酸，C端富含疏水基团。组蛋白修饰多发生在N端，包括乙酰化、甲基化、磷酸化等，影响染色质结构和基因表达。组蛋白基因通常不是单拷贝，而是在基因组中重复多次，以满足大量组蛋白需求。", "page": 83, "level": "掌握", "img": "assets/img/ch02/p083.jpg", "anim": null, "fig": null, "points": ["组蛋白肽链氨基酸分布不对称：N端富含碱性氨基酸，C端富含疏水基团", "组蛋白修饰多发生在N端，包括乙酰化、甲基化、磷酸化等", "修饰影响染色质结构和基因表达", "组蛋白基因通常不是单拷贝，而是在基因组中重复多次，以满足大量组蛋白需求"], "check": {"q": "关于组蛋白的氨基酸分布与修饰，下列叙述正确的是：", "o": ["A. N端富含疏水基团，C端富含碱性氨基酸", "B. 修饰多发生在C端，包括乙酰化、甲基化、磷酸化等", "C. N端富含碱性氨基酸，修饰多发生在N端", "D. 组蛋白基因通常为单拷贝"], "a": "C", "e": "组蛋白肽链N端富含碱性氨基酸，C端富含疏水基团；修饰多发生在N端；组蛋白基因通常重复多次而非单拷贝。"}, "cards": [{"front": "核小体中DNA缠绕组蛋白八聚体多少圈？", "back": "约1.67圈。", "mnemonic": "", "useImg": false}]}, {"i": 19, "sec": "染色体与DNA包装（核小体）", "title": "核心组蛋白的结构域 (p84)", "notes": "核心组蛋白共享一个共同的结构折叠，称为组蛋白折叠域（histone-fold domain），由3个α螺旋和2个环组成。每个核心组蛋白具有N端“尾巴”，是广泛修饰的位点。这些结构特征对组蛋白八聚体的组装和DNA缠绕至关重要。", "page": 84, "level": "理解", "img": "assets/img/ch02/p084.jpg", "anim": null, "fig": null, "points": ["核心组蛋白共享一个共同的结构折叠，称为组蛋白折叠域（histone-fold domain）", "组蛋白折叠域由3个α螺旋和2个环组成", "每个核心组蛋白具有N端“尾巴”，是广泛修饰的位点", "这些结构特征对组蛋白八聚体的组装和DNA缠绕至关重要"], "check": {"q": "核心组蛋白共享的结构折叠域（histone-fold domain）由什么组成？", "o": ["A. 3个α螺旋和2个环", "B. 2个α螺旋和3个环", "C. 4个α螺旋和1个环", "D. 1个α螺旋和4个环"], "a": "A", "e": "组蛋白折叠域由3个α螺旋和2个环组成；每个核心组蛋白还有广泛修饰的N端尾巴。"}, "cards": [{"front": "谁提出了核小体假说？何时？", "back": "Kornberg于1974年提出核小体假说。", "mnemonic": "", "useImg": false}]}, {"i": 20, "sec": "染色体与DNA包装（核小体）", "title": "核小体组装示意图 (p85)", "notes": "本页为图片/示意图，展示核小体组装过程：H3-H4四聚体首先结合DNA，然后两个H2A-H2B二聚体加入，形成组蛋白八聚体，DNA缠绕其上形成核小体。该图说明核小体组装的逐步性和有序性。", "page": 85, "level": "掌握", "img": "assets/img/ch02/p085.jpg", "anim": null, "fig": "图中先显示H3-H4四聚体与DNA结合，随后两个H2A-H2B二聚体从两侧加入，最后DNA缠绕形成核小体；按箭头顺序可理解组装的逐步性和有序性。", "points": ["H3-H4四聚体首先结合DNA", "然后两个H2A-H2B二聚体加入，形成组蛋白八聚体", "DNA缠绕其上形成核小体", "该图说明核小体组装的逐步性和有序性"], "check": {"q": "根据核小体组装示意图，核小体组装过程的正确顺序是：", "o": ["A. H2A-H2B二聚体先结合DNA，再加入H3-H4四聚体", "B. H3-H4四聚体先结合DNA，再加入两个H2A-H2B二聚体", "C. 八个组蛋白同时结合DNA", "D. H1先结合DNA，再组装核心组蛋白"], "a": "B", "e": "组装过程为：H3-H4四聚体首先结合DNA，然后两个H2A-H2B二聚体加入，形成组蛋白八聚体，DNA缠绕其上形成核小体。"}, "cards": [{"front": "DNase I消化实验如何证明核小体结构？", "back": "部分消化后琼脂糖凝胶电泳显示150-200 bp倍数的梯状条带，说明DNA被蛋白质保护形成重复的核小体结构。", "mnemonic": "梯状条带=核小体重复", "useImg": false}]}, {"i": 21, "sec": "染色体与DNA包装（核小体）", "title": "组蛋白八聚体的组成 (p86)", "notes": "组蛋白八聚体由1个H3-H4四聚体和2个H2A-H2B二聚体组成。H3-H4四聚体位于核心颗粒中央，两个H2A-H2B二聚体分别位于两侧。这种排列方式使八聚体呈盘状，为DNA缠绕提供表面。", "page": 86, "level": "掌握", "img": "assets/img/ch02/p086.jpg", "anim": null, "fig": null, "points": ["组蛋白八聚体由1个H3-H4四聚体和2个H2A-H2B二聚体组成", "H3-H4四聚体位于核心颗粒中央", "两个H2A-H2B二聚体分别位于两侧", "这种排列方式使八聚体呈盘状，为DNA缠绕提供表面"], "check": {"q": "关于组蛋白八聚体的组成和排列，下列哪项正确？", "o": ["A. 由2个H3-H4四聚体和1个H2A-H2B二聚体组成", "B. 由1个H3-H4四聚体和2个H2A-H2B二聚体组成", "C. 由4个H2A-H2B二聚体组成", "D. 由1个H2A-H2B四聚体和2个H3-H4二聚体组成"], "a": "B", "e": "组蛋白八聚体由1个H3-H4四聚体和2个H2A-H2B二聚体组成；H3-H4四聚体位于中央，两个H2A-H2B二聚体分别位于两侧。"}, "cards": [{"front": "核小体由什么组成？", "back": "组蛋白八聚体和约146 bp DNA，DNA缠绕约1.67圈形成盘状核心颗粒，相邻核小体由连接DNA相连，H1结合在连接DNA上。", "mnemonic": "", "useImg": false}]}, {"i": 22, "sec": "染色体与DNA包装（核小体）", "title": "核小体核心颗粒的逐步组装 (p87)", "notes": "H3-H4四聚体首先结合DNA，然后结合两个H2A-H2B二聚体，形成组蛋白八聚体。这一逐步组装过程确保核小体正确形成，并受组蛋白伴侣和修饰调控。", "page": 87, "level": "掌握", "img": "assets/img/ch02/p087.jpg", "anim": null, "fig": null, "points": ["H3-H4四聚体首先结合DNA", "然后结合两个H2A-H2B二聚体，形成组蛋白八聚体", "这一逐步组装过程确保核小体正确形成", "并受组蛋白伴侣和修饰调控"], "check": {"q": "核小体核心颗粒逐步组装时，最先结合DNA的是哪一组件？", "o": ["A. H2A-H2B二聚体", "B. H1组蛋白", "C. H3-H4四聚体", "D. 完整组蛋白八聚体"], "a": "C", "e": "组装过程中H3-H4四聚体首先结合DNA，随后两个H2A-H2B二聚体加入，形成组蛋白八聚体。"}, "cards": [{"front": "真核细胞含有哪5种组蛋白？", "back": "H1、H2A、H2B、H3和H4。", "mnemonic": "", "useImg": false}]}, {"i": 23, "sec": "染色体与DNA包装（核小体）", "title": "核小体核心颗粒的晶体结构 (p88)", "notes": "Luger和Richmond于1997年在Nature发表核小体核心颗粒的晶体结构（2.8 Å），揭示DNA缠绕组蛋白八聚体的精确方式。该结构显示DNA以左手超螺旋缠绕约1.67圈，组蛋白尾部伸出。这一成果是染色质结构研究的里程碑。", "page": 88, "level": "理解", "img": "assets/img/ch02/p088.jpg", "anim": null, "fig": null, "points": ["Luger和Richmond于1997年在Nature发表核小体核心颗粒的晶体结构（2.8 Å）", "揭示DNA缠绕组蛋白八聚体的精确方式", "该结构显示DNA以左手超螺旋缠绕约1.67圈，组蛋白尾部伸出", "这一成果是染色质结构研究的里程碑"], "check": {"q": "Luger和Richmond于1997年发表的核小体核心颗粒晶体结构，主要揭示了什么？", "o": ["A. DNA以右手超螺旋缠绕组蛋白八聚体约1.67圈", "B. DNA以左手超螺旋缠绕组蛋白八聚体约1.67圈", "C. DNA以左手超螺旋缠绕组蛋白八聚体约2.5圈", "D. DNA不缠绕组蛋白，仅与其表面结合"], "a": "B", "e": "该2.8 Å晶体结构显示DNA以左手超螺旋缠绕组蛋白八聚体约1.67圈，组蛋白尾部伸出，是染色质结构研究的里程碑。"}, "cards": [{"front": "哪些是核心组蛋白？哪些是连接组蛋白？", "back": "H2A、H2B、H3、H4为核心组蛋白；H1为连接组蛋白。", "mnemonic": "H1连接，其余核心", "useImg": false}]}, {"i": 24, "sec": "染色体与DNA包装（核小体）", "title": "核小体的形状 (p89)", "notes": "核小体呈圆柱形，DNA围绕组蛋白八聚体表面组织成约1又2/3圈。DNA的缠绕导致其长度压缩约6倍，形成盘状核心颗粒。这种结构是染色质进一步压缩的基础。", "page": 89, "level": "掌握", "img": "assets/img/ch02/p089.jpg", "anim": null, "fig": null, "points": ["核小体呈圆柱形", "DNA围绕组蛋白八聚体表面组织成约1又2/3圈", "DNA的缠绕导致其长度压缩约6倍", "形成盘状核心颗粒", "这种结构是染色质进一步压缩的基础"], "check": {"q": "关于核小体形状及DNA缠绕的压缩效果，下列哪项正确？", "o": ["A. 核小体呈圆柱形，DNA缠绕约1又2/3圈，长度压缩约6倍", "B. 核小体呈球形，DNA缠绕约1圈，长度压缩约2倍", "C. 核小体呈圆柱形，DNA缠绕约3圈，长度压缩约10倍", "D. 核小体呈盘状，DNA不缠绕，长度不压缩"], "a": "A", "e": "核小体呈圆柱形，DNA围绕组蛋白八聚体表面组织成约1又2/3圈，导致DNA长度压缩约6倍，形成盘状核心颗粒。"}, "cards": [{"front": "组蛋白有哪些特性？", "back": "细胞核中含量丰富，总质量几乎与DNA相当；中性pH下带明显正电荷；不同物种间高度保守，无组织特异性。", "mnemonic": "多、正、保守", "useImg": false}]}, {"i": 25, "sec": "染色体与DNA包装（核小体）", "title": "组蛋白H1的结合 (p90)", "notes": "组蛋白H1结合在核小体之间的连接DNA上，锁住核小体DNA的进出端，稳定核小体结构，并促进染色质高级结构的形成。H1的結合使核小体排列更紧密，有助于30 nm纤维的形成。", "page": 90, "level": "掌握", "img": "assets/img/ch02/p090.jpg", "anim": null, "fig": null, "points": ["组蛋白H1结合在核小体之间的连接DNA上", "锁住核小体DNA的进出端", "稳定核小体结构", "促进染色质高级结构的形成", "H1的结合使核小体排列更紧密，有助于30 nm纤维的形成"], "check": {"q": "组蛋白H1在染色质结构中的主要作用是什么？", "o": ["A. 替代H3-H4四聚体形成核小体核心", "B. 结合在核小体之间的连接DNA上，锁住进出端并稳定核小体结构", "C. 直接催化DNA超螺旋的解旋", "D. 组成组蛋白八聚体的中央四聚体"], "a": "B", "e": "H1结合在核小体之间的连接DNA上，锁住核小体DNA的进出端，稳定核小体结构，并促进30 nm纤维等高级结构的形成。"}, "cards": [{"front": "组蛋白修饰多发生在哪里？有哪些类型？", "back": "多发生在N端，包括乙酰化、甲基化、磷酸化等。", "mnemonic": "", "useImg": false}]}, {"i": 26, "sec": "染色体与DNA包装（核小体）", "title": "核小体组装过程小结 (p91)", "notes": "核小体组装过程包括：H3-H4四聚体结合DNA，H2A-H2B二聚体加入形成八聚体，DNA缠绕形成核小体，H1结合连接DNA。该过程受组蛋白伴侣和修饰调控，是染色质结构动态变化的基础。", "page": 91, "level": "掌握", "img": "assets/img/ch02/p091.jpg", "anim": null, "fig": null, "points": ["H3-H4四聚体结合DNA", "H2A-H2B二聚体加入形成八聚体", "DNA缠绕形成核小体", "H1结合连接DNA", "该过程受组蛋白伴侣和修饰调控，是染色质结构动态变化的基础"], "check": {"q": "核小体组装过程小结中，正确的顺序是？", "o": ["A. H2A-H2B二聚体先结合DNA，随后H3-H4四聚体加入，最后H1结合", "B. H3-H4四聚体先结合DNA，H2A-H2B二聚体加入形成八聚体，DNA缠绕，H1结合连接DNA", "C. H1先结合DNA，然后H3-H4四聚体和H2A-H2B二聚体同时加入", "D. 组蛋白八聚体先完整形成，再与DNA结合，不需要H1"], "a": "B", "e": "核小体组装包括H3-H4四聚体结合DNA、H2A-H2B二聚体加入形成八聚体、DNA缠绕形成核小体、H1结合连接DNA，并受组蛋白伴侣和修饰调控。"}, "cards": [{"front": "什么是组蛋白折叠域？", "back": "核心组蛋白共享的共同结构折叠，由3个α螺旋和2个环组成。", "mnemonic": "3α螺旋+2环", "useImg": false}]}, {"i": 27, "sec": "染色体与DNA包装（核小体）", "title": "核小体结构要点总结 (p92)", "notes": "每个核小体单位包括约200 bp DNA、一个组蛋白八聚体和一个H1分子。组蛋白八聚体构成盘状核心，两个H3-H4形成四聚体位于中央，两个H2A-H2B二聚体位于两侧。146 bp DNA缠绕八聚体，H1结合额外20 bp DNA，锁住进出端。包括H1和166 bp DNA的结构称染色质小体。相邻核小体以连接DNA相连，形成约200 bp的重复单位。", "page": 92, "level": "掌握", "img": "assets/img/ch02/p092.jpg", "anim": null, "fig": null, "points": ["每个核小体单位包括约200 bp DNA、一个组蛋白八聚体和一个H1分子", "组蛋白八聚体构成盘状核心，两个H3-H4形成四聚体位于中央，两个H2A-H2B二聚体位于两侧", "146 bp DNA缠绕八聚体，H1结合额外20 bp DNA，锁住进出端", "包括H1和166 bp DNA的结构称染色质小体", "相邻核小体以连接DNA相连，形成约200 bp的重复单位"], "check": {"q": "根据核小体结构要点，下列哪项描述正确？", "o": ["A. 每个核小体单位包括约146 bp DNA、一个组蛋白八聚体和一个H1分子", "B. 146 bp DNA缠绕八聚体，H1结合额外20 bp DNA，包括H1和166 bp DNA的结构称染色质小体", "C. 相邻核小体之间没有连接DNA，形成约100 bp的重复单位", "D. H3-H4四聚体位于两侧，两个H2A-H2B二聚体位于中央"], "a": "B", "e": "146 bp DNA缠绕八聚体，H1结合额外20 bp DNA，包括H1和166 bp DNA的结构称染色质小体；每个核小体单位约200 bp，H3-H4四聚体位于中央，H2A-H2B二聚体位于两侧。"}, "cards": [{"front": "组蛋白八聚体如何组成？", "back": "1个H3-H4四聚体位于中央，2个H2A-H2B二聚体分别位于两侧。", "mnemonic": "中央H3H4，两侧H2AH2B", "useImg": false}]}, {"i": 28, "sec": "染色体与DNA包装（核小体）", "title": "组蛋白变体改变核小体功能 (p93)", "notes": "真核生物中存在多种组蛋白变体，可替换标准组蛋白形成替代核小体。例如H2A.Z、H3.3、CENP-A等，参与基因表达调控、染色质重塑、着丝粒功能等。组蛋白变体增加了核小体功能的多样性，是表观遗传调控的重要机制。", "page": 93, "level": "理解", "img": "assets/img/ch02/p093.jpg", "anim": null, "fig": null, "points": ["真核生物中存在多种组蛋白变体，可替换标准组蛋白形成替代核小体", "例如H2A.Z、H3.3、CENP-A等", "参与基因表达调控、染色质重塑、着丝粒功能等", "组蛋白变体增加了核小体功能的多样性", "是表观遗传调控的重要机制"], "check": {"q": "关于组蛋白变体与核小体功能，下列叙述正确的是？", "o": ["A. 组蛋白变体可替换标准组蛋白形成替代核小体，增加核小体功能的多样性", "B. 组蛋白变体只存在于原核生物中，与基因表达调控无关", "C. H2A.Z、H3.3、CENP-A属于标准组蛋白，不参与表观遗传调控", "D. 组蛋白变体替换后形成的核小体功能与标准核小体完全相同"], "a": "A", "e": "该页指出真核生物中存在多种组蛋白变体，可替换标准组蛋白形成替代核小体，如H2A.Z、H3.3、CENP-A等，参与基因表达调控、染色质重塑、着丝粒功能等，增加核小体功能多样性，是表观遗传调控的重要机制。"}, "cards": [{"front": "核小体核心颗粒的逐步组装过程是什么？", "back": "H3-H4四聚体首先结合DNA，然后两个H2A-H2B二聚体加入，形成组蛋白八聚体。", "mnemonic": "先四后二", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_30", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "下列关于核小体结构的描述，哪一项是正确的？", "o": ["A. 核小体由H1、H2A、H2B、H3和H4各两个分子组成八聚体", "B. 核小体核心颗粒由H3-H4四聚体和两个H2A-H2B二聚体组成，DNA缠绕约1.67圈", "C. 核小体中的DNA长度为200 bp，缠绕组蛋白八聚体两圈", "D. 组蛋白H1位于核小体核心颗粒中央，直接参与DNA缠绕"], "a": "B", "e": "核小体核心颗粒由H3-H4四聚体和两个H2A-H2B二聚体组成，DNA缠绕约1.67圈；H1为连接组蛋白，不参与八聚体核心；核心DNA约146 bp，加上连接DNA约200 bp。", "kp": "ch02_s6_23"}, {"id": "ch02_mcq_31", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "DNase I消化染色质实验得到150-200 bp倍数的梯状条带，这一结果说明什么？", "o": ["A. DNA被组蛋白保护，形成重复的核小体结构", "B. DNA被DNase I完全降解", "C. 染色质中不存在蛋白质", "D. DNA是环状结构"], "a": "A", "e": "DNase I部分消化后产生150-200 bp倍数的DNA片段，说明DNA被蛋白质保护，形成重复的核小体结构，这是核小体存在的经典证据。", "kp": "ch02_s6_14"}, {"id": "ch02_mcq_32", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "关于组蛋白的特性，下列哪项错误？", "o": ["A. 组蛋白在中性pH下带正电荷", "B. 组蛋白在不同物种间高度保守", "C. 组蛋白基因通常是单拷贝基因", "D. 组蛋白修饰多发生在N端"], "a": "C", "e": "组蛋白基因通常不是单拷贝，而是在基因组中重复多次，以满足大量组蛋白的需求；其他选项均正确。", "kp": "ch02_s6_17"}, {"id": "ch02_mcq_33", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "DNA包装的多级水平中，第二级结构是？", "o": ["A. 核小体", "B. 30 nm纤维（螺线管模型）", "C. 核骨架", "D. 中期染色体"], "a": "B", "e": "DNA包装一级为核小体，二级为30 nm纤维（螺线管模型），三级为核骨架，四级为有丝分裂中期染色体。", "kp": "ch02_s6_11"}, {"id": "ch02_mcq_34", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "关于原核生物染色体结构，下列描述正确的是？", "o": ["A. 大肠杆菌染色体完全由蛋白质组成", "B. 大肠杆菌染色体外围部分为双链DNA超螺旋，形成约100个独立的拓扑结构域", "C. 原核生物染色体为线状", "D. 原核生物染色体没有DNA环"], "a": "B", "e": "大肠杆菌染色体中央部分（约20%）由RNA和核心蛋白组成，外围部分（约80%）为双链DNA超螺旋，扭结成约100个DNA环，每个环是一个相对独立的拓扑结构域。", "kp": "ch02_s6_7"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}, {"i": 7, "name": "模块八：组蛋白变体、高级结构与组蛋白修饰", "slides": [{"i": 0, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "组蛋白变体及其功能 (p94)", "notes": "组蛋白变体是标准组蛋白的替代形式，可在特定染色质区域替换常规组蛋白，从而改变核小体性质与功能。H2A.Z 富集于启动子和调控区，影响核小体稳定性并参与转录调控；H2A.X 广泛分布，DNA 双链断裂后被磷酸化为 γ-H2A.X，作为 DNA 损伤标记参与修复；macroH2A 见于沉默染色质和失活 X 染色体，参与转录抑制；H3.3 可在不依赖 DNA 复制的情况下装配，常与活跃转录相关；CENP-A 位于着丝粒，决定其身份并帮助动粒组装；H1 变体影响染色质高级压缩。", "page": 94, "level": "掌握", "img": "assets/img/ch02/p094.jpg", "anim": null, "fig": null, "points": ["组蛋白变体是标准组蛋白的替代形式，可替换常规组蛋白改变核小体性质与功能", "H2A.Z富集于启动子和调控区，影响核小体稳定性并参与转录调控", "H2A.X在DNA双链断裂后被磷酸化为γ-H2A.X，作为DNA损伤标记参与修复", "macroH2A见于沉默染色质和失活X染色体，参与转录抑制", "H3.3不依赖DNA复制装配，常与活跃转录相关"], "check": {"q": "下列哪种组蛋白变体在DNA双链断裂后被磷酸化，作为DNA损伤标记参与修复？", "o": ["A. H2A.Z", "B. H2A.X", "C. macroH2A", "D. CENP-A"], "a": "B", "e": "H2A.X广泛分布，DNA双链断裂后被磷酸化为γ-H2A.X，作为DNA损伤标记参与修复。"}, "cards": [{"front": "什么是组蛋白变体？它们的基本功能是什么？", "back": "组蛋白变体是标准组蛋白的替代形式，可在特定染色质区域替换常规组蛋白，改变核小体性质与功能。", "mnemonic": "变体=换零件，改变核小体性能", "useImg": false}]}, {"i": 1, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "CENP-A 与着丝粒核小体 (p95)", "notes": "该页示意图说明 CENP-A 是 H3 的组蛋白变体，它特异性地掺入着丝粒 DNA 区域的核小体中，取代常规 H3，形成着丝粒特异性核小体。这种替换是着丝粒身份的表观遗传标志，为动粒蛋白提供结合平台，确保染色体在细胞分裂时正确分离。图中还概括了通过掺入组蛋白变体改变染色质组成的方式，即组蛋白变体交换可重塑核小体并影响染色质功能。", "page": 95, "level": "掌握", "img": "assets/img/ch02/p095.jpg", "anim": null, "fig": "图中展示CENP-A取代常规H3掺入着丝粒区域核小体的过程。看时注意着丝粒DNA区域核小体中H3被CENP-A替换，形成着丝粒特异性核小体，并进一步为动粒蛋白提供结合平台。", "points": ["CENP-A是H3的组蛋白变体，特异性掺入着丝粒DNA区域核小体取代常规H3", "着丝粒特异性核小体是着丝粒身份的表观遗传标志", "为动粒蛋白提供结合平台，确保染色体在细胞分裂时正确分离", "组蛋白变体交换可重塑核小体并影响染色质功能"], "check": {"q": "关于CENP-A的叙述，正确的是？", "o": ["A. 它是H2A的变体，掺入启动子区", "B. 它是H3的变体，特异掺入着丝粒DNA区域取代常规H3", "C. 它促进30 nm纤维形成", "D. 它富集于失活X染色体，参与转录抑制"], "a": "B", "e": "CENP-A是H3的组蛋白变体，特异性掺入着丝粒DNA区域核小体取代常规H3，是着丝粒身份的表观遗传标志。"}, "cards": [{"front": "H2A.Z、H2A.X、macroH2A、H3.3 各自的功能是什么？", "back": "H2A.Z富集于启动子和调控区，影响核小体稳定性并参与转录调控；H2A.X在DNA双链断裂后被磷酸化为γ-H2A.X，作为DNA损伤标记参与修复；macroH2A见于沉默染色质和失活X染色体，参与转录抑制；H3.3可不依赖DNA复制装配，常与活跃转录相关。", "mnemonic": "Z调转录，X标损伤，macro沉默，H3.3活跃", "useImg": false}]}, {"i": 2, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "H1 促进 30 nm 纤维形成 (p96)", "notes": "H1 是连接组蛋白，结合在核小体核心颗粒之间的连接 DNA 上，帮助稳定高级结构。它促进核小体阵列折叠成 30 nm 染色质纤维，这是染色质压缩的重要层级。30 nm 纤维的形成使 DNA 进一步缩短，有利于遗传物质在细胞核内的高度组织化包装，同时也影响基因表达的可及性。", "page": 96, "level": "掌握", "img": "assets/img/ch02/p096.jpg", "anim": null, "fig": null, "points": ["H1是连接组蛋白，结合在核小体核心颗粒之间的连接DNA上", "H1帮助稳定高级结构，促进核小体阵列折叠成30 nm染色质纤维", "30 nm纤维是染色质压缩的重要层级，使DNA进一步缩短", "有利于遗传物质在细胞核内高度组织化包装，并影响基因表达可及性"], "check": {"q": "H1组蛋白的主要功能是？", "o": ["A. 取代H3形成着丝粒特异性核小体", "B. 结合连接DNA，促进核小体阵列折叠成30 nm染色质纤维", "C. 作为DNA损伤标记参与修复", "D. 在不依赖DNA复制的情况下装配，与活跃转录相关"], "a": "B", "e": "H1是连接组蛋白，结合核小体核心颗粒之间的连接DNA，帮助稳定高级结构，促进30 nm纤维形成。"}, "cards": [{"front": "CENP-A 是什么？它在着丝粒中起什么作用？", "back": "CENP-A是H3的组蛋白变体，特异性掺入着丝粒DNA区域的核小体取代常规H3，形成着丝粒特异性核小体，是着丝粒身份的表观遗传标志，为动粒蛋白提供结合平台，确保染色体正确分离。", "mnemonic": "CENP-A=着丝粒身份证", "useImg": false}]}, {"i": 3, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "30 nm 纤维组装模型：螺线管与之字形 (p97)", "notes": "关于 30 nm 染色质纤维的组装方式，目前主要有两种模型：螺线管模型认为核小体沿一个中心轴螺旋排列，形成规则的中空螺旋；之字形模型则认为核小体以锯齿状方式折叠，相邻核小体之间通过连接 DNA 和 H1 相互作用。两种模型都试图解释核小体阵列如何压缩成 30 nm 纤维，但具体机制仍存在争议，取决于染色质条件和实验方法。", "page": 97, "level": "理解", "img": "assets/img/ch02/p097.jpg", "anim": null, "fig": null, "points": ["30 nm染色质纤维组装主要有螺线管模型和之字形模型两种", "螺线管模型认为核小体沿中心轴螺旋排列，形成规则中空螺旋", "之字形模型认为核小体以锯齿状折叠，相邻核小体通过连接DNA和H1相互作用", "两种模型均试图解释核小体阵列如何压缩成30 nm纤维，但具体机制仍有争议", "机制取决于染色质条件和实验方法"], "check": {"q": "关于30 nm染色质纤维组装模型，下列描述正确的是？", "o": ["A. 螺线管模型认为核小体以锯齿状方式折叠", "B. 之字形模型认为核小体沿中心轴螺旋排列形成中空螺旋", "C. 螺线管模型认为核小体沿中心轴螺旋排列形成规则中空螺旋，之字形模型认为核小体以锯齿状折叠", "D. 两种模型已达成一致，机制完全清楚"], "a": "C", "e": "螺线管模型认为核小体沿中心轴螺旋排列形成规则中空螺旋；之字形模型认为核小体以锯齿状方式折叠，相邻核小体通过连接DNA和H1相互作用。"}, "cards": [{"front": "H1 组蛋白的功能是什么？", "back": "H1是连接组蛋白，结合在核小体核心颗粒之间的连接DNA上，帮助稳定高级结构，促进核小体阵列折叠成30 nm染色质纤维。", "mnemonic": "H1=连接器，拉紧成30nm纤维", "useImg": false}]}, {"i": 4, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "染色质进一步压缩与核骨架模型 (p98)", "notes": "在 30 nm 纤维基础上，DNA 还需要再压缩约 103–104 倍才能装入细胞核，但这一机制尚不完全清楚。目前提出核骨架模型，认为染色质通过大量核小体 DNA 形成的环状结构锚定在核骨架上，从而实现更高层次的压缩。这些环状结构可能由特定蛋白复合物固定，使染色质在核内形成有序的三维组织，并参与基因表达调控。", "page": 98, "level": "理解", "img": "assets/img/ch02/p098.jpg", "anim": null, "fig": null, "points": ["在30 nm纤维基础上DNA还需再压缩约10^3–10^4倍才能装入细胞核", "该更高层次压缩机制尚不完全清楚", "核骨架模型认为染色质通过核小体DNA形成的环状结构锚定在核骨架上", "环状结构可能由特定蛋白复合物固定，使染色质形成有序三维组织", "参与基因表达调控"], "check": {"q": "关于染色质进一步压缩的核骨架模型，下列叙述正确的是？", "o": ["A. 30 nm纤维已足以将DNA装入细胞核，无需进一步压缩", "B. 染色质通过大量核小体DNA形成的环状结构锚定在核骨架上实现更高层次压缩", "C. 核骨架模型认为染色质以线性方式随机分布", "D. 该模型已完全阐明染色质压缩机制"], "a": "B", "e": "核骨架模型认为染色质通过大量核小体DNA形成的环状结构锚定在核骨架上，实现更高层次压缩，但机制尚不完全清楚。"}, "cards": [{"front": "30 nm 染色质纤维的两种组装模型是什么？", "back": "螺线管模型：核小体沿中心轴螺旋排列形成规则中空螺旋；之字形模型：核小体以锯齿状折叠，相邻核小体通过连接DNA和H1相互作用。两种模型仍有争议。", "mnemonic": "螺线管=螺旋楼梯，之字形=锯齿折叠", "useImg": false}]}, {"i": 5, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "核小体 DNA 大环参与 DNA 进一步压缩 (p99)", "notes": "该页进一步说明 DNA 的更高层次压缩涉及核小体 DNA 形成大环。这些环状结构以核骨架或核基质为锚点，将 30 nm 纤维组织成环状结构域，从而实现 DNA 的进一步缩短和有序排列。这种环状组织不仅有助于染色质压缩，也可能通过环的拓扑结构影响基因的可及性和表达调控，是染色质高级结构的重要特征。", "page": 99, "level": "理解", "img": "assets/img/ch02/p099.jpg", "anim": null, "fig": null, "points": ["DNA更高层次压缩涉及核小体DNA形成大环", "环状结构以核骨架或核基质为锚点，将30 nm纤维组织成环状结构域", "实现DNA进一步缩短和有序排列", "环状组织有助于染色质压缩，也可能通过拓扑结构影响基因可及性和表达调控", "是染色质高级结构的重要特征"], "check": {"q": "关于核小体DNA大环在DNA进一步压缩中的作用，下列描述正确的是？", "o": ["A. 大环以核骨架或核基质为锚点，将30 nm纤维组织成环状结构域", "B. 大环结构仅参与压缩，不影响基因表达调控", "C. 大环结构使DNA完全解压缩", "D. 大环结构由DNA复制直接形成，与核骨架无关"], "a": "A", "e": "核小体DNA形成大环，以核骨架或核基质为锚点，将30 nm纤维组织成环状结构域，实现进一步压缩，并可能影响基因可及性和表达调控。"}, "cards": [{"front": "什么是核骨架模型？它解释了什么层次的染色质压缩？", "back": "核骨架模型认为染色质通过大量核小体DNA形成的环状结构锚定在核骨架上，实现30 nm纤维以上的更高层次压缩（再压缩约10³–10⁴倍），形成有序三维组织并参与基因表达调控。", "mnemonic": "环锚骨架，高级压缩", "useImg": false}]}, {"i": 6, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "组蛋白 N 端尾部的修饰 (p100)", "notes": "组蛋白 N 端尾部从核小体核心伸出，可发生多种翻译后修饰，包括乙酰化、甲基化、磷酸化、泛素化等。这些修饰是表观遗传调控的重要方式，能够改变染色质结构或招募特定蛋白，从而影响基因表达。组蛋白尾部修饰不改变 DNA 序列，但可遗传给子代细胞，是表观遗传信息的重要载体。", "page": 100, "level": "掌握", "img": "assets/img/ch02/p100.jpg", "anim": null, "fig": null, "points": ["组蛋白N端尾部从核小体核心伸出，可发生多种翻译后修饰", "修饰类型包括乙酰化、甲基化、磷酸化、泛素化等", "这些修饰是表观遗传调控的重要方式，可改变染色质结构或招募特定蛋白", "组蛋白尾部修饰不改变DNA序列，但可遗传给子代细胞", "是表观遗传信息的重要载体"], "check": {"q": "关于组蛋白N端尾部修饰，下列叙述正确的是？", "o": ["A. 组蛋白尾部修饰会改变DNA序列", "B. 组蛋白尾部修饰包括乙酰化、甲基化、磷酸化、泛素化等，是表观遗传调控的重要方式", "C. 组蛋白尾部修饰不能遗传给子代细胞", "D. 组蛋白尾部修饰仅影响染色质结构，不招募特定蛋白"], "a": "B", "e": "组蛋白N端尾部可发生乙酰化、甲基化、磷酸化、泛素化等多种翻译后修饰，是表观遗传调控的重要方式，不改变DNA序列但可遗传。"}, "cards": [{"front": "核小体 DNA 大环在染色质压缩中有什么作用？", "back": "核小体DNA形成大环，以核骨架或核基质为锚点，将30 nm纤维组织成环状结构域，实现DNA进一步缩短和有序排列，并通过环的拓扑结构影响基因可及性和表达调控。", "mnemonic": "大环锚定，压缩又调控", "useImg": false}]}, {"i": 7, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "组蛋白修饰作为表观遗传标记 (p101)", "notes": "组蛋白翻译后修饰是一类重要的表观遗传标记。表观遗传修饰是指在不改变 DNA 碱基序列的情况下，通过化学修饰或染色质结构变化，改变基因是否容易被表达。组蛋白修饰可以影响染色质的开放程度，决定转录因子和其他调控蛋白能否接近 DNA，从而调控基因表达。这种调控方式在发育、细胞分化、疾病发生等过程中具有关键作用。", "page": 101, "level": "掌握", "img": "assets/img/ch02/p101.jpg", "anim": null, "fig": null, "points": ["组蛋白翻译后修饰是一类重要的表观遗传标记", "表观遗传修饰不改变DNA碱基序列，通过化学修饰或染色质结构变化改变基因表达难易", "组蛋白修饰影响染色质开放程度，决定转录因子和调控蛋白能否接近DNA", "从而调控基因表达", "在发育、细胞分化、疾病发生等过程中具有关键作用"], "check": {"q": "关于组蛋白翻译后修饰作为表观遗传标记，下列说法正确的是：", "o": ["A. 它通过改变DNA碱基序列来调控基因表达", "B. 它可影响染色质开放程度，从而影响转录因子接近DNA", "C. 它仅参与细胞分裂，与发育和疾病无关", "D. 它只决定DNA复制起点，不参与基因表达调控"], "a": "B", "e": "组蛋白修饰不改变DNA碱基序列，而是通过影响染色质开放程度，决定转录因子等能否接近DNA，从而调控基因表达，并在发育、细胞分化和疾病中起关键作用。"}, "cards": [{"front": "组蛋白 N 端尾部可发生哪些翻译后修饰？其意义是什么？", "back": "可发生乙酰化、甲基化、磷酸化、泛素化等修饰。这些修饰是表观遗传调控的重要方式，能改变染色质结构或招募特定蛋白，影响基因表达，且不改变DNA序列但可遗传给子代。", "mnemonic": "乙甲磷泛，表观遗传", "useImg": false}]}, {"i": 8, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "组蛋白修饰的写入、阅读与擦除 (p102)", "notes": "组蛋白修饰由三类功能蛋白协同调控：写入器（Writers）是添加修饰标记的酶，如组蛋白乙酰转移酶和甲基转移酶；阅读器（Readers）是识别并结合修饰标记的蛋白，将修饰信息转化为下游功能；擦除器（Erasers）是去除修饰标记的酶，如去乙酰化酶和去甲基化酶。这种动态调控使组蛋白修饰能够灵活响应细胞信号，精确控制基因表达。", "page": 102, "level": "掌握", "img": "assets/img/ch02/p102.jpg", "anim": null, "fig": null, "points": ["组蛋白修饰由写入器、阅读器和擦除器三类功能蛋白协同调控", "写入器是添加修饰标记的酶，如组蛋白乙酰转移酶和甲基转移酶", "阅读器识别并结合修饰标记，将修饰信息转化为下游功能", "擦除器是去除修饰标记的酶，如去乙酰化酶和去甲基化酶", "动态调控使组蛋白修饰能灵活响应细胞信号，精确控制基因表达"], "check": {"q": "在组蛋白修饰的动态调控中，负责识别并结合修饰标记、将修饰信息转化为下游功能的蛋白称为：", "o": ["A. 写入器（Writers）", "B. 阅读器（Readers）", "C. 擦除器（Erasers）", "D. 解旋酶（Helicases）"], "a": "B", "e": "阅读器识别并结合组蛋白修饰标记，把修饰信息转化为下游功能；写入器添加修饰，擦除器去除修饰。"}, "cards": [{"front": "什么是表观遗传修饰？组蛋白修饰如何参与其中？", "back": "表观遗传修饰指不改变DNA碱基序列，通过化学修饰或染色质结构变化改变基因是否容易表达。组蛋白修饰可影响染色质开放程度，决定转录因子能否接近DNA，从而调控基因表达，在发育、分化、疾病中起关键作用。", "mnemonic": "不改序列改包装，开合决定表达", "useImg": false}]}, {"i": 9, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "蛋白结构域识别修饰组蛋白（阅读器） (p103)", "notes": "阅读器蛋白通过特定的蛋白结构域识别修饰后的组蛋白。例如，溴结构域（bromodomain）识别乙酰化赖氨酸，染色质结构域（chromodomain）和 PHD 指结构域识别甲基化赖氨酸，14-3-3 蛋白识别磷酸化丝氨酸等。这些结构域与修饰标记的特异性结合，将组蛋白修饰信息转化为蛋白质复合物的招募和功能执行，是组蛋白密码解读的关键环节。", "page": 103, "level": "理解", "img": "assets/img/ch02/p103.jpg", "anim": null, "fig": null, "points": ["阅读器蛋白通过特定蛋白结构域识别修饰后的组蛋白", "溴结构域识别乙酰化赖氨酸", "染色质结构域和PHD指结构域识别甲基化赖氨酸", "14-3-3蛋白识别磷酸化丝氨酸等", "结构域与修饰标记特异性结合，将组蛋白修饰信息转化为蛋白复合物招募和功能执行，是组蛋白密码解读的关键环节"], "check": {"q": "下列蛋白结构域与其识别的组蛋白修饰配对正确的是：", "o": ["A. 溴结构域识别甲基化赖氨酸", "B. 染色质结构域识别乙酰化赖氨酸", "C. PHD指结构域识别甲基化赖氨酸", "D. 14-3-3蛋白识别乙酰化赖氨酸"], "a": "C", "e": "溴结构域识别乙酰化赖氨酸，染色质结构域和PHD指结构域识别甲基化赖氨酸，14-3-3蛋白识别磷酸化丝氨酸。"}, "cards": [{"front": "组蛋白修饰的写入器、阅读器和擦除器分别是什么？", "back": "写入器（Writers）：添加修饰标记的酶，如组蛋白乙酰转移酶和甲基转移酶；阅读器（Readers）：识别并结合修饰标记的蛋白，将修饰信息转化为下游功能；擦除器（Erasers）：去除修饰标记的酶，如去乙酰化酶和去甲基化酶。", "mnemonic": "写加读传擦去除", "useImg": false}]}, {"i": 10, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "组蛋白密码假说与染色质压缩调控 (p104)", "notes": "组蛋白修饰可通过电荷-电荷相互作用调节染色质压缩，例如乙酰化中和赖氨酸正电荷，减弱组蛋白与 DNA 的相互作用，使染色质松散。Allis 和 Strahl 提出的组蛋白密码假说认为，多种组蛋白修饰以组合或顺序方式作用于一个或多个组蛋白尾部，指定独特的下游功能。该假说强调修饰的组合性和上下文依赖性，为理解表观遗传调控提供了重要框架。", "page": 104, "level": "掌握", "img": "assets/img/ch02/p104.jpg", "anim": null, "fig": null, "points": ["组蛋白修饰可通过电荷-电荷相互作用调节染色质压缩", "乙酰化中和赖氨酸正电荷，减弱组蛋白与DNA相互作用，使染色质松散", "Allis和Strahl提出组蛋白密码假说", "假说认为多种组蛋白修饰以组合或顺序方式作用于一个或多个组蛋白尾部，指定独特下游功能", "强调修饰的组合性和上下文依赖性，为理解表观遗传调控提供重要框架"], "check": {"q": "关于组蛋白密码假说，下列描述正确的是：", "o": ["A. 认为单一组蛋白修饰即可独立决定全部下游功能", "B. 强调多种组蛋白修饰以组合或顺序方式指定独特功能", "C. 认为组蛋白修饰通过改变DNA碱基序列发挥作用", "D. 认为乙酰化会增强组蛋白与DNA的相互作用"], "a": "B", "e": "Allis和Strahl提出的组蛋白密码假说认为，多种组蛋白修饰以组合或顺序方式作用于组蛋白尾部，指定独特的下游功能，并强调组合性和上下文依赖性。"}, "cards": [{"front": "阅读器蛋白通过哪些结构域识别修饰组蛋白？", "back": "溴结构域（bromodomain）识别乙酰化赖氨酸；染色质结构域（chromodomain）和PHD指结构域识别甲基化赖氨酸；14-3-3蛋白识别磷酸化丝氨酸等。这些特异性结合将组蛋白修饰信息转化为蛋白复合物的招募和功能执行。", "mnemonic": "溴认乙酰，染色质/PHD认甲基，14-3-3认磷酸", "useImg": false}]}, {"i": 11, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "组蛋白乙酰化使染色质松散并暴露 DNA 位点 (p105)", "notes": "组蛋白乙酰化中和赖氨酸残基的正电荷，降低组蛋白与 DNA 的亲和力，使染色质结构变得松散。同时，核小体重塑复合物可移动核小体，进一步改变核小体位置。这些变化使原先被遮挡的 DNA 位点暴露出来，允许新的调控蛋白结合，从而激活或抑制转录。该过程展示了组蛋白修饰与核小体重塑协同调控基因表达可及性的机制。", "page": 105, "level": "掌握", "img": "assets/img/ch02/p105.jpg", "anim": null, "fig": null, "points": ["组蛋白乙酰化中和赖氨酸残基正电荷，降低组蛋白与DNA亲和力，使染色质松散", "核小体重塑复合物可移动核小体，进一步改变核小体位置", "这些变化使原先被遮挡的DNA位点暴露出来", "允许新的调控蛋白结合，从而激活或抑制转录", "展示组蛋白修饰与核小体重塑协同调控基因表达可及性的机制"], "check": {"q": "组蛋白乙酰化使染色质松散并暴露DNA位点，其主要机制是：", "o": ["A. 乙酰化增加赖氨酸正电荷，增强组蛋白与DNA结合", "B. 乙酰化中和赖氨酸正电荷，降低组蛋白与DNA亲和力", "C. 乙酰化直接切除核小体，使DNA完全裸露", "D. 乙酰化改变DNA碱基序列，产生新的调控位点"], "a": "B", "e": "乙酰化中和赖氨酸残基的正电荷，降低组蛋白与DNA的亲和力，使染色质松散；核小体重塑复合物还可移动核小体，暴露DNA位点。"}, "cards": [{"front": "什么是组蛋白密码假说？乙酰化如何影响染色质压缩？", "back": "Allis和Strahl提出的组蛋白密码假说认为，多种组蛋白修饰以组合或顺序方式作用于组蛋白尾部，指定独特的下游功能，强调组合性和上下文依赖性。乙酰化中和赖氨酸正电荷，减弱组蛋白与DNA的相互作用，使染色质松散。", "mnemonic": "组合修饰=密码；乙酰中和电荷=松散", "useImg": false}]}, {"i": 12, "sec": "模块八：组蛋白变体、高级结构与组蛋白修饰", "title": "本章结束 (p106)", "notes": "本页为第二章“染色体与 DNA”的结束页，总结本章内容：染色体由 DNA 和组蛋白等组成，通过核小体、30 nm 纤维、环状结构域等层级实现高度压缩；组蛋白变体和翻译后修饰构成表观遗传调控的重要机制，影响染色质结构和基因表达。这些知识为理解 DNA 复制、转录、修复等过程奠定基础。", "page": 106, "level": "了解", "img": "assets/img/ch02/p106.jpg", "anim": null, "fig": null, "points": ["本页为第二章“染色体与DNA”的结束页", "染色体由DNA和组蛋白等组成，通过核小体、30 nm纤维、环状结构域等层级实现高度压缩", "组蛋白变体和翻译后修饰构成表观遗传调控的重要机制", "影响染色质结构和基因表达", "为理解DNA复制、转录、修复等过程奠定基础"], "check": {"q": "根据本章结束页的总结，下列哪项正确概括了本章关于染色体与DNA的核心内容？", "o": ["A. 染色体仅由DNA组成，不涉及组蛋白和高级结构", "B. 染色体通过核小体、30 nm纤维、环状结构域等层级实现高度压缩，组蛋白变体和修饰参与表观遗传调控", "C. 组蛋白变体和翻译后修饰会改变DNA碱基序列，从而影响基因表达", "D. 本章内容仅解释DNA复制，不涉及转录和修复"], "a": "B", "e": "本章总结指出，染色体由DNA和组蛋白等组成，通过核小体、30 nm纤维、环状结构域等层级高度压缩；组蛋白变体和翻译后修饰构成表观遗传调控的重要机制，并为理解DNA复制、转录、修复奠定基础。"}, "cards": [{"front": "组蛋白乙酰化如何使染色质松散并暴露 DNA 位点？", "back": "乙酰化中和赖氨酸残基的正电荷，降低组蛋白与DNA的亲和力，使染色质结构松散；同时核小体重塑复合物可移动核小体，进一步改变位置，使原先被遮挡的DNA位点暴露，允许新的调控蛋白结合，从而调控转录。", "mnemonic": "乙酰松绑，重塑挪位，暴露位点", "useImg": false}]}], "mcq": [{"id": "ch02_mcq_35", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "下列哪种组蛋白变体在 DNA 双链断裂后被磷酸化形成 γ-H2A.X，并参与 DNA 损伤修复？", "o": ["A. H2A.Z", "B. H2A.X", "C. macroH2A", "D. CENP-A"], "a": "B", "e": "H2A.X 在 DNA 双链断裂后被磷酸化形成 γ-H2A.X，作为 DNA 损伤标记参与修复。H2A.Z 参与转录调控，macroH2A 参与染色质沉默，CENP-A 位于着丝粒。", "kp": "ch02_s7_0"}, {"id": "ch02_mcq_36", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "关于组蛋白密码假说，下列描述正确的是？", "o": ["A. 一种组蛋白修饰只对应一种下游功能", "B. 多种组蛋白修饰以组合或顺序方式指定独特的下游功能", "C. 组蛋白修饰通过改变 DNA 碱基序列来调控基因表达", "D. 组蛋白修饰仅发生在组蛋白球状结构域"], "a": "B", "e": "组蛋白密码假说认为多种组蛋白修饰以组合或顺序方式作用于一个或多个组蛋白尾部，指定独特的下游功能。组蛋白修饰不改变 DNA 序列，且主要发生在 N 端尾部。", "kp": "ch02_s7_10"}, {"id": "ch02_mcq_37", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "在组蛋白修饰调控中，负责添加修饰标记的酶被称为？", "o": ["A. Reader", "B. Eraser", "C. Writer", "D. Remodeler"], "a": "C", "e": "Writer（写入器）是添加修饰标记的酶，Reader（阅读器）识别修饰，Eraser（擦除器）去除修饰，Remodeler 是核小体重塑复合物。", "kp": "ch02_s7_8"}, {"id": "ch02_mcq_38", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "H1 组蛋白在染色质高级结构中的主要作用是？", "o": ["A. 形成核小体核心颗粒", "B. 促进 30 nm 纤维形成", "C. 识别组蛋白乙酰化修饰", "D. 参与 DNA 双链断裂修复"], "a": "B", "e": "H1 是连接组蛋白，结合连接 DNA，促进核小体阵列折叠成 30 nm 染色质纤维。核小体核心由 H2A、H2B、H3、H4 组成。", "kp": "ch02_s7_10"}, {"id": "ch02_mcq_39", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "组蛋白乙酰化使染色质松散的主要机制是？", "o": ["A. 增加组蛋白正电荷，增强与 DNA 结合", "B. 中和赖氨酸正电荷，减弱组蛋白与 DNA 的相互作用", "C. 直接降解组蛋白", "D. 改变 DNA 碱基序列"], "a": "B", "e": "乙酰化中和赖氨酸残基的正电荷，降低组蛋白与 DNA 的亲和力，使染色质结构松散，有利于调控蛋白结合。", "kp": "ch02_s7_11"}], "judge": [], "fill": [], "short": [], "calc": [], "term": []}], "mcq": [{"id": "ch02_mcq_1", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "根据现代分子生物学定义，基因是指：", "o": ["A. 一段能编码蛋白质的DNA序列", "B. 合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列", "C. 染色体上能被染色的区域", "D. 生物体内全部DNA的总和"], "a": "B", "e": "基因的现代定义强调其最终功能产物可以是有功能的多肽或RNA分子，因此编码RNA的序列也属于基因；A只涵盖编码蛋白质的基因，D描述的是基因组。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_2", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "关于染色质与染色体的关系，正确的是：", "o": ["A. 染色质和染色体是两种不同的遗传物质", "B. 染色质只存在于原核细胞，染色体只存在于真核细胞", "C. 染色质和染色体是同一物质在细胞周期不同阶段的不同存在形式", "D. 染色体由RNA和蛋白质组成，染色质由DNA和蛋白质组成"], "a": "C", "e": "真核细胞中，DNA与组蛋白等结合形成染色质，分裂期高度折叠压缩形成染色体，二者化学本质相同，只是形态和包装程度不同。", "kp": "ch02_s0_2"}, {"id": "ch02_mcq_3", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "下列哪项不是基因最终功能产物的可能形式？", "o": ["A. 具有催化功能的RNA", "B. 具有调控功能的RNA", "C. 具有结构功能的多肽", "D. 直接作为遗传密码的脱氧核糖"], "a": "D", "e": "基因的功能产物可以是有功能的多肽或RNA分子；脱氧核糖是DNA的组成成分，不是基因表达的功能产物。", "kp": "ch02_s0_1"}, {"id": "ch02_mcq_4", "mod": "模块一：染色质、染色体与基因的概念", "modI": 0, "q": "“核酸”这一术语的正确含义是：", "o": ["A. 仅指DNA", "B. 仅指RNA", "C. DNA和RNA的总称", "D. 指所有含氮碱基"], "a": "C", "e": "核酸是脱氧核糖核酸（DNA）和核糖核酸（RNA）的总称，DNA和RNA都是核酸的具体类型。", "kp": "ch02_s0_2"}, {"id": "ch02_mcq_5", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "DNA双螺旋中，碱基对之间的主要作用力是：", "o": ["A. 磷酸二酯键", "B. 氢键", "C. 肽键", "D. 糖苷键"], "a": "B", "e": "碱基对之间通过氢键连接，A-T形成两个氢键，G-C形成三个氢键；磷酸二酯键连接同一链内相邻核苷酸，糖苷键连接碱基与戊糖。", "kp": "ch02_s1_7"}, {"id": "ch02_mcq_6", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "下列关于DNA与RNA核苷酸差异的叙述，正确的是：", "o": ["A. DNA含核糖，RNA含脱氧核糖", "B. DNA含尿嘧啶，RNA含胸腺嘧啶", "C. DNA含脱氧核糖和胸腺嘧啶，RNA含核糖和尿嘧啶", "D. DNA和RNA的碱基组成完全相同"], "a": "C", "e": "DNA含脱氧核糖和胸腺嘧啶（T），RNA含核糖和尿嘧啶（U），这是两者在化学组成上的主要区别。", "kp": "ch02_s1_3"}, {"id": "ch02_mcq_7", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "生理水溶液条件下DNA的主要构象形式是：", "o": ["A. A-DNA", "B. B-DNA", "C. Z-DNA", "D. 三链DNA"], "a": "B", "e": "B-DNA是生理水溶液条件下的主要形式；A-DNA在低水合条件下有利，Z-DNA为左手螺旋，需特定序列和拓扑压力。", "kp": "ch02_s1_10"}, {"id": "ch02_mcq_8", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "维持DNA双螺旋稳定性的因素中，贡献最大的是：", "o": ["A. 碱基对之间的氢键", "B. 碱基堆积力", "C. 磷酸基团与阳离子形成的离子键", "D. 碱基的分子内能"], "a": "B", "e": "碱基堆积力包括疏水相互作用和范德华力，对双螺旋稳定性贡献最大；氢键主要保证配对特异性，离子键主要屏蔽磷酸骨架的静电排斥。", "kp": "ch02_s1_11"}, {"id": "ch02_mcq_9", "mod": "模块二：DNA的一级与二级结构", "modI": 1, "q": "DNA两条链反向平行的含义是：", "o": ["A. 两条链的碱基序列完全相同", "B. 一条链为5′→3′方向，另一条链为3′→5′方向", "C. 两条链均为左手螺旋", "D. 两条链通过磷酸二酯键相互连接"], "a": "B", "e": "反向平行指两条多核苷酸链方向相反：一条为5′→3′，另一条为3′→5′；两条链之间通过碱基氢键连接，而非磷酸二酯键。", "kp": "ch02_s1_6"}, {"id": "ch02_mcq_10", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "关于DNA超螺旋的描述，下列哪项是正确的？", "o": ["A. 正超螺旋有利于DNA解链", "B. 负超螺旋使DNA更加紧密，不利于解链", "C. 负超螺旋有利于DNA解链，促进复制和转录", "D. 超螺旋只存在于环状DNA中"], "a": "C", "e": "负超螺旋使DNA双链更容易解开，从而促进复制和转录。正超螺旋则使解链更困难。超螺旋也存在于线性DNA的拓扑约束区域。", "kp": "ch02_s2_2"}, {"id": "ch02_mcq_11", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "DNA的熔解温度（Tm）是指：", "o": ["A. DNA完全变性时的温度", "B. DNA两条链半解离时的温度", "C. DNA开始变性时的温度", "D. DNA复性一半时的温度"], "a": "B", "e": "Tm是DNA两条链半解离或变性的温度，即吸光值增加到最大值一半时的温度。", "kp": "ch02_s2_7"}, {"id": "ch02_mcq_12", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "下列哪种条件不利于DNA复性？", "o": ["A. 温度比Tm低约25℃", "B. 高DNA浓度", "C. 缓慢降温", "D. 高温（接近Tm）"], "a": "D", "e": "复性的最佳温度比Tm低约25℃，高温接近Tm会使DNA保持变性状态，不利于复性。", "kp": "ch02_s2_10"}, {"id": "ch02_mcq_13", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "关于DNA杂交，下列哪项描述是错误的？", "o": ["A. 杂交可以发生在DNA和RNA之间", "B. 杂交需要两条链完全互补", "C. 杂交是许多分子生物学技术的基础", "D. 杂交的严格性受温度和盐浓度影响"], "a": "B", "e": "杂交可以发生在互补或接近互补的序列之间，不需要完全互补。", "kp": "ch02_s2_10"}, {"id": "ch02_mcq_14", "mod": "模块三：DNA的三级结构（拓扑）与理化性质", "modI": 2, "q": "在DNA复制过程中，解旋酶解开双链会导致什么后果？", "o": ["A. 形成负超螺旋，促进解链", "B. 形成正超螺旋，阻碍解链", "C. 形成连锁，阻碍解链", "D. 形成纽结，促进解链"], "a": "B", "e": "解旋酶解开双链时，未解链部分缠绕更紧密，形成正超螺旋压力，阻碍解链继续进行，需要拓扑异构酶来释放张力。", "kp": "ch02_s2_4"}, {"id": "ch02_mcq_15", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "下列哪项属于细胞质基因？", "o": ["A. 染色体上的核基因", "B. 细菌质粒基因", "C. 核糖体RNA基因", "D. 组蛋白基因"], "a": "B", "e": "细胞质基因位于细胞核以外的细胞质中，如细菌质粒、线粒体基因和叶绿体基因。核基因位于染色体上，rRNA基因和组蛋白基因均属核基因。", "kp": "ch02_s3_1"}, {"id": "ch02_mcq_16", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "关于原核生物mRNA，下列说法正确的是：", "o": ["A. 通常为单顺反子mRNA", "B. 一个mRNA只能翻译成一条多肽链", "C. 通常为多顺反子mRNA，可翻译成多条多肽链", "D. 不经过转录直接翻译"], "a": "C", "e": "原核生物mRNA多为多顺反子mRNA，一个mRNA分子上携有几种多肽的氨基酸序列信息，能翻译成两条或多条多肽链。真核mRNA通常为单顺反子。", "kp": "ch02_s3_7"}, {"id": "ch02_mcq_17", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "真核生物断裂基因中，内含子的典型边界特征是：", "o": ["A. 5′端AG，3′端GT", "B. 5′端GT，3′端AG", "C. 5′端AT，3′端GC", "D. 5′端GC，3′端AT"], "a": "B", "e": "真核基因内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG，这是剪接体识别内含子的重要信号。", "kp": "ch02_s3_9"}, {"id": "ch02_mcq_18", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "关于重叠基因，下列描述错误的是：", "o": ["A. 两个或两个以上基因共用一段DNA顺序", "B. 可使有限的基因组携带更多遗传信息", "C. 在真核生物中极为普遍", "D. 有多种重叠方式，如大基因内包含小基因"], "a": "C", "e": "重叠基因指两个或两个以上基因共用一段DNA顺序，在原核生物和病毒中较常见，并非在真核生物中极为普遍。它可提高编码效率，有多种重叠方式。", "kp": "ch02_s3_8"}, {"id": "ch02_mcq_19", "mod": "模块四：基因的分类与结构", "modI": 3, "q": "按基因产物分类，tRNA基因属于：", "o": ["A. 蛋白编码基因", "B. 功能RNA基因", "C. 调节基因", "D. 结构基因"], "a": "B", "e": "tRNA基因转录后不翻译，直接以RNA形式发挥功能，属于功能RNA基因。蛋白编码基因包括结构基因和调节基因，最终产物为蛋白质。", "kp": "ch02_s3_3"}, {"id": "ch02_mcq_20", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "关于细菌核基因组的结构特点，下列哪项正确？", "o": ["A. 由多条线性染色体组成，有多个复制起点", "B. 由一条双链环状DNA组成，只有一个复制起点", "C. 由一条单链RNA组成，无复制起点", "D. 由质粒和组蛋白共同构成，有核膜包被"], "a": "B", "e": "细菌核基因组通常由一条双链环状DNA分子组成，只有一个复制起点，DNA在胞内形成类核，无核膜包被。", "kp": "ch02_s4_1"}, {"id": "ch02_mcq_21", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "细菌结构基因的典型特征是：", "o": ["A. 含有大量内含子，需要剪接", "B. 序列连续，无内含子", "C. 全部为多拷贝基因", "D. 不能组成操纵子"], "a": "B", "e": "细菌结构基因序列连续、无内含子；大多数结构基因组成操纵子，且编码蛋白质的基因多为单拷贝，但rRNA基因常为多拷贝。", "kp": "ch02_s4_3"}, {"id": "ch02_mcq_22", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "关于质粒的特性，下列描述错误的是：", "o": ["A. 质粒对宿主生存通常不是必需的", "B. 质粒可赋予宿主抗生素抗性等有利表型", "C. 质粒离开宿主后仍能独立完成复制和转录", "D. 质粒必须依赖宿主细胞的酶和蛋白质进行复制"], "a": "C", "e": "质粒离开宿主无法独立生存，必须依赖宿主细胞的酶和蛋白质才能完成自身复制和转录。", "kp": "ch02_s4_5"}, {"id": "ch02_mcq_23", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "质粒作为基因工程载体通常不需要具备下列哪一特点？", "o": ["A. 能独立自主复制", "B. 便于检测，如具有抗生素抗性", "C. 容易导入宿主细胞并易于分离纯化", "D. 必须含有完整的内含子剪接系统"], "a": "D", "e": "基因工程载体质粒通常要求能独立复制、便于检测、容易导入和分离纯化；内含子剪接系统不是细菌质粒载体的必备特点。", "kp": "ch02_s4_8"}, {"id": "ch02_mcq_24", "mod": "模块五：基因组——细菌基因组与质粒", "modI": 4, "q": "细菌基因组中编码rRNA的基因常为多拷贝，其主要原因是：", "o": ["A. 细菌需要大量核糖体以满足快速蛋白质合成", "B. rRNA基因必须通过转座才能表达", "C. rRNA基因含有内含子，需要多拷贝补偿", "D. 细菌基因组重复序列极少，所以rRNA不能多拷贝"], "a": "A", "e": "细菌生长繁殖快，对核糖体需求量大，多拷贝rRNA基因可保证rRNA高效转录，从而满足蛋白质合成需要。", "kp": "ch02_s4_3"}, {"id": "ch02_mcq_25", "mod": "模块六：真核生物基因组", "modI": 5, "q": "下列关于真核生物基因组特点的叙述，错误的是：", "o": ["A. 基因组庞大，与物种复杂性总体呈正相关", "B. 非编码区占90%以上，基因密度低", "C. 基因多为断裂基因，含有内含子和外显子", "D. 基因组中重复序列很少，且不编码蛋白质"], "a": "D", "e": "真核基因组含有大量重复序列，如卫星DNA和转座元件，它们大多不编码蛋白质，但会影响基因组大小、结构和表达调控，因此D错误。", "kp": "ch02_s5_7"}, {"id": "ch02_mcq_26", "mod": "模块六：真核生物基因组", "modI": 5, "q": "真核生物断裂基因中，在mRNA剪接过程中被切除的序列是：", "o": ["A. 外显子", "B. 内含子", "C. 启动子", "D. 增强子"], "a": "B", "e": "断裂基因由外显子和内含子组成，内含子在转录后剪接过程中被切除，外显子则连接形成成熟mRNA。", "kp": "ch02_s5_6"}, {"id": "ch02_mcq_27", "mod": "模块六：真核生物基因组", "modI": 5, "q": "关于转座元件的转座机制，下列叙述正确的是：", "o": ["A. “复制-粘贴”转座后原拷贝丢失，拷贝数不变", "B. “剪切-粘贴”转座后原拷贝保留，拷贝数增加", "C. “复制-粘贴”转座后原拷贝保留，拷贝数增加", "D. 两种机制均不改变基因组大小"], "a": "C", "e": "复制型转座即“复制-粘贴”，原拷贝保留并在新位点插入新拷贝，拷贝数增加；剪切型转座即“剪切-粘贴”，原位置丢失，拷贝数通常不增加。", "kp": "ch02_s5_5"}, {"id": "ch02_mcq_28", "mod": "模块六：真核生物基因组", "modI": 5, "q": "下列哪项不是真核生物基因组的主要特征？", "o": ["A. 含有大量重复序列", "B. 基因密度高，编码区占90%以上", "C. 存在断裂基因", "D. mRNA通常为单顺反子"], "a": "B", "e": "真核基因组非编码区占90%以上，基因密度低，编码区比例小，因此B不是真核基因组特征。", "kp": "ch02_s5_7"}, {"id": "ch02_mcq_29", "mod": "模块六：真核生物基因组", "modI": 5, "q": "大多数转座元件在真核基因组中不活跃“跳跃”的主要原因是：", "o": ["A. 它们全部被完全切除", "B. 突变积累或表观遗传机制使其沉默", "C. 它们只能存在于原核生物中", "D. 它们不参与基因组进化"], "a": "B", "e": "大多数转座子因突变积累或表观遗传机制（如DNA甲基化、组蛋白修饰）被沉默，只有少数仍具转座活性。", "kp": "ch02_s5_4"}, {"id": "ch02_mcq_30", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "下列关于核小体结构的描述，哪一项是正确的？", "o": ["A. 核小体由H1、H2A、H2B、H3和H4各两个分子组成八聚体", "B. 核小体核心颗粒由H3-H4四聚体和两个H2A-H2B二聚体组成，DNA缠绕约1.67圈", "C. 核小体中的DNA长度为200 bp，缠绕组蛋白八聚体两圈", "D. 组蛋白H1位于核小体核心颗粒中央，直接参与DNA缠绕"], "a": "B", "e": "核小体核心颗粒由H3-H4四聚体和两个H2A-H2B二聚体组成，DNA缠绕约1.67圈；H1为连接组蛋白，不参与八聚体核心；核心DNA约146 bp，加上连接DNA约200 bp。", "kp": "ch02_s6_23"}, {"id": "ch02_mcq_31", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "DNase I消化染色质实验得到150-200 bp倍数的梯状条带，这一结果说明什么？", "o": ["A. DNA被组蛋白保护，形成重复的核小体结构", "B. DNA被DNase I完全降解", "C. 染色质中不存在蛋白质", "D. DNA是环状结构"], "a": "A", "e": "DNase I部分消化后产生150-200 bp倍数的DNA片段，说明DNA被蛋白质保护，形成重复的核小体结构，这是核小体存在的经典证据。", "kp": "ch02_s6_14"}, {"id": "ch02_mcq_32", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "关于组蛋白的特性，下列哪项错误？", "o": ["A. 组蛋白在中性pH下带正电荷", "B. 组蛋白在不同物种间高度保守", "C. 组蛋白基因通常是单拷贝基因", "D. 组蛋白修饰多发生在N端"], "a": "C", "e": "组蛋白基因通常不是单拷贝，而是在基因组中重复多次，以满足大量组蛋白的需求；其他选项均正确。", "kp": "ch02_s6_17"}, {"id": "ch02_mcq_33", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "DNA包装的多级水平中，第二级结构是？", "o": ["A. 核小体", "B. 30 nm纤维（螺线管模型）", "C. 核骨架", "D. 中期染色体"], "a": "B", "e": "DNA包装一级为核小体，二级为30 nm纤维（螺线管模型），三级为核骨架，四级为有丝分裂中期染色体。", "kp": "ch02_s6_11"}, {"id": "ch02_mcq_34", "mod": "模块七：染色体与DNA包装（核小体）", "modI": 6, "q": "关于原核生物染色体结构，下列描述正确的是？", "o": ["A. 大肠杆菌染色体完全由蛋白质组成", "B. 大肠杆菌染色体外围部分为双链DNA超螺旋，形成约100个独立的拓扑结构域", "C. 原核生物染色体为线状", "D. 原核生物染色体没有DNA环"], "a": "B", "e": "大肠杆菌染色体中央部分（约20%）由RNA和核心蛋白组成，外围部分（约80%）为双链DNA超螺旋，扭结成约100个DNA环，每个环是一个相对独立的拓扑结构域。", "kp": "ch02_s6_7"}, {"id": "ch02_mcq_35", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "下列哪种组蛋白变体在 DNA 双链断裂后被磷酸化形成 γ-H2A.X，并参与 DNA 损伤修复？", "o": ["A. H2A.Z", "B. H2A.X", "C. macroH2A", "D. CENP-A"], "a": "B", "e": "H2A.X 在 DNA 双链断裂后被磷酸化形成 γ-H2A.X，作为 DNA 损伤标记参与修复。H2A.Z 参与转录调控，macroH2A 参与染色质沉默，CENP-A 位于着丝粒。", "kp": "ch02_s7_0"}, {"id": "ch02_mcq_36", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "关于组蛋白密码假说，下列描述正确的是？", "o": ["A. 一种组蛋白修饰只对应一种下游功能", "B. 多种组蛋白修饰以组合或顺序方式指定独特的下游功能", "C. 组蛋白修饰通过改变 DNA 碱基序列来调控基因表达", "D. 组蛋白修饰仅发生在组蛋白球状结构域"], "a": "B", "e": "组蛋白密码假说认为多种组蛋白修饰以组合或顺序方式作用于一个或多个组蛋白尾部，指定独特的下游功能。组蛋白修饰不改变 DNA 序列，且主要发生在 N 端尾部。", "kp": "ch02_s7_10"}, {"id": "ch02_mcq_37", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "在组蛋白修饰调控中，负责添加修饰标记的酶被称为？", "o": ["A. Reader", "B. Eraser", "C. Writer", "D. Remodeler"], "a": "C", "e": "Writer（写入器）是添加修饰标记的酶，Reader（阅读器）识别修饰，Eraser（擦除器）去除修饰，Remodeler 是核小体重塑复合物。", "kp": "ch02_s7_8"}, {"id": "ch02_mcq_38", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "H1 组蛋白在染色质高级结构中的主要作用是？", "o": ["A. 形成核小体核心颗粒", "B. 促进 30 nm 纤维形成", "C. 识别组蛋白乙酰化修饰", "D. 参与 DNA 双链断裂修复"], "a": "B", "e": "H1 是连接组蛋白，结合连接 DNA，促进核小体阵列折叠成 30 nm 染色质纤维。核小体核心由 H2A、H2B、H3、H4 组成。", "kp": "ch02_s7_10"}, {"id": "ch02_mcq_39", "mod": "模块八：组蛋白变体、高级结构与组蛋白修饰", "modI": 7, "q": "组蛋白乙酰化使染色质松散的主要机制是？", "o": ["A. 增加组蛋白正电荷，增强与 DNA 结合", "B. 中和赖氨酸正电荷，减弱组蛋白与 DNA 的相互作用", "C. 直接降解组蛋白", "D. 改变 DNA 碱基序列"], "a": "B", "e": "乙酰化中和赖氨酸残基的正电荷，降低组蛋白与 DNA 的亲和力，使染色质结构松散，有利于调控蛋白结合。", "kp": "ch02_s7_11"}], "judge": [{"id": "ch02_judge_1", "modI": 0, "q": "基因是合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列。", "a": "对", "e": "这是现代分子生物学对基因的定义，强调基因是功能单位，最终产物可为多肽或RNA。", "kp": "ch02_s0_1"}, {"id": "ch02_judge_2", "modI": 0, "q": "染色质与染色体是两种完全不同的物质。", "a": "错", "e": "染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式：间期多为伸展的染色质，分裂期则凝缩为染色体，二者均以DNA为基本遗传物质。", "kp": "ch02_s0_2"}, {"id": "ch02_judge_3", "modI": 1, "q": "RNA用尿嘧啶（U）替代DNA中的胸腺嘧啶（T），U与A同样能配对。", "a": "对", "e": "RNA含核糖（2′-OH），DNA含脱氧核糖；RNA用U替代T，U与A同样能配对，但T比U多一个甲基，有利于DNA的稳定性和修复识别。", "kp": "ch02_s1_3"}, {"id": "ch02_judge_4", "modI": 1, "q": "DNA双螺旋中，磷酸-脱氧核糖骨架位于内侧，碱基对位于外侧。", "a": "错", "e": "DNA双螺旋中，磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧，形成大沟和小沟。", "kp": "ch02_s1_7"}, {"id": "ch02_judge_5", "modI": 2, "q": "碱基堆积力对双螺旋稳定性贡献最大，氢键保证配对特异性。", "a": "对", "e": "维持双螺旋稳定的因素中，碱基堆积力对双螺旋稳定性贡献最大，氢键保证配对特异性，离子键维持骨架电荷平衡。", "kp": "ch02_s2_6"}, {"id": "ch02_judge_6", "modI": 2, "q": "DNA变性过程中，氢键断裂，碱基堆积力被破坏，共价键也断裂。", "a": "错", "e": "DNA变性过程中，氢键断裂，碱基堆积力被破坏，但共价键不受影响。", "kp": "ch02_s2_6"}, {"id": "ch02_judge_7", "modI": 3, "q": "原核生物mRNA多为单顺反子mRNA，真核生物mRNA通常为多顺反子mRNA。", "a": "错", "e": "原核生物mRNA多为多顺反子mRNA，即一个mRNA分子上携有几种多肽分子的氨基酸序列信息；真核生物mRNA通常为单顺反子mRNA，一个mRNA分子上只携有一种多肽分子的氨基酸序列信息。", "kp": "ch02_s3_7"}, {"id": "ch02_judge_8", "modI": 3, "q": "重叠基因指两个或两个以上的基因共用一段DNA顺序的现象，在原核生物和病毒中较为常见。", "a": "对", "e": "重叠基因可使有限的基因组携带更多遗传信息，提高编码效率，典型例子如噬菌体ΦX174的基因组。", "kp": "ch02_s3_8"}, {"id": "ch02_judge_9", "modI": 4, "q": "细菌核基因组一般由一条双链环状DNA分子组成，有多个复制起点。", "a": "错", "e": "细菌核基因组一般由一条双链环状DNA分子组成，只有一个复制起点，保证整个基因组从一个位点起始复制。", "kp": "ch02_s4_1"}, {"id": "ch02_judge_10", "modI": 4, "q": "质粒对宿主生存并非必需，但离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录。", "a": "对", "e": "质粒像“借居者”一样存在于宿主细胞中，通常不杀伤细胞，也不明显影响宿主代谢，宿主失去质粒仍可生存，但质粒离开宿主不能独立生存。", "kp": "ch02_s4_6"}], "fill": [{"id": "ch02_fill_1", "modI": 0, "q": "1909年，Johannsen提出“________”一词，用以指代决定遗传性状的“遗传因子”。", "a": "基因", "kp": "ch02_s0_1"}, {"id": "ch02_fill_2", "modI": 1, "q": "DNA含四种碱基：嘌呤类的腺嘌呤（A）和鸟嘌呤（G），嘧啶类的胞嘧啶（C）和________（T）。", "a": "胸腺嘧啶", "kp": "ch02_s1_2"}, {"id": "ch02_fill_3", "modI": 1, "q": "DNA多核苷酸链中，相邻核苷酸通过________相连（一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键）。", "a": "磷酸二酯键", "kp": "ch02_s1_5"}, {"id": "ch02_fill_4", "modI": 1, "q": "DNA双螺旋中，A与T形成________个氢键，G与C形成________个氢键。", "a": "2,3", "kp": "ch02_s1_7"}, {"id": "ch02_fill_5", "modI": 2, "q": "DNA变性后，紫外吸收（260 nm）增加，称为________效应。", "a": "增色", "kp": "ch02_s2_6"}, {"id": "ch02_fill_6", "modI": 2, "q": "DNA的熔解温度（Tm）是两条链半解离或变性的温度，即吸光值增加到最大值的一半时的温度。Tm值与________含量正相关。", "a": "GC", "kp": "ch02_s2_7"}, {"id": "ch02_fill_7", "modI": 3, "q": "原核生物mRNA多为________mRNA，即一个mRNA分子上携有几种多肽分子的氨基酸序列信息。", "a": "多顺反子", "kp": "ch02_s3_7"}, {"id": "ch02_fill_8", "modI": 3, "q": "真核生物基因多为断裂结构，由________和________交替组成。", "a": "外显子,内含子", "kp": "ch02_s3_9"}, {"id": "ch02_fill_9", "modI": 4, "q": "细菌核基因组一般由一条双链环状DNA分子组成，只有________个复制起点。", "a": "一", "kp": "ch02_s4_1"}, {"id": "ch02_fill_10", "modI": 4, "q": "质粒作为基因工程载体应具备三个特点：能独立自主复制、便于________（如抗生素抗性）、容易________并分离纯化。", "a": "检测,导入宿主细胞", "kp": "ch02_s4_8"}], "short": [{"id": "ch02_short_1", "modI": 0, "q": "简述基因的现代分子生物学定义及其功能产物类型。", "a": "定义：合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。功能产物类型：①若最终产物是多肽，基因信息需经转录和翻译表达为蛋白质，再体现生理功能；②若最终产物是RNA，则该RNA本身即具结构、催化、识别或调控等功能，无需翻译。该定义强调基因是“功能单位”，而非仅是一段可读框。", "kp": "ch02_s0_1"}, {"id": "ch02_short_2", "modI": 1, "q": "简述DNA双螺旋结构的主要特征。", "a": "①两条反向平行的多核苷酸链围绕同一中心轴盘绕形成双螺旋；②磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧；③形成大沟和小沟；④双螺旋直径约2 nm；⑤B-DNA每圈约10个碱基对，螺距约3.4 nm；⑥碱基互补配对：A与T形成两个氢键，G与C形成三个氢键；⑦这种结构既稳定又便于碱基序列被读取。", "kp": "ch02_s1_7"}, {"id": "ch02_short_3", "modI": 2, "q": "简述维持DNA双螺旋稳定的因素。", "a": "①碱基对之间的氢键：保证配对特异性；②碱基堆积力：包括碱基疏水相互作用和范德华力，对双螺旋稳定性贡献最大；③磷酸基团负电荷与介质中阳离子形成的离子键：可屏蔽静电排斥，维持骨架电荷平衡；④碱基的分子内能。这些因素共同决定DNA的稳定性与解链行为。", "kp": "ch02_s2_2"}, {"id": "ch02_short_4", "modI": 3, "q": "简述原核基因结构的主要特征。", "a": "①操纵子模型：一个转录单位可能包括多个开放阅读框，多个结构基因共用一个启动子和终止子；②转录成一条多顺反子mRNA；③操纵子中的基因通常功能相关，便于协同调控；④结构基因序列通常是连续的，没有内含子，转录后一般不需要剪接；⑤基因组中重复序列很少，编码蛋白质的结构基因多为单拷贝，但rRNA基因往往是多拷贝；⑥存在重叠基因现象；⑦具有转座现象。", "kp": "ch02_s3_6"}, {"id": "ch02_short_5", "modI": 4, "q": "简述质粒的定义、特点及其作为基因工程载体的条件。", "a": "定义：质粒是独立于染色体外、能自主复制的核酸分子，细菌质粒大多是环状双链DNA。特点：①对宿主生存并非必需；②离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录；③可赋予宿主有利表型，如抗生素抗性；④在结构上主要有超螺旋环状双链DNA、带缺口的环状DNA以及线性DNA三种状态。作为基因工程载体的条件：①能独立自主复制；②便于导入宿主细胞；③具有选择标记。", "kp": "ch02_s4_8"}], "calc": [{"id": "ch02_calc_1", "modI": 2, "q": "论述DNA复制过程中拓扑压力的产生及拓扑异构酶的作用机制。", "a": "在DNA复制过程中，解旋酶解开双链，未解链部分的缠绕更加紧密，形成正超螺旋压力。这种压力使解链不能继续进行，因此需要拓扑异构酶来释放这种张力。拓扑异构酶I切割一条链并旋转，拓扑异构酶II切割两条链并传递另一条双链通过，从而改变连环数。这一机制保证了复制叉的顺利推进。此外，细胞内的DNA通常处于负超螺旋状态，这有利于解链过程；在真核生物中，核小体的形成引入负超螺旋，帮助DNA压缩；拓扑异构酶可以松弛超螺旋DNA，通过暂时切断DNA链来改变拓扑状态，维持DNA的适当拓扑状态。", "steps": "①解旋酶解开双链产生正超螺旋压力；②正超螺旋压力阻碍解链；③拓扑异构酶I切割一条链并旋转；④拓扑异构酶II切割两条链并传递另一条双链通过；⑤改变连环数，释放张力；⑥保证复制叉顺利推进；⑦负超螺旋有利于解链，核小体引入负超螺旋；⑧拓扑异构酶维持适当拓扑状态。", "kp": "ch02_s2_4"}, {"id": "ch02_calc_2", "modI": 3, "q": "论述真核生物基因断裂结构的特征、分布及其进化意义。", "a": "真核生物基因多为断裂结构，由外显子和内含子交替组成。外显子是编码序列，最终出现在成熟RNA产物中；内含子是非编码序列，通常不编码蛋白质，在转录后经剪接被去除。内含子边界常遵循GT-AG规则，即5′端为GT，3′端为AG。大多数高等真核基因被非编码DNA中断。断裂结构使真核基因可通过可变剪接产生多种mRNA和蛋白质，极大扩展了遗传信息容量，是真核基因表达调控和蛋白质多样性的重要基础。分布：断裂基因在细菌和噬菌体中也有发现，但极为罕见；酵母中绝大多数基因（>96%）不是断裂基因，平均长约1.4 kb，很少超过5 kb；哺乳动物中仅约6%的基因编码序列不被中断，约50%的基因含10个以上内含子，许多基因长度在5 kb至100 kb之间。进化意义：不同物种相关基因比较表明，外显子序列通常保守，而内含子进化快得多，原因可能是内含子缺乏产生有用蛋白质序列的选择压力。这揭示了断裂基因在真核基因组中的普遍性及其进化意义。", "steps": "①真核基因由外显子和内含子交替组成；②外显子编码，内含子非编码；③内含子边界常遵循GT-AG规则；④可变剪接产生多种mRNA和蛋白质；⑤扩展遗传信息容量；⑥断裂基因在细菌和噬菌体中罕见；⑦酵母中>96%基因不是断裂基因；⑧哺乳动物中仅约6%基因编码序列不被中断；⑨外显子保守，内含子进化快；⑩内含子缺乏选择压力。", "kp": "ch02_s3_9"}], "term": [{"id": "ch02_term_1", "modI": 0, "term": "Gene", "def": "基因：合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列，通常为DNA序列（RNA病毒中为RNA）。要点：①1909年Johannsen提出“基因”一词；②强调功能单位，而非仅一段可读框；③最终产物可为多肽或RNA；④若产物为多肽，需经转录和翻译；⑤若产物为RNA，则该RNA本身即具结构、催化、识别或调控等功能。", "kp": "ch02_s0_1"}, {"id": "ch02_term_2", "modI": 0, "term": "Chromatin", "def": "染色质：真核细胞中DNA与组蛋白等结合形成的复合物。要点：①间期多为伸展的染色质；②细胞分裂时高度折叠压缩成染色体；③染色质与染色体是同一物质在不同细胞周期阶段的不同存在形式；④均以DNA为基本遗传物质。", "kp": null}, {"id": "ch02_term_3", "modI": 1, "term": "Nucleotide", "def": "核苷酸：由碱基、戊糖和磷酸组成，是核酸的基本结构单位。要点：①碱基与戊糖通过N-糖苷键连接形成核苷；②核苷再与磷酸通过磷酸酯键连接形成核苷酸；③过程中伴随脱水；④糖苷键和磷酸酯键是核酸一级结构中两类关键共价键。", "kp": "ch02_s1_1"}, {"id": "ch02_term_4", "modI": 1, "term": "Phosphodiester bond", "def": "3′,5′-磷酸二酯键：DNA多核苷酸链中相邻核苷酸之间的连接键。要点：①一个核苷酸的3′-OH与下一个核苷酸的5′-磷酸形成酯键；②构成DNA的共价骨架；③使链具有明确方向性，一端为5′端，另一端为3′端；④碱基序列携带遗传信息。", "kp": "ch02_s1_6"}, {"id": "ch02_term_5", "modI": 1, "term": "B-DNA", "def": "B型DNA：生理水溶液条件下DNA的主要双螺旋构象。要点：①右手螺旋；②两条反向平行的多核苷酸链围绕同一中心轴盘绕；③磷酸-脱氧核糖骨架位于外侧，碱基对位于内侧；④形成大沟和小沟；⑤直径约2 nm，每圈约10个碱基对，螺距约3.4 nm。", "kp": "ch02_s1_9"}, {"id": "ch02_term_6", "modI": 2, "term": "Supercoiling", "def": "超螺旋：DNA链所承受扭转应力的一种表现，通常指DNA相对于正常状态发生过度缠绕或缠绕不足。要点：①是同一DNA分子内的过度缠绕或缠绕不足；②使DNA更紧密，有利于包装；③分为正超螺旋和负超螺旋；④负超螺旋有利于解链，促进复制和转录；⑤复制和转录时解旋会产生正超螺旋压力。", "kp": "ch02_s2_1"}, {"id": "ch02_term_7", "modI": 2, "term": "Topoisomerase", "def": "拓扑异构酶：通过切断和重新连接DNA链来调节超螺旋水平的酶。要点：①拓扑异构酶I切割一条链并旋转；②拓扑异构酶II切割两条链并传递另一条双链通过；③改变连环数；④解决复制和转录中的拓扑压力；⑤维持DNA适当拓扑状态。", "kp": "ch02_s2_1"}, {"id": "ch02_term_8", "modI": 2, "term": "DNA denaturation", "def": "DNA变性（DNA熔解）：DNA双螺旋的两条链分离的过程。要点：①促进条件包括加热、低离子强度、高pH和有机溶剂；②氢键断裂，碱基堆积力被破坏，但共价键不受影响；③变性后260 nm紫外吸收增加，称为增色效应；④常用于检测DNA变性和复性。", "kp": "ch02_s2_10"}, {"id": "ch02_term_9", "modI": 2, "term": "Tm", "def": "熔解温度（Tm）：两条链半解离或变性的温度，即吸光值增加到最大值的一半时的温度。要点：①通过260 nm处吸光度增加来测量；②Tm值与GC含量正相关；③GC含量越高，Tm越高；④因为GC碱基对有三个氢键，比AT碱基对更稳定；⑤可用于估计DNA的GC含量和PCR引物设计。", "kp": "ch02_s2_7"}, {"id": "ch02_term_10", "modI": 3, "term": "Operon", "def": "操纵子：原核生物基因表达调控的典型单位。要点：①由Jacob和Monod提出；②通常由启动子、操纵基因和一组功能相关的结构基因组成；③受同一调控序列控制；④转录成多顺反子mRNA；⑤一个开关同时控制多个相关蛋白合成，提高效率并节约调控资源。", "kp": "ch02_s3_6"}, {"id": "ch02_term_11", "modI": 4, "term": "Plasmid", "def": "质粒：独立于染色体外、能自主复制的核酸分子。要点：①广义上可为DNA或RNA，存在于细菌、放线菌、真菌及一些动植物细胞中；②细菌中最常见，大多是环状双链DNA；③狭义上指细菌染色体外的小型环状双链DNA分子；④对宿主生存并非必需，但可赋予有利表型；⑤是基因工程中最重要的载体来源之一。", "kp": "ch02_s4_1"}, {"id": "ch02_term_12", "modI": 4, "term": "Nucleoid", "def": "类核：细菌细胞内DNA高度折叠形成的致密区域。要点：①没有核膜与细胞质分隔；②细菌核基因组一般由一条双链环状DNA分子组成；③只有一个复制起点；④保证整个基因组从一个位点起始复制；⑤使细菌能快速复制、转录和分裂。", "kp": "ch02_s4_1"}], "preview": {"main": "本章围绕遗传信息的物质基础展开，主线是“DNA→基因→基因组→染色体”的层次递进：先解析DNA的化学组成、双螺旋结构、拓扑性质与变复性等物理化学行为，再界定基因的概念与结构类型，进而比较细菌与真核基因组及质粒、转座因子等特征，最终理解DNA如何折叠压缩为染色质与染色体。", "questions": ["DNA双螺旋为什么能同时保证结构稳定和遗传信息可被读取？碱基堆积力、氢键和离子键各自贡献了什么？", "A-DNA、B-DNA和Z-DNA的主要差异是什么？为什么B-DNA是生理条件下的主要形式，而其他构象也有生物学意义？", "DNA超螺旋、拓扑构型和拓扑异构酶之间是什么关系？复制和转录过程中为什么会产生拓扑压力，细胞如何解决？", "DNA变性、复性和杂交的分子机制是什么？Tm值、GC含量和复性条件如何影响这些过程，并如何应用于PCR和杂交技术？", "基因的概念从“遗传因子”到现代分子定义经历了怎样的变化？蛋白编码基因与功能RNA基因、结构基因与调节基因分别有何区别？", "原核基因的操纵子、多顺反子mRNA和重叠基因与真核基因的断裂结构、单顺反子mRNA相比，体现了哪些不同的基因组织与表达策略？", "细菌基因组、质粒和真核基因组在结构、复制方式、重复序列和基因密度上有哪些关键差异？转座因子和质粒对遗传变异与适应有什么意义？"]}, "appcards": [{"front": "为什么说“基因是功能单位，而不是一段可任意切割的DNA序列”？请结合基因的现代定义说明。", "back": "现代定义：基因是合成一条有功能的多肽或RNA分子所必需的全部核苷酸序列。若产物是多肽，需经转录和翻译；若产物是RNA，则RNA本身即具结构、催化、识别或调控功能。因此基因的边界由“能否产生一个功能产物”决定，而不仅由序列长度或位置决定。", "points": "①点明基因定义；②区分多肽产物与RNA产物；③强调“功能产物”决定基因单位；④说明不能仅按序列任意切割。", "mod": 0, "modName": "模块一：染色质、染色体与基因的概念", "level": "掌握", "src": "生成"}, {"front": "染色质与染色体在真核细胞中为什么是“同一物质的不同存在形式”？请从细胞周期和分子组成角度解释。", "back": "二者均以DNA为基本遗传物质，并与组蛋白等结合。间期DNA伸展、参与复制与转录，表现为染色质；分裂期染色质高度折叠压缩，便于分离和分配，表现为染色体。因此差异主要是细胞周期阶段和包装程度不同，不是物质种类不同。", "points": "①说明二者基本成分相同；②指出间期多为染色质；③指出分裂期凝缩为染色体；④点明高度折叠压缩与细胞周期阶段差异。", "mod": 0, "modName": "模块一：染色质、染色体与基因的概念", "level": "掌握", "src": "生成"}, {"front": "学习“DNA→基因→基因组→染色体”这一层次递进关系有什么意义？请举例说明。", "back": "意义在于建立从化学载体到功能单位、再到全部遗传信息、最后到细胞组织形式的整体框架。例如：DNA是遗传信息化学载体；某基因是其中可产生多肽或RNA的功能序列；基因组是一个生物全部遗传信息总和；染色体则是DNA在细胞内的组织与包装形式。这样可避免把基因、基因组和染色体混为一谈。", "points": "①按DNA、基因、基因组、染色体依次说明；②突出层次递进；③给出至少一个具体例子；④指出有助于避免概念混淆。", "mod": 0, "modName": "模块一：染色质、染色体与基因的概念", "level": "掌握", "src": "生成"}, {"front": "若某基因的最终产物是RNA而不是蛋白质，其功能体现方式与编码蛋白质的基因有何不同？请举例说明。", "back": "编码蛋白质的基因需经转录和翻译，最终由多肽/蛋白质体现生理功能；最终产物为RNA的基因，其RNA本身即可具有结构、催化、识别或调控等功能，无需翻译。例如rRNA可参与核糖体结构，tRNA可识别密码子并转运氨基酸，某些调控RNA可参与基因表达调控。", "points": "①说明蛋白质基因需转录和翻译；②说明RNA基因无需翻译；③列出RNA本身功能如结构、催化、识别、调控；④举例rRNA、tRNA或调控RNA。", "mod": 0, "modName": "模块一：染色质、染色体与基因的概念", "level": "掌握", "src": "生成"}, {"front": "比较DNA与RNA在核苷酸组成上的差异，并说明这些差异对二者功能分工的意义。", "back": "差异：①糖不同——RNA含核糖（2′-OH），DNA含脱氧核糖（2′-H）；②碱基不同——RNA用尿嘧啶U替代DNA中的胸腺嘧啶T（T比U多一个甲基）。意义：2′-OH使RNA更易折叠、更易被降解，适合作为短寿命的功能分子（如mRNA、tRNA、rRNA）；DNA因缺少2′-OH更稳定，且T/U的甲基差异有利于修复系统识别（如识别C脱氨生成的U），故DNA更适合长期储存遗传信息。", "points": "糖差异（2′-OH vs 2′-H）；碱基差异（U vs T，T多甲基）；RNA易折叠易降解→功能分子；DNA稳定+修复识别→遗传储存", "mod": 1, "modName": "模块二：DNA的一级与二级结构", "level": "掌握", "src": "生成"}, {"front": "为什么说碱基互补配对是DNA复制、转录和分子杂交的基础？请结合氢键数目举例说明。", "back": "碱基互补使两条链序列互为模板：A与T形成2个氢键，G与C形成3个氢键，因此一条链的序列可决定另一条链的序列。复制时，亲链作为模板按A-T、G-C规则合成子链；转录时，以DNA为模板按A-U、T-A、G-C规则合成RNA；分子杂交（如Southern、PCR、探针杂交）中，探针与目标序列通过互补配对形成稳定双链。G-C含量越高，氢键越多，双链越稳定，解链温度越高。", "points": "A-T 2个氢键，G-C 3个氢键；模板决定序列；复制/转录/杂交均依赖互补配对；G-C含量影响稳定性与Tm", "mod": 1, "modName": "模块二：DNA的一级与二级结构", "level": "掌握", "src": "生成"}, {"front": "维持DNA双螺旋稳定的因素有哪些？其中哪一因素贡献最大？请说明各因素的作用机制。", "back": "四类作用：①碱基对间氢键——保证配对特异性；②碱基堆积力（疏水相互作用+范德华力）——对稳定性贡献最大，源于碱基芳香环间的疏水堆积；③磷酸骨架负电荷与介质中阳离子的离子键——屏蔽静电排斥，维持骨架电荷平衡；④碱基分子内能。共同决定DNA的稳定性与解链行为。", "points": "氢键（特异性）；碱基堆积力（贡献最大）；离子键（屏蔽静电排斥）；碱基分子内能；共同决定稳定性与解链行为", "mod": 1, "modName": "模块二：DNA的一级与二级结构", "level": "掌握", "src": "生成"}, {"front": "DNA存在A-DNA、B-DNA、Z-DNA等多种构象，请比较其特点并举例说明其生物学意义。", "back": "特点：B-DNA为右手螺旋，是生理水溶液条件下的主要形式，直径约2 nm，每圈约10 bp，螺距约3.4 nm；A-DNA为右手螺旋，在低水合条件下有利，RNA-DNA杂交链和双链RNA常采用A型几何；Z-DNA为左手螺旋，形成依赖特定序列（如交替嘌呤-嘧啶）和拓扑压力。影响因素包括核苷酸顺序、碱基组成、盐种类、相对湿度（水合程度）及拓扑压力。意义：蛋白质可识别特定DNA构象，参与复制、转录、重组和基因表达调控；结构多样性提示DNA在细胞内并非静态，可随环境与功能需要发生构象变化。", "points": "B-DNA右手、生理主要形式（2 nm/10 bp/3.4 nm）；A-DNA低水合、RNA-DNA杂交与双链RNA；Z-DNA左手、特定序列+拓扑压力；影响因素（序列/盐/水合/拓扑）；蛋白质识别构象→调控意义", "mod": 1, "modName": "模块二：DNA的一级与二级结构", "level": "掌握", "src": "生成"}, {"front": "真核生物线性DNA与细菌质粒cccDNA在拓扑约束上有何不同？这种差异对DNA复制和转录有何影响？", "back": "cccDNA（如质粒、环状细菌染色体）两条链共价闭合，无自由末端，连环数固定，是受拓扑约束的典型；真核线性DNA虽无共价闭合，但因长度极长且与染色质蛋白及核基质相互作用，同样受到拓扑约束。影响：受约束的DNA在复制/转录解旋时无法通过自由旋转释放张力，会积累正超螺旋，阻碍复制叉和RNA聚合酶推进，因此必须依赖拓扑异构酶调节拓扑状态。", "points": "cccDNA共价闭合、连环数固定；真核线性DNA因长度和染色质相互作用受约束；拓扑约束导致复制转录时积累正超螺旋；需拓扑异构酶解除。", "mod": 2, "modName": "模块三：DNA的三级结构（拓扑）与理化性质", "level": "掌握", "src": "生成"}, {"front": "DNA复制过程中为什么会产生拓扑压力？细胞如何解决这一问题？请结合拓扑异构酶I和II的作用机制说明。", "back": "复制时解旋酶解开双链，复制叉前方未解链部分缠绕更紧，形成正超螺旋压力，使解链不能继续。解决：拓扑异构酶I切割一条链，使链旋转后再连接，改变连环数；拓扑异构酶II切割两条链，让另一条双链通过切口后再连接，改变连环数。二者释放张力，保证复制叉顺利推进。", "points": "解旋酶解链导致前方正超螺旋积累；拓扑异构酶I切一条链旋转再连接；拓扑异构酶II切两条链、传递双链通过；释放张力保证复制叉推进。", "mod": 2, "modName": "模块三：DNA的三级结构（拓扑）与理化性质", "level": "掌握", "src": "生成"}, {"front": "为什么细胞内的DNA通常处于负超螺旋状态？负超螺旋对DNA的复制、转录和包装有何生物学意义？", "back": "负超螺旋是缠绕不足，DNA链承受扭转应力，有利于双链解开。意义：①促进复制和转录，因为解链更容易；②真核生物中核小体形成引入负超螺旋，帮助长链DNA压缩包装；③与DNA重组和修复密切相关。拓扑异构酶可松弛超螺旋，维持适当拓扑状态。", "points": "负超螺旋为缠绕不足、利于解链；促进复制转录；核小体引入负超螺旋帮助压缩；参与重组修复；拓扑异构酶维持适当拓扑水平。", "mod": 2, "modName": "模块三：DNA的三级结构（拓扑）与理化性质", "level": "掌握", "src": "生成"}, {"front": "DNA变性与复性分别受哪些因素影响？如何利用Tm和增色效应进行PCR引物设计或GC含量估算？", "back": "变性条件：加热、低离子强度、高pH、有机溶剂；氢键断裂、碱基堆积力破坏，共价键不断，260 nm吸收增加（增色效应）。复性影响因素：温度（比Tm低约25℃最佳）、DNA浓度（越高越快）、复性时间（降温要慢）、DNA复杂度（越小越单一越快）。应用：Tm与GC含量正相关，GC越高Tm越高；测Tm可估算GC含量，反之可据GC含量设计PCR引物退火温度。", "points": "变性条件与增色效应；复性受温度、浓度、时间、复杂度影响；Tm与GC含量正相关；用于估算GC含量和PCR引物设计。", "mod": 2, "modName": "模块三：DNA的三级结构（拓扑）与理化性质", "level": "掌握", "src": "生成"}, {"front": "原核生物的多顺反子mRNA与真核生物的单顺反子mRNA在结构上有何主要区别？这种差异对基因表达调控各有什么意义？", "back": "区别：原核mRNA一个分子含多个ORF，可翻译多条多肽链；真核mRNA一个分子只含一个ORF，只翻译一条多肽链。意义：原核多顺反子使功能相关基因（如操纵子中代谢途径的酶基因）同步协调表达，提高调控效率；真核单顺反子使每个基因可独立调控，有利于复杂发育和细胞分化。", "points": "答出原核多ORF/多肽链；答出真核单ORF/单肽链；答出原核同步协调、高效调控；答出真核独立调控、利于分化发育。", "mod": 3, "modName": "模块四：基因的分类与结构", "level": "掌握", "src": "生成"}, {"front": "为什么线粒体基因和叶绿体基因被称为“半自主性”基因？请结合其复制与表达所需条件说明。", "back": "线粒体和叶绿体基因组能进行一定程度的自主复制和表达，但自主程度有限；许多功能蛋白由核基因编码，其复制与表达部分依赖核基因编码的蛋白。因此它们既不是完全自主，也不是完全受核控制，称为半自主性。", "points": "答出细胞器基因组可部分自主复制/表达；答出许多功能蛋白由核基因编码；答出复制表达依赖核基因产物；结论为半自主性。", "mod": 3, "modName": "模块四：基因的分类与结构", "level": "掌握", "src": "生成"}, {"front": "真核基因的断裂结构（外显子与内含子交替）有什么生物学意义？请从遗传信息容量和蛋白质多样性角度举例说明。", "back": "真核基因由外显子和内含子交替组成，转录后经剪接去除内含子。意义：断裂结构使真核基因可通过可变剪接产生多种mRNA和蛋白质，极大扩展遗传信息容量，是蛋白质多样性的重要基础。例如同一前体mRNA经不同剪接可生成不同成熟mRNA，翻译出功能不同的蛋白。", "points": "答出外显子编码、内含子非编码；答出转录后剪接；答出可变剪接；答出扩展遗传信息容量/增加蛋白质多样性；有举例更好。", "mod": 3, "modName": "模块四：基因的分类与结构", "level": "掌握", "src": "生成"}, {"front": "质粒作为细胞质基因的典型代表，在细菌生存和基因工程中分别有什么应用价值？", "back": "质粒是染色体或拟核以外的DNA分子，具有自主复制能力，可赋予宿主菌抗药性、产毒素等性状，有利于细菌在特定环境中生存。在基因工程中，质粒可作为重要载体，用于携带和扩增外源DNA。", "points": "答出质粒位于染色体/拟核外；答出自主复制；答出赋予宿主抗药性/产毒素等性状；答出基因工程载体应用。", "mod": 3, "modName": "模块四：基因的分类与结构", "level": "掌握", "src": "生成"}, {"front": "为什么细菌基因组能够实现快速复制、转录和分裂？请从细菌核基因组的结构特征角度说明原因机制。", "back": "细菌核基因组一般为一条双链环状DNA，只有一个复制起点，复制从单一原点起始，便于快速完成整个基因组复制；DNA高度折叠形成类核，无核膜与细胞质分隔，使复制、转录和翻译可在同一区域高效进行；基因组小、结构紧凑、基因密度高，进一步减少复制负担。这些特征共同保证细菌快速繁殖。", "points": "环状双链DNA；单一复制起点；类核无核膜分隔；基因组小且紧凑；复制转录高效", "mod": 4, "modName": "模块五：基因组——细菌基因组与质粒", "level": "掌握", "src": "生成"}, {"front": "细菌结构基因通常连续、无内含子，且重复序列少，但rRNA基因常为多拷贝。请解释这种组织方式的生物学意义。", "back": "结构基因连续且无内含子，使转录后一般不需要剪接，可快速产生成熟mRNA并翻译成蛋白质，适应细菌快速生长。重复序列少、结构基因多为单拷贝，有利于基因组经济高效。rRNA基因多拷贝则是因为细菌繁殖快、蛋白质合成需求大，需要大量核糖体，多拷贝rRNA基因可保证rRNA高效转录，满足翻译需求。", "points": "无内含子→无需剪接、快速表达；重复少、单拷贝→经济高效；rRNA多拷贝→满足核糖体需求；适应快速生长", "mod": 4, "modName": "模块五：基因组——细菌基因组与质粒", "level": "掌握", "src": "生成"}, {"front": "质粒对宿主并非必需，却能在细菌群体中稳定存在并具有选择优势。请比较质粒的寄生性、依赖性与选择优势，并举例说明。", "back": "质粒对宿主生存非必需，像借居者，通常不杀伤细胞，也不明显影响宿主代谢，宿主失去质粒仍可生存，体现寄生性；但质粒离开宿主不能独立生存，必须依赖宿主的酶和蛋白质完成复制与转录，体现依赖性；质粒可赋予宿主有利表型，如抗生素抗性，体现选择优势。例如Ampr可水解β-内酰胺环解除氨苄毒性，Tetr可阻止四环素进入细胞，使宿主在相应抗生素环境中存活。", "points": "寄生性：非必需、不杀伤、可失去；依赖性：依赖宿主酶和蛋白复制转录；选择优势：赋予有利表型；举例：Ampr、Tetr", "mod": 4, "modName": "模块五：基因组——细菌基因组与质粒", "level": "掌握", "src": "生成"}, {"front": "质粒常被改造为基因工程载体。请说明质粒作为载体应具备哪些特点，并举例说明其应用。", "back": "质粒作为基因工程载体应具备三个特点：能独立自主复制，保证外源基因在宿主中扩增；便于检测，如带抗生素抗性筛选标记；容易导入宿主细胞，也易从宿主细胞中分离纯化。应用中可人工构建质粒，加入多克隆位点、筛选标记和调控元件，把外源基因送入宿主细胞进行克隆扩增或表达。", "points": "独立自主复制；便于检测如抗性筛选；易导入和分离纯化；人工构建多克隆位点、筛选标记、调控元件；用于克隆扩增或表达", "mod": 4, "modName": "模块五：基因组——细菌基因组与质粒", "level": "掌握", "src": "生成"}, {"front": "真核生物基因组大小与物种复杂性总体呈正相关，但存在“C值悖论”。请比较原核与真核基因组在基因密度和非编码区比例上的差异，并解释真核基因组为何需要如此庞大的非编码序列。", "back": "差异：原核基因组基因排列紧凑，基因密度高，甚至存在重叠基因，非编码区比例低；真核基因组庞大，编码区通常不足10%，90%以上为非编码序列，基因密度低，基因间间隔大量非编码DNA。原因/意义：庞大的非编码序列并非“垃圾”，其中包含调控元件、重复序列、内含子等，参与基因表达调控、染色体结构维持和进化；同时为真核生物复杂的发育调控和遗传信息容量扩展提供序列基础。", "points": "原核基因紧凑、密度高、可重叠；真核编码区<10%、非编码>90%、基因密度低；非编码区含调控元件、重复序列、内含子；参与表达调控、染色体结构、进化；为发育复杂性提供基础。", "mod": 5, "modName": "模块六：真核生物基因组", "level": "掌握", "src": "生成"}, {"front": "真核基因组含有大量重复序列。请比较串联重复序列与散在重复序列在排列方式、典型类型、分布区域和主要功能上的不同，并举例说明。", "back": "串联重复序列：首尾相连成簇分布，包括卫星DNA、小卫星DNA、微卫星DNA，常位于着丝粒、端粒等异染色质区，与染色体结构和稳定性有关。散在重复序列：分散分布于基因组中，典型代表为转座元件，可移动或曾具有移动能力，影响基因组大小、结构和进化。二者拷贝数、分布和功能不同，共同塑造真核基因组复杂结构。", "points": "串联重复：首尾相连成簇；卫星/小卫星/微卫星；着丝粒、端粒等异染色质区；染色体结构与稳定性。散在重复：分散分布；转座元件；可移动或曾移动；影响基因组大小、结构、进化。", "mod": 5, "modName": "模块六：真核生物基因组", "level": "掌握", "src": "生成"}, {"front": "转座元件是真核重复序列的重要组成部分。请比较复制型转座与剪切型转座在转座机制、原拷贝是否保留、拷贝数变化及常见代表上的差异，并说明大多数转座子为何不活跃“跳跃”。", "back": "复制型转座为“复制-粘贴”：转座子先转录为RNA，再逆转录为DNA，插入新位点，原拷贝保留，拷贝数增加，常见于逆转录转座子。剪切型转座为“剪切-粘贴”：转座酶将转座子从原位置切下并插入新位点，原位置丢失，拷贝数通常不增加，属于DNA型转座。大多数转座子因突变积累或表观遗传机制如DNA甲基化、组蛋白修饰而被沉默，只有少数仍具转座活性。", "points": "复制型：复制-粘贴；RNA→逆转录DNA；原拷贝保留；拷贝数增加；逆转录转座子。剪切型：剪切-粘贴；转座酶切下插入；原位置丢失；拷贝数通常不增加；DNA型转座。沉默原因：突变积累、DNA甲基化、组蛋白修饰等表观遗传机制。", "mod": 5, "modName": "模块六：真核生物基因组", "level": "掌握", "src": "生成"}, {"front": "断裂基因是真核生物基因组的重要特征。请说明外显子与内含子的区别，并解释断裂基因和可变剪接对真核生物遗传信息容量与蛋白质多样性的意义。", "back": "断裂基因指编码蛋白质的基因序列被非编码插入序列隔开。外显子是最终保留在成熟mRNA中的编码或非编码区段；内含子在转录后剪接过程中被切除。意义：断裂基因是真核生物与原核生物基因组的主要区别之一；同一前体mRNA可通过可变剪接产生多种mRNA和蛋白质，极大扩展遗传信息容量，增加蛋白质多样性，是真核生物进化与发育复杂性的重要基础。", "points": "断裂基因：编码序列被非编码插入序列隔开。外显子：保留在成熟mRNA中；内含子：剪接时被切除。可变剪接：同一前体mRNA产生多种mRNA和蛋白质。意义：扩展遗传信息容量、增加蛋白质多样性、真核进化与发育复杂性基础。", "mod": 5, "modName": "模块六：真核生物基因组", "level": "掌握", "src": "生成"}, {"front": "为什么说DNA必须被高度压缩？请结合人体DNA总长度与细胞核大小的关系说明DNA包装的必要性。", "back": "人体二倍体细胞约含2套基因组，每套约3.4×10⁹ bp，每个碱基对长度约0.332 nm，人体约1×10¹⁴个细胞，总DNA长度约2.26×10¹¹ km，约为地球到太阳距离的1500个来回。如此长的DNA必须被高度压缩才能容纳于细胞核内，因此DNA需要与组蛋白等结合形成染色质，并在分裂期进一步压缩为染色体。", "points": "①碱基对长度0.332 nm；②人类基因组3.4×10⁹ bp；③二倍体2套基因组；④总长度约2.26×10¹¹ km；⑤结论：DNA必须高度压缩以适应细胞核空间", "mod": 6, "modName": "模块七：染色体与DNA包装（核小体）", "level": "掌握", "src": "生成"}, {"front": "染色质与染色体有何区别和联系？DNA包装成染色体对细胞有什么重要意义？", "back": "染色质是DNA与其结合蛋白形成的复合物，存在于间期，结构较松散；染色体是细胞分裂期染色质高度压缩形成的结构。二者是同一物质在不同细胞周期阶段的不同存在形式。DNA包装成染色体的意义包括：便于将DNA装入细胞；保护DNA免受损伤；细胞分裂时高效传递给两个子细胞；赋予每个DNA分子整体组织形式，有利于基因表达、DNA复制、修复及重组。", "points": "①染色质：DNA与蛋白复合物，间期松散；②染色体：分裂期高度压缩形式；③二者为同一物质不同时期状态；④意义：压缩装入、保护、传递、组织化利于复制表达修复重组", "mod": 6, "modName": "模块七：染色体与DNA包装（核小体）", "level": "掌握", "src": "生成"}, {"front": "请比较原核生物染色体与真核生物染色体在结构、基因密度和非编码序列方面的主要差异，并说明这些差异的意义。", "back": "原核生物染色体通常为环状，如大肠杆菌染色体中央约20%由RNA和核心蛋白组成帮助DNA盘曲，外围约80%为双链DNA超螺旋，扭结成约100个相对独立的拓扑结构域；基因组几乎全部由基因组成，基因密度极高。真核生物染色体为线状，基因密度较低，存在大量非编码序列，包括调控序列、重复序列和内含子等。这些差异反映了真核生物基因表达调控更复杂，也与生物进化、基因组复杂性和生活方式相关。", "points": "①原核：环状、超螺旋、约100个拓扑结构域、基因密度高；②真核：线状、非编码序列多、基因密度低；③意义：真核调控更复杂，与进化和生活方式相关", "mod": 6, "modName": "模块七：染色体与DNA包装（核小体）", "level": "掌握", "src": "生成"}, {"front": "请描述核小体的结构组成，并说明H1组蛋白在染色质高级结构形成中的作用。", "back": "核小体是染色质的基本结构单位，由组蛋白八聚体和约146 bp DNA组成。组蛋白八聚体由1个H3-H4四聚体和2个H2A-H2B二聚体组成，H3-H4四聚体位于中央，两个H2A-H2B二聚体位于两侧。DNA缠绕在组蛋白八聚体表面约1.67圈，形成盘状核心颗粒，使DNA长度压缩约6倍。相邻核小体由连接DNA相连。H1为连接组蛋白，结合在核小体之间的连接DNA上，锁住核小体DNA的进出端，稳定核小体结构，并促进30 nm纤维等染色质高级结构的形成。", "points": "①核小体=组蛋白八聚体+约146 bp DNA；②八聚体=1个H3-H4四聚体+2个H2A-H2B二聚体；③DNA缠绕约1.67圈，压缩约6倍；④H1结合连接DNA，锁住进出端；⑤H1稳定核小体并促进高级结构形成", "mod": 6, "modName": "模块七：染色体与DNA包装（核小体）", "level": "掌握", "src": "生成"}, {"front": "组蛋白变体与常规组蛋白在染色质中的分布和功能有何不同？请举例说明两类组蛋白变体的功能差异。", "back": "组蛋白变体是标准组蛋白的替代形式，可在特定染色质区域替换常规组蛋白，改变核小体性质与功能。例如：H2A.Z 富集于启动子和调控区，影响核小体稳定性并参与转录调控；H2A.X 广泛分布，DNA 双链断裂后被磷酸化为 γ-H2A.X，作为 DNA 损伤标记参与修复；macroH2A 见于沉默染色质和失活 X 染色体，参与转录抑制；H3.3 可在不依赖 DNA 复制的情况下装配，常与活跃转录相关；CENP-A 是 H3 变体，特异掺入着丝粒区域，形成着丝粒特异性核小体，为动粒蛋白提供结合平台，确保染色体正确分离。", "points": "①组蛋白变体定义：标准组蛋白的替代形式，可改变核小体性质与功能；②举例 H2A.Z、H2A.X、macroH2A、H3.3、CENP-A 中至少两类；③说明其分布或功能差异；④CENP-A 与着丝粒身份、动粒平台、染色体分离的关系。", "mod": 7, "modName": "模块八：组蛋白变体、高级结构与组蛋白修饰", "level": "掌握", "src": "生成"}, {"front": "30 nm 染色质纤维是如何形成的？H1 在其中起什么作用？目前对其组装模型有哪些主要观点？", "back": "H1 是连接组蛋白，结合在核小体核心颗粒之间的连接 DNA 上，帮助稳定高级结构，促进核小体阵列折叠成 30 nm 染色质纤维。30 nm 纤维使 DNA 进一步缩短，有利于遗传物质在细胞核内高度组织化包装，同时影响基因表达可及性。关于 30 nm 纤维组装主要有两种模型：螺线管模型认为核小体沿中心轴螺旋排列，形成规则中空螺旋；之字形模型认为核小体以锯齿状方式折叠，相邻核小体通过连接 DNA 和 H1 相互作用。两种模型均试图解释核小体阵列如何压缩成 30 nm 纤维，但具体机制仍存在争议，取决于染色质条件和实验方法。", "points": "①H1 结合连接 DNA；②H1 促进核小体阵列折叠成 30 nm 纤维；③30 nm 纤维意义：进一步压缩 DNA、影响可及性；④螺线管模型；⑤之字形模型；⑥两种模型存在争议。", "mod": 7, "modName": "模块八：组蛋白变体、高级结构与组蛋白修饰", "level": "掌握", "src": "生成"}, {"front": "什么是组蛋白修饰的写入器、阅读器和擦除器？请举例说明它们如何协同实现表观遗传调控。", "back": "组蛋白修饰由三类功能蛋白协同调控：写入器是添加修饰标记的酶，如组蛋白乙酰转移酶和甲基转移酶；阅读器是识别并结合修饰标记的蛋白，将修饰信息转化为下游功能，如溴结构域识别乙酰化赖氨酸，染色质结构域和 PHD 指结构域识别甲基化赖氨酸，14-3-3 蛋白识别磷酸化丝氨酸；擦除器是去除修饰标记的酶，如去乙酰化酶和去甲基化酶。这种动态调控使组蛋白修饰能够灵活响应细胞信号，精确控制基因表达。", "points": "①写入器定义并举例乙酰转移酶、甲基转移酶；②阅读器定义并举例溴结构域、染色质结构域、PHD 指、14-3-3；③擦除器定义并举例去乙酰化酶、去甲基化酶；④协同动态调控基因表达。", "mod": 7, "modName": "模块八：组蛋白变体、高级结构与组蛋白修饰", "level": "掌握", "src": "生成"}, {"front": "组蛋白乙酰化为什么能使染色质松散并暴露 DNA 位点？这一过程如何与核小体重塑协同调控基因表达？", "back": "组蛋白乙酰化中和赖氨酸残基的正电荷，降低组蛋白与 DNA 的亲和力，使染色质结构变得松散。同时，核小体重塑复合物可移动核小体，进一步改变核小体位置。这些变化使原先被遮挡的 DNA 位点暴露出来，允许新的调控蛋白结合，从而激活或抑制转录。该过程展示了组蛋白修饰与核小体重塑协同调控基因表达可及性的机制。此外，Allis 和 Strahl 提出的组蛋白密码假说认为，多种组蛋白修饰以组合或顺序方式作用于一个或多个组蛋白尾部，指定独特的下游功能，强调修饰的组合性和上下文依赖性。", "points": "①乙酰化中和赖氨酸正电荷；②降低组蛋白与 DNA 亲和力；③染色质松散；④核小体重塑复合物移动核小体；⑤暴露 DNA 位点，允许调控蛋白结合；⑥影响转录；⑦可联系组蛋白密码假说。", "mod": 7, "modName": "模块八：组蛋白变体、高级结构与组蛋白修饰", "level": "掌握", "src": "生成"}]};